"use strict";exports.id=8024,exports.ids=[8024],exports.modules={98024:(a,b,c)=>{c.d(b,{A:()=>A});let d="/images/google-workspace/module-1",e=(a,b)=>b.map((b,c)=>({src:`${d}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),f=[{slug:"what-is-google-workspace",title:"What Google Workspace Is",description:"Meet the Google Workspace apps, learn how a personal Google account differs from a work account, and see how each Google app lines up with the Microsoft 365 app you may already know.",objectives:["Name the main Google Workspace apps and what each one is used for at work","Explain how a personal Google account differs from a work or school Google Workspace account","Match each Google app to the Microsoft 365 app that does the same job","Describe three habits of cloud apps: changes save on their own, you share a link instead of an attachment, and your files open on any computer"],duration:"20 min",videoUrl:"https://www.youtube.com/embed/chz7N054NAc",slides:e("what-is-google-workspace",["What Google Workspace is: Google's apps for work, all in the browser","The apps you will use: Gmail and Calendar, Drive, Docs, Sheets, Slides, Meet and Chat","Personal Google account or work account: who sets it up and what changes","Google Workspace and Microsoft 365, app by app","Three habits of cloud apps: automatic saving, sharing a link, any computer","Quick check: which app would you open?"]),sections:[{heading:"Your first day at Parkview",blocks:[{type:"scenario",role:"You are Jordan Lee, the new office assistant at Parkview Property Management.",text:"Parkview manages two apartment buildings, Elm Street Apartments and Riverside Commons. The office runs on Google Workspace: tenant letters are in Google Docs, the maintenance request log is a Google Sheet, and the staff talks over Gmail and Google Meet. Your manager, Denise Carter, set up your work account (jlee@parkviewpm.example) and wants you to know your way around before your first tenant walks in.",task:"Know what each Google Workspace app is for, what kind of account you have, and how the Google apps compare with Microsoft Office."},{type:"paragraph",text:"Google Workspace is Google's set of apps for work and school: Gmail, Google Calendar, Google Drive, Google Docs, Google Sheets, Google Slides, Google Meet, Google Chat, Google Forms, and more. They run in a web browser, so there is nothing to install on the computer. You sign in with one Google account and every app is there."},{type:"callout",variant:"info",text:"Google Workspace was called G Suite until October 2020. If a coworker or a job posting says G Suite, they mean the same apps."},{type:"key-terms",terms:[{term:"Google account",definition:"The sign-in you use for every Google app. It can be a personal account you create yourself or a work or school account your organization gives you."},{term:"Google Workspace",definition:"Google's apps for work and school (Gmail, Calendar, Drive, Docs, Sheets, Slides, Meet, Chat, Forms, and others), managed by an organization."},{term:"Cloud app",definition:"An app that runs in a web browser and keeps your files on the internet instead of on one computer."},{term:"Google Drive",definition:"Google's cloud storage. Every Doc, Sheet, and Slides file you make is saved in Drive."},{term:"Administrator (admin)",definition:"The person or IT team who manages your organization's Google Workspace accounts and settings."}]}]},{heading:"The apps you will use",blocks:[{type:"table",caption:"Google Workspace apps at Parkview Property Management",columns:["App","What it does","At Parkview"],rows:[["Gmail","Email","Answer tenant questions and send notices"],["Google Calendar","Schedules and meetings","Book apartment showings and staff meetings"],["Google Drive","Stores and shares files","Keep every lease form, letter, and log in shared folders"],["Google Docs","Word processing","Write the tenant welcome letter and building notices"],["Google Sheets","Spreadsheets","Track maintenance requests, rent payments, and supplies"],["Google Slides","Presentations","Build the new-tenant orientation slideshow"],["Google Meet and Google Chat","Video meetings and team messaging","Meet with the property manager who works at the other building"],["Google Forms","Forms and surveys","Collect maintenance requests from tenants online"]]},{type:"paragraph",text:"This course teaches Drive, Docs, and Sheets first, because almost every office task starts with a file. Later modules cover Slides, Gmail, Calendar and Meet, and working together across the apps."}]},{heading:"Personal account or work account?",blocks:[{type:"paragraph",text:"Anyone can create a free personal Google account (an address that ends in @gmail.com). A work or school account is created by an organization that pays for Google Workspace, and it usually uses the organization's own email address, like jlee@parkviewpm.example. The apps look almost the same. What changes is who is in charge of the account."},{type:"table",caption:"Personal Google account compared with a work or school account",columns:["","Personal Google account","Work or school account"],rows:[["Who creates it","You do","Your organization's administrator"],["Email address","Usually ends in @gmail.com","Usually the organization's address (@parkviewpm.example)"],["Storage","15 GB free, shared by Gmail, Drive, and Google Photos","Set by the organization's plan"],["Who controls settings","You","The administrator, who can turn features on or off"],["Sharing","With specific people or anyone with the link","Also with everyone in the organization, and admins can limit outside sharing"],["Who owns the files","You","The organization. When you leave the job, the account and its files stay with the company"]]},{type:"drag-drop",mode:"sort",title:"Personal or work account?",prompt:"Drag each statement to the kind of account it describes.",buckets:[{id:"personal",label:"Personal Google account"},{id:"work",label:"Work or school account"}],items:[{id:"a",text:"Jordan created it at home with an @gmail.com address",bucket:"personal"},{id:"b",text:"The administrator turned off sharing outside the company",bucket:"work"},{id:"c",text:"Its 15 GB of free storage is shared by Gmail, Drive, and Photos",bucket:"personal"},{id:"d",text:"The files stay with the company when the employee leaves",bucket:"work"},{id:"e",text:"The address ends in @parkviewpm.example",bucket:"work"},{id:"f",text:"Only the account holder decides which features are on",bucket:"personal"}],explanation:"Ask who set up the account. If you created it, it is personal and you control it. If your employer or school created it, it is a work or school account, the organization controls it, and work files belong there, not in your personal account."},{type:"callout",variant:"warning",text:"Keep work files in your work account. Do not download company files to your personal Google account or share them from it, even to work from home. If you need access from home, ask how your employer wants you to sign in."}]},{heading:"Google Workspace and Microsoft 365",blocks:[{type:"paragraph",text:"Microsoft 365 (Word, Excel, PowerPoint, Outlook, OneDrive, and Teams) and Google Workspace do the same jobs. Many offices use one; plenty use both, for example Google Workspace for daily work and Word for a letter that must match a printed letterhead. If you already know a Microsoft app, most of what you know carries over."},{type:"table",caption:"Which app does the same job",columns:["Google Workspace","Microsoft 365"],rows:[["Google Drive","OneDrive (and SharePoint for team files)"],["Google Docs","Word"],["Google Sheets","Excel"],["Google Slides","PowerPoint"],["Gmail and Google Calendar","Outlook"],["Google Meet and Google Chat","Microsoft Teams"],["Google Forms","Microsoft Forms"]]},{type:"image",src:`${d}/what-is-google-workspace/google-and-microsoft.png`,alt:"Quick reference: Google Workspace apps and their Microsoft 365 matches, and the differences that matter at work",caption:"Quick reference you can keep: Google and Microsoft apps side by side."},{type:"drag-drop",mode:"match",title:"Match the apps",prompt:"Drag each Microsoft 365 app onto the Google app that does the same job.",items:[{id:"m1",text:"Google Docs",match:"Word"},{id:"m2",text:"Google Sheets",match:"Excel"},{id:"m3",text:"Google Slides",match:"PowerPoint"},{id:"m4",text:"Google Drive",match:"OneDrive"},{id:"m5",text:"Google Meet",match:"Microsoft Teams"}],explanation:"The pairs do the same job. In each pair, the Google app runs in the browser, saves on its own, and shares by link."}]},{heading:"Three habits of cloud apps",blocks:[{type:"list",ordered:!0,items:["Changes save on their own. Docs, Sheets, and Slides save every change to Google Drive as you type. There is no Save button. Version history keeps earlier versions in case you need to go back.","You share a link, not an attachment. Instead of emailing a copy, you share the file, and everyone works in the same one at the same time. You decide who can view, comment, or edit.","Your files open on any computer. Sign in on any computer with a web browser and your files are there. That is also why you must sign out on a shared computer."]},{type:"worked-example",title:"Why Denise never emails the maintenance log",task:"Three people update the maintenance request log during the day.",steps:[{move:"Keep one Google Sheet in the shared Maintenance folder in Drive.",why:"If each person emailed copies back and forth, nobody would know which copy is current."},{move:"Share the sheet with Kim and Marcus as editors.",why:"Sharing gives people access to the one real file instead of making new copies."},{move:"Let everyone type into it at the same time.",why:"Sheets saves every change for everyone, so the log is always up to date."}],result:"One current log that the whole team can see and update from any computer.",takeaway:"In Google Workspace, keep one file and share it. Copies are for people outside the team who need a finished version."},{type:"callout",variant:"info",text:"Some Google accounts include Gemini, Google's AI assistant, which shows up as an Ask Gemini button in apps such as Docs. It needs an eligible Google Workspace or Google AI plan, and many employers turn it off or limit it. Nothing in this course requires it. If your job lets you use it, read and check everything it writes before you share it."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Denise asks you to track tenant maintenance requests so three coworkers can update the list during the day. Which app fits best?",options:["Google Docs","Google Sheets","Google Slides","Google Meet"],correctIndex:1,explanation:"A list with columns (date, apartment, problem, status) that several people update is a spreadsheet job. Google Sheets keeps one shared, current copy.",optionRationales:["Docs is for letters and notices. A list that needs sorting and filtering belongs in a spreadsheet.","Correct. Sheets is built for lists and logs, and several people can edit it at the same time.","Slides is for presentations, not for a list people update all day.","Meet is for video meetings. It does not store the list."]},{type:"knowledge-check",question:"What is true about saving in Google Docs?",options:["Press Ctrl+S every few minutes or you lose your work","Changes are saved to Google Drive automatically as you work","You must download the file to save it","Only the owner's changes are saved"],correctIndex:1,explanation:"Docs, Sheets, and Slides save every change to Drive as you work. There is no Save button, and version history keeps earlier versions.",optionRationales:["That is a Word habit. Google's editors save on their own.","Correct. Every change is saved to Drive automatically.","Downloading makes a separate copy. The file in Drive is already saved.","Every editor's changes are saved, and version history shows who changed what."]},{type:"knowledge-check",question:"Your Parkview account is jlee@parkviewpm.example. Who controls which features it has?",options:["You do","Google support","Parkview's Google Workspace administrator","Anyone you share a file with"],correctIndex:2,explanation:"A work account is managed by the organization. Its administrator can turn features on or off and set sharing rules.",optionRationales:["You control a personal account. A work account is managed by your organization.","Google provides the apps, but your organization's admin manages the account settings.","Correct. The admin manages work accounts, including sharing rules and features.","Sharing a file never gives someone control of your account."]}]}],challenge:[{type:"paragraph",text:"Look around Google Workspace in your own account. A free personal Google account works for this."},{type:"list",ordered:!0,items:["Go to drive.google.com and sign in.","Click the Google apps menu (the grid of dots at the top right). Write down six apps you see.","Open Docs and then Sheets from the Google apps menu. Look at the home screen of each: Start a new document (or spreadsheet), the Template gallery, and your recent files.","For each of these Parkview jobs, write the app you would use and one sentence why: a building notice for the lobby, a list of apartments due for smoke detector checks, a video call with the property manager at the other building.","If you are on a shared computer, sign out: click your profile picture at the top right, then Sign out."]},{type:"callout",variant:"success",text:"Deliverable: Submit your list of six apps and your three app choices with reasons to your instructor or course folder. If you cannot sign in to a Google account, complete the practice simulation in this lesson and submit its results page (use Print or save results on the finish card)."}]},{slug:"signing-in-and-staying-secure",title:"Signing In and Keeping Your Account Safe",description:"Sign in to your Google account, approve a 2-Step Verification prompt, and sign out the right way on a shared or public computer.",objectives:["Sign in to a Google account in a web browser","Explain 2-Step Verification and approve, or block, a sign-in prompt on your phone","Sign out when you finish on a shared computer, and use a private browsing window on a public one","Find the Security & sign-in page in your Google Account and check whether 2-Step Verification is on"],duration:"20 min",slides:e("signing-in-and-staying-secure",["Signing in: email, password, then a second step","2-Step Verification: something you know plus something you have","Second steps you can use: Google prompts, passkeys and security keys, authenticator codes, text codes, backup codes","Never approve a sign-in you did not start","Shared and public computers: sign out, or use a private window","Quick check: safe or risky?"]),sections:[{heading:"One account opens everything",blocks:[{type:"scenario",role:"You are covering the front desk at Parkview Property Management.",text:"The front desk computer is shared by everyone who covers the desk: you, Andre the leasing agent, and sometimes Kim from maintenance. Your Google account opens your email, every shared file, and the tenant contact list. If you leave it signed in, the next person at the desk is working as you.",task:"Sign in safely, understand the 2-Step Verification prompt, and always leave the shared computer signed out."},{type:"paragraph",text:"Your Google account is the key to every app in Google Workspace. Because one account opens your email, your files, and your calendar, protecting it protects all of them. Two habits do most of the work: turning on 2-Step Verification and signing out of shared computers."},{type:"list",ordered:!0,items:["Open a web browser and go to drive.google.com (or any Google app, such as mail.google.com).","In Email or phone, type your account address and click Next.","Type your password and click Next.","If 2-Step Verification is on, complete the second step, such as tapping Yes on your phone.","The app opens. Your profile picture or initial at the top right shows which account you are using."]},{type:"drag-drop",mode:"order",title:"Put the sign-in steps in order",prompt:"Drag the steps into the order you do them.",items:[{id:"s1",text:"Go to drive.google.com in a browser"},{id:"s2",text:"Type your email address and click Next"},{id:"s3",text:"Type your password and click Next"},{id:"s4",text:"Tap Yes on the prompt on your phone"},{id:"s5",text:"Check the profile picture at the top right"}],explanation:"Email first, then password, then the second step. Checking the profile picture confirms you are in the right account, which matters when a computer has been used by someone else."}]},{heading:"2-Step Verification",blocks:[{type:"paragraph",text:"With 2-Step Verification, signing in takes something you know (your password) and something you have (usually your phone). If someone steals or guesses your password, they still cannot get in without the second step."},{type:"table",caption:"Second steps Google offers",columns:["Second step","How it works"],rows:[["Google prompts","A notification on your signed-in phone asks if you are trying to sign in. You tap Yes or No."],["Passkeys and security keys","Your phone, computer, or a small hardware key confirms it is you, often with your fingerprint, face, or screen lock."],["Authenticator app","An app such as Google Authenticator shows a one-time code. It works without internet or cell service."],["Text message or call","Google sends a 6-digit code to your phone number. Google notes these codes can be vulnerable to phone-number scams."],["Backup codes","A printed list of 8-digit codes for when you do not have your phone. Keep them private and somewhere safe."]]},{type:"list",items:["To turn it on in a personal account: go to myaccount.google.com, select Security & sign-in, and under How you sign in to Google, choose Turn on 2-Step Verification. Follow the steps on the screen.","In a work or school account, your administrator may already require it or may manage it for you. If the steps do not work, contact your administrator."]},{type:"callout",variant:"warning",text:"If a sign-in prompt appears on your phone and you are not signing in, tap No, it's not me. A prompt you did not start means someone may know your password. Change your password and tell your supervisor or IT. Never approve a prompt because a caller or a text message tells you to."}]},{heading:"Shared and public computers",blocks:[{type:"table",caption:"What to do on each kind of computer",columns:["Computer","What to do when you finish"],rows:[["Your own computer","You can stay signed in. Lock the screen when you step away (Windows key + L)."],["A shared work computer, like the front desk","Sign out: click your profile picture at the top right, then Sign out. Do not let the browser save your password."],["A public computer, like a library","Sign in only in a private browsing window (Incognito in Chrome, InPrivate in Edge). When you finish, close every private window and you are signed out."]]},{type:"paragraph",text:"Forgot to sign out somewhere? Go to your Google Account, open Your devices, and use Manage devices to remove the computer you no longer use. If your password could have been saved on someone else's computer, change it."},{type:"drag-drop",mode:"sort",title:"Safe or risky?",prompt:"Sort each habit.",buckets:[{id:"safe",label:"Safe habit"},{id:"risky",label:"Risky habit"}],items:[{id:"h1",text:"Signing out of the front desk computer before you go to lunch",bucket:"safe"},{id:"h2",text:"Clicking Save password on the shared front desk computer",bucket:"risky"},{id:"h3",text:"Tapping No, it's not me on a sign-in prompt you did not start",bucket:"safe"},{id:"h4",text:"Approving a sign-in prompt because a caller says he is from IT",bucket:"risky"},{id:"h5",text:"Using an Incognito window to check your account at the library",bucket:"safe"},{id:"h6",text:"Using the same password for your Google account and a shopping site",bucket:"risky"}],explanation:"Safe habits keep other people from working as you: sign out, do not save passwords on shared computers, use private windows on public ones, and never approve a sign-in you did not start."},{type:"tip",text:"Use a long password you do not use anywhere else. A short sentence of unrelated words is easier to remember and harder to guess than a short word with symbols."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You are not signing in anywhere, and your phone shows a Google prompt: Are you trying to sign in? What should you do?",options:["Tap Yes so the prompt goes away","Ignore it","Tap No, it's not me, then change your password and tell IT","Turn off 2-Step Verification"],correctIndex:2,explanation:"A prompt you did not start means someone has your password and is trying to get in. Block it, change your password, and report it.",optionRationales:["Tapping Yes lets the other person into your account.","Ignoring it leaves your password in someone else's hands.","Correct. Block the sign-in, change the password, and report it.","2-Step Verification just stopped the intruder. Turning it off makes things worse."]},{type:"knowledge-check",question:"You checked the shared calendar on the front desk computer. What do you do before you leave the desk?",options:["Close the browser tab","Sign out: profile picture, then Sign out","Minimize the browser","Nothing, the next person uses the same account"],correctIndex:1,explanation:"Closing a tab or minimizing the window can leave you signed in. Sign out from your profile picture so the next person cannot work as you.",optionRationales:["Closing a tab often leaves you signed in for the next person.","Correct. Signing out ends your session on that computer.","Minimizing hides the window. You are still signed in.","Everyone has their own account. Sharing one account hides who did what."]}]}],challenge:[{type:"paragraph",text:"Check the security of your own Google account. Use a personal Google account, on your own device if you can."},{type:"list",ordered:!0,items:["Go to myaccount.google.com and sign in.","Select Security & sign-in.","Under How you sign in to Google, find 2-Step Verification. Write down whether it is on or off.","Write down which second steps your account has (for example, Google prompts, an authenticator app, or backup codes). Do not write down any codes or phone numbers.","If 2-Step Verification is off and this is your own account, turn it on and follow the steps on the screen.","Sign out when you finish: profile picture at the top right, then Sign out."]},{type:"callout",variant:"success",text:"Deliverable: Submit a short note to your instructor or course folder: is 2-Step Verification on, which kinds of second step you have, and one thing you will do differently on shared computers. If you cannot use a Google account, complete the practice simulation and submit its results page."}]},{slug:"getting-around-the-apps",title:"Getting Around Drive, Docs, Sheets, and Slides",description:"Move between the Google apps, start a new file from a blank page or a template, and learn the parts of the screen that every Google editor shares.",objectives:["Open Docs, Sheets, and Slides from the Google apps menu and from their home screens","Start a new file from a blank page or a template, and give it a clear name","Name the parts of a Google editor: title, menus, toolbar, document status, version history, comments, and Share","Find any command with Search the menus (Alt+/)"],duration:"20 min",slides:e("getting-around-the-apps",["Getting around: the Google apps menu and each app's home screen","A home screen: Start a new file, Template gallery, Recent files","Every editor has the same parts","Name your file the moment you create it","Search the menus: Alt+/ finds any command","Quick check: where would you click?"]),sections:[{heading:"Moving between apps",blocks:[{type:"scenario",role:"You are setting up your first files at Parkview Property Management.",text:"Denise asks you to start a letter to a vendor and a supply order spreadsheet. You know Word and Excel, but the Google apps are new, and you want to stop guessing where things are.",task:"Open the right app, start each file from a blank page or a template, name it, and find commands quickly."},{type:"list",items:["The Google apps menu is the grid of dots at the top right of Drive, Gmail, and the app home screens. Click it, then click an app. The order of the apps is set by Google; you cannot rearrange them.","Each app also has its own address: docs.google.com, sheets.google.com, slides.google.com, drive.google.com, mail.google.com, calendar.google.com.","In an open document, click the Docs (or Sheets or Slides) logo at the top left to go back to that app's home screen.","Every file opens in its own browser tab, so you can keep Drive in one tab and your document in another."]}]},{heading:"Home screens and templates",blocks:[{type:"paragraph",text:"Docs, Sheets, and Slides each open to a home screen. Across the top is Start a new document (or spreadsheet, or presentation) with a Blank option and a few templates. Template gallery at the top right shows more. Below that is a list of your recent files."},{type:"table",caption:"Ways to start a new file",columns:["From","How","Same as in Microsoft Office"],rows:[["An app's home screen","Click Blank, or click a template","File › New in Word or Excel"],["Drive","New › Google Docs (or Sheets, Slides) › Blank document or From a template","Creating a file in a OneDrive folder"],["Inside Docs","File › New › Document, or From a template","File › New in Word"]]},{type:"callout",variant:"info",text:"A file you start from a home screen is saved in My Drive. A file you start with New in a Drive folder is saved in that folder. Either way, you can move it later."},{type:"paragraph",text:"A new file is named Untitled document (or Untitled spreadsheet). Rename it right away so you and your coworkers can find it: click the name at the top left, type a clear name such as Parkview Supply Order, and press Enter."}]},{heading:"The parts of every editor",blocks:[{type:"table",caption:"Parts of the Docs, Sheets, and Slides screen",columns:["Part","Where","What it does"],rows:[["App logo","Top left","Goes back to the app's home screen"],["File name","Next to the logo","Click it to rename the file"],["Star, Move, and document status","Right of the file name","Star the file, move it to a folder, and see that changes are saved to Drive"],["Menus","Under the file name","File, Edit, View, Insert, Format, and more. Like Word's Ribbon tabs"],["Toolbar","Under the menus","One-click formatting: undo, print, styles, font, bold, and more"],["Version history","Top right (the clock icon, Last edit)","See and restore earlier versions"],["Comments","Top right","Open the comment history"],["Share","Top right","Give people access to the file"],["Profile picture","Top right","Shows which account you are using, and signs you out"]]},{type:"drag-drop",mode:"match",title:"Where would you click?",prompt:"Match each job to the part of the screen that does it.",items:[{id:"p1",text:"Rename the file",match:"The file name at the top left"},{id:"p2",text:"Give Kim access to the file",match:"Share at the top right"},{id:"p3",text:"See an earlier version",match:"Version history (the clock icon)"},{id:"p4",text:"Make text bold",match:"The toolbar"},{id:"p5",text:"Go back to the Docs home screen",match:"The Docs logo at the top left"}],explanation:"The editors share one layout: the name and status across the top, menus and toolbar below, and Share, comments, and version history at the top right."}]},{heading:"Find any command",blocks:[{type:"paragraph",text:"Can't find a command? Click Search the menus (the magnifying glass at the left end of the toolbar) or press Alt+/ and type what you want, like word count or page setup. Press Enter to run the first match. Ctrl+/ shows the keyboard shortcuts."},{type:"table",caption:"Shortcuts that work like Microsoft Office",columns:["Shortcut","What it does"],rows:[["Ctrl+B, Ctrl+I, Ctrl+U","Bold, italic, underline"],["Ctrl+Z, Ctrl+Y","Undo, redo"],["Ctrl+C, Ctrl+X, Ctrl+V","Copy, cut, paste"],["Ctrl+K","Insert a link"],["Ctrl+P","Print"],["Alt+/","Search the menus"]]},{type:"tip",text:"Ctrl+S does nothing harmful in Google's editors, but you never need it. Look for Saved to Drive by the document status icon if you want to be sure."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You started a document from the Docs home screen and it is called Untitled document. What is the fastest way to rename it?",options:["File › Save as","Click the name at the top left, type the new name, press Enter","Download it with a new name","Close the tab and rename it in File Explorer"],correctIndex:1,explanation:"The file name at the top left is a box you can click and type in. The new name is saved right away.",optionRationales:["Google's editors do not have Save as. Use the name box or File › Rename.","Correct. Click the name, type, and press Enter.","Downloading makes a copy on the computer. The file in Drive keeps the old name.","Google files live in Drive, not in File Explorer."]},{type:"knowledge-check",question:"You need Page setup but cannot find it. What is the quickest way?",options:["Press Alt+/ and type page setup","Look on every toolbar button","Reinstall Google Docs","Ask a coworker to do it"],correctIndex:0,explanation:"Search the menus (Alt+/) finds any command by name.",optionRationales:["Correct. Search the menus finds the command and runs it.","Page setup is in the File menu, not on the toolbar. Searching is faster.","Google Docs runs in the browser, so there is nothing to install.","You can find it yourself in seconds with Search the menus."]}]}],challenge:[{type:"paragraph",text:"Practice in your own Google account."},{type:"list",ordered:!0,items:["Open Google Docs from the Google apps menu. Start a document from any template in the Template gallery.","Rename it Template Practice - your first name.","Use Search the menus (Alt+/) to open Word count. Write down the number of words.","Click the Docs logo to go back to the home screen. Find your new document under Recent documents.","Open Google Sheets from the Google apps menu and start a blank spreadsheet. Rename it Supply Order Practice."]},{type:"callout",variant:"success",text:"Deliverable: Submit the word count and a screenshot of your Docs home screen showing your renamed document to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"working-with-office-files",title:"Working with Microsoft Office Files",description:"Open and edit Word, Excel, and PowerPoint files without converting them, convert one to a Google file when you need to, and download Google files as Office files or PDFs.",objectives:["Open and edit a Word, Excel, or PowerPoint file from Drive and keep it in its Office format","Convert an Office file with File › Save as Google Docs, Sheets, or Slides, and explain why that makes a copy","Download a Google file as a Microsoft Office file or a PDF","Choose the right format to send to someone outside your company"],duration:"20 min",slides:e("working-with-office-files",["Office files in Google Workspace: open, edit, convert, download","Office editing: the .DOCX chip means it stays a Word file","Save as Google Docs makes a Google copy; the Office file stays as it was","File › Download: Word, Excel, PowerPoint, PDF","Which format should you send?","Quick check: edit, convert, or download?"]),sections:[{heading:"Office files keep arriving",blocks:[{type:"scenario",role:"You handle the paperwork that comes into the Parkview office.",text:"Not everyone uses Google Workspace. Russo Plumbing emails its invoices as Excel files, the lease renewal notice came from the company lawyer as a Word file, and a tenant who uses Word asked for the move-in checklist in Word. Parkview's files live in Drive, so you need to handle all of these without retyping anything.",task:"Edit Office files in Drive, convert them when you need Google features, and send people the format they can use."},{type:"paragraph",text:"Drive stores any kind of file. When you double-click a Word, Excel, or PowerPoint file in Drive, it opens in Google Docs, Sheets, or Slides. You can read it, edit it, and comment on it. Your changes are saved back to the original Office file."}]},{heading:"Office editing: keep the Office format",blocks:[{type:"list",items:["An Office file shows its file type in a small chip next to the name at the top left, such as .DOCX, .XLSX, or .PPTX.","Edits save automatically, in the Office format. Someone who downloads the file later gets a normal Word, Excel, or PowerPoint file.","Drive's Office editing works with Word (.doc, .docx, .dot), Excel (.xls, .xlsx, .xlsm, .xlt), and PowerPoint (.ppt, .pptx, .pps, .pot) files."]},{type:"paragraph",text:"Some features work only in Google files, such as protected ranges in Sheets, add-ons, Apps Script, and translating a document. To use them, convert the file: open it, then choose File › Save as Google Docs (or Save as Google Sheets, Save as Google Slides)."},{type:"callout",variant:"info",text:"Converting makes a copy. The original Office file stays in Drive, unchanged, and the new Google file opens in a new tab. Rename or delete the one you do not need so coworkers do not edit the wrong copy."}]},{heading:"Download as Office or PDF",blocks:[{type:"paragraph",text:"To send someone a file they can open without Google, download it in another format: open the file and choose File › Download, then pick the format. The download goes to your computer's Downloads folder, and you can attach it to an email. The file in Drive does not change."},{type:"table",caption:"Common File › Download formats",columns:["App","Format","Use it when"],rows:[["Docs","Microsoft Word (.docx)","The other person needs to edit it in Word"],["Docs","PDF Document (.pdf)","The other person only needs to read, print, or sign it"],["Sheets","Microsoft Excel (.xlsx)","The other person needs to work with the numbers in Excel"],["Sheets","Comma Separated Values (.csv)","Another system needs the data (a CSV file holds one sheet of plain data)"],["Slides","Microsoft PowerPoint (.pptx)","The presenter uses PowerPoint"],["Slides","PDF Document (.pdf)","People only need to read the slides"]]},{type:"drag-drop",mode:"sort",title:"What should you send?",prompt:"Sort each request.",buckets:[{id:"pdf",label:"Download a PDF"},{id:"office",label:"Download an Office file"},{id:"share",label:"Share the Google file"}],items:[{id:"r1",text:"A tenant needs to print and sign the move-in checklist",bucket:"pdf"},{id:"r2",text:"The lawyer will edit the lease notice in Word",bucket:"office"},{id:"r3",text:"Marcus, at Parkview, needs to add notes to the notice",bucket:"share"},{id:"r4",text:"The accountant wants the rent totals in Excel",bucket:"office"},{id:"r5",text:"A building notice will be posted on the lobby board",bucket:"pdf"},{id:"r6",text:"Kim and Denise will update the maintenance log together",bucket:"share"}],explanation:"Inside Parkview, share the one Google file. Outside, send a PDF when people only read or print, and an Office file when they need to edit in Microsoft Office."},{type:"worked-example",title:"The lease renewal notice",task:"The lawyer sent Lease Renewal Notice.docx. Denise wants it styled like Parkview's other notices and kept as a Google Doc, and a tenant needs a copy to print.",steps:[{move:"Double-click the .docx file in Drive.",why:"It opens in Docs with the .DOCX chip, so you can check it right away without converting."},{move:"File › Save as Google Docs.",why:"Denise wants a Google Doc, and converting gives you a Google copy while the lawyer's original stays as it was."},{move:"Format the Google copy.",why:"Edits now go into Parkview's Google Doc, not the lawyer's file."},{move:"File › Download › PDF Document (.pdf) for the tenant.",why:"A PDF prints the same on any computer and cannot be changed by accident."}],result:"A Google Doc for the office and a PDF for the tenant, with the lawyer's original untouched.",takeaway:"Edit Office files in place when you only need a quick change; convert when Parkview will keep and maintain the file."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You open Russo Plumbing Invoice.xlsx from Drive and fix a typo. What happens?",options:["The change is lost because Sheets cannot edit Excel files","The change is saved in the original Excel file","Drive makes a Google Sheets copy automatically","You must download the file to save the change"],correctIndex:1,explanation:"Office editing saves your changes back to the Office file in its original format.",optionRationales:["Sheets edits Excel files directly with Office editing.","Correct. The .XLSX chip shows it is still an Excel file, and your change is saved in it.","A Google copy is made only when you choose File › Save as Google Sheets.","Changes save automatically. Downloading is only for sending a copy."]},{type:"knowledge-check",question:"You chose File › Save as Google Docs on a Word file. What is in Drive now?",options:["Only the Google Doc","Only the Word file","Both: the original Word file and a new Google Doc","A PDF"],correctIndex:2,explanation:"Converting makes a copy. The Word file stays, and the Google Doc opens in a new tab.",optionRationales:["The original is not deleted when you convert.","Converting adds a Google Doc next to the Word file.","Correct. You now have two files. Remove or rename the one you do not need.","PDF is a download format, not what Save as Google Docs makes."]}]}],challenge:[{type:"paragraph",text:"Practice with your own Google account and any Word file (or download one of your Google Docs as Word first)."},{type:"list",ordered:!0,items:["Upload a Word file to My Drive (New › File upload), or create a Google Doc and download it with File › Download › Microsoft Word (.docx), then upload that .docx.","Double-click the Word file in Drive. Find the .DOCX chip next to the name.","Make one small change, then choose File › Save as Google Docs. Check that Drive now has both files.","In the Google Doc, choose File › Download › PDF Document (.pdf). Open the PDF from your Downloads folder."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of Drive showing both the Word file and the Google Doc, plus the PDF, to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]}],g="/images/google-workspace/module-2",h=(a,b)=>b.map((b,c)=>({src:`${g}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),i=[{slug:"the-drive-screen-and-uploading",title:"The Drive Screen and Uploading Files",description:"Learn the parts of Google Drive, from New and Home to Shared with me and Trash, and upload files and folders from your computer.",objectives:["Name what each part of Drive's left side shows: Home, My Drive, Shared drives, Shared with me, Recent, Starred, Spam, Trash, and Storage","Upload files and folders with New and by dragging them into Drive","Switch between list and grid layout and open a file's details","Explain what happens when you upload a file with the same name as one already in Drive"],duration:"20 min",videoUrl:"https://www.youtube.com/embed/hoQbFkScHGk",slides:h("the-drive-screen-and-uploading",["Google Drive: every file in one place, on any computer","The Drive screen: New, the left side, search, the file list, and details","Home, My Drive, Shared with me: whose files are where","Uploading: New, then File upload or Folder upload, or drag files in","Same name? The upload becomes a new version, unless you keep both","Quick check: where would you look?"]),sections:[{heading:"Your files live in Drive",blocks:[{type:"scenario",role:"You keep Parkview's paperwork organized.",text:"Tenants drop off signed forms at the front desk, and you scan them on the office computer. Right now the scans pile up on the desktop, where nobody else can find them. Denise wants every form in Parkview's Drive folders, where the team can open them from either building.",task:"Find your way around Drive and upload files into the right folder."},{type:"paragraph",text:"Google Drive is where every Google Doc, Sheet, and Slides file is saved, and where you can store any other file: PDFs, photos, Word and Excel files, videos. Go to drive.google.com (or choose Drive in the Google apps menu) and sign in."},{type:"table",caption:"The left side of Drive",columns:["Item","What it shows"],rows:[["New","Make a folder, upload files or folders, or create a Google Doc, Sheet, Slides, or Form"],["Home","Files and folders you or others opened, shared, or edited recently, plus files for upcoming meetings"],["Activity (work accounts)","Recent comments, access requests, and approvals in one place"],["My Drive","Files and folders you created or uploaded, organized your way"],["Shared drives (work accounts)","Team drives whose files belong to the team, not to one person"],["Computers","Folders synced from a computer with Drive for desktop"],["Shared with me","Files other people shared with you"],["Recent and Starred","Files you opened lately, and files you marked with a star"],["Spam and Trash","Files you marked as spam, and files you deleted (kept for 30 days)"],["Storage","How much space you use, and which files use the most"]]},{type:"callout",variant:"info",text:"Drive opens to Home or My Drive. You can choose which one in Drive's Settings (the gear at the top right), under Start page."}]},{heading:"The file list and details",blocks:[{type:"list",items:["Click a file once to select it. A bar appears above the list with Share, Download, Move, Move to trash, Copy link, and More actions.","Double-click a file to open it. Google files open in their own browser tab; other files open in a preview.","Right-click a file for every option, including Organize and Share.","Use the List layout and Grid layout buttons at the top right of the list to switch views.","Select a file and click View details (the i in a circle) to see its type, size, owner, who has access, and recent activity."]},{type:"drag-drop",mode:"match",title:"Where would you look?",prompt:"Match each question to the part of Drive that answers it.",items:[{id:"q1",text:"Kim shared the boiler inspection with you. Where is it?",match:"Shared with me"},{id:"q2",text:"You deleted a flyer by mistake yesterday.",match:"Trash"},{id:"q3",text:"Which files take up the most space?",match:"Storage"},{id:"q4",text:"The folders you made for each building.",match:"My Drive"},{id:"q5",text:"Who has access to this lease, and when was it changed?",match:"View details"}],explanation:"My Drive holds what you own and organize. Shared with me holds what others shared. Trash holds deleted files for 30 days. Storage ranks files by size. Details shows a file's access and history."}]},{heading:"Uploading files and folders",blocks:[{type:"list",ordered:!0,items:["Open the Drive folder where the file belongs (double-click it).","Click New, then File upload (or Folder upload for a whole folder).","Choose the file on your computer and click Open. A box at the bottom right shows the upload's progress.","Or drag files or folders from your computer's desktop or File Explorer straight into the open Drive folder in your browser."]},{type:"paragraph",text:"If you upload a file with the same name as one already in that folder, Drive saves it as a new version of the existing file. To keep both as separate files, click Keep both files in the upload box. Uploaded files use your Drive storage."},{type:"callout",variant:"version",text:"Uploaded Word and Excel files stay Office files, which you can still edit in Drive (Module 1). If you want uploads to become Google files automatically, turn on Convert uploads to Google Docs editor format in Drive's Settings. You can change that setting only on a computer."},{type:"table",caption:"If you know OneDrive",columns:["Google Drive","OneDrive"],rows:[["New › File upload","Create or upload › Files upload"],["My Drive","My files"],["Shared with me","Shared › With you"],["Shared drives","SharePoint and Teams libraries"],["Trash","Recycle bin"]]}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Andre shared a tenant's application with you. Where do you find it first?",options:["My Drive","Shared with me","Trash","Computers"],correctIndex:1,explanation:"Files other people share with you appear in Shared with me (and often in Home and Recent). They stay in the owner's Drive.",optionRationales:["My Drive holds files you created or uploaded. A shared file is not there unless you add a shortcut.","Correct. Shared with me lists files others shared with you.","Trash holds deleted files.","Computers holds folders synced from a computer with Drive for desktop."]},{type:"knowledge-check",question:"You upload Parking Permit Form.docx into a folder that already has a file with that exact name. What happens?",options:["Drive refuses the upload","The upload becomes a new version of the existing file, unless you choose Keep both files","Both files are deleted","The new file goes to Trash"],correctIndex:1,explanation:"Drive treats a same-name upload as a new version of the file. Keep both files in the upload box saves it as a separate file.",optionRationales:["Drive accepts the upload.","Correct. It is saved as a revision of the existing file unless you keep both.","Nothing is deleted.","Uploads never go to Trash."]}]}],challenge:[{type:"paragraph",text:"Practice in your own Google Drive."},{type:"list",ordered:!0,items:["Go to drive.google.com and make a folder named Drive Practice (New › New folder).","Open the folder and upload any file from your computer (New › File upload).","Drag a second file from your desktop or File Explorer into the open folder.","Switch to grid layout, then back to list layout.","Select one of the files and open View details. Write down its size and owner."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of your Drive Practice folder with the details pane open to your instructor or course folder. No Google account, or a computer that blocks uploads? Complete the practice simulation and submit its results page."}]},{slug:"organizing-files-and-folders",title:"Organizing Files and Folders",description:"Build a folder system your coworkers can follow: create folders, move and rename files, star and color what matters, add shortcuts, and make copies.",objectives:["Create folders and folders inside folders","Move files by dragging them or with Organize › Move, and rename them","Star files and color-code folders so the important ones stand out","Add a shortcut to a file in a second folder, and make a copy when you need a separate file","Name files so anyone can find them"],duration:"20 min",videoUrl:"https://www.youtube.com/embed/07z6YD6f8bs",slides:h("organizing-files-and-folders",["Organizing Drive: folders, names, stars, colors, and shortcuts","A folder system the whole office can follow","Moving files: drag them, or Organize, then Move","Stars and folder colors: only you see them","Shortcut or copy? One file in two places, or two separate files","Quick check: shortcut, copy, or move?"]),sections:[{heading:"Folders the whole office can follow",blocks:[{type:"scenario",role:"You are cleaning up Parkview's My Drive.",text:"Files for both buildings sit loose in My Drive, one is still called Untitled document, and nobody can find the laundry schedule. Denise wants a folder for each building with a Maintenance folder inside, files named so anyone can search for them, and the files you use every day easy to reach.",task:"Organize the files into folders, rename them clearly, and mark the important ones."},{type:"list",items:["Create a folder: open the place it should go, click New › New folder, type a name, and click Create.","Folders can hold folders: Elm Street Apartments › Maintenance › Boiler.","Rename a file or folder: right-click it › Rename, or select it and press F2. Inside an open file, click its name at the top left.","Name files with what, where, and which: Elm Street Laundry Schedule, Lease - Elm 3B - Jordan Smith. Avoid names like Untitled document, scan001, or final final."]},{type:"worked-example",title:"Naming the boiler notes",task:"A file called Untitled document holds notes from the Elm Street boiler inspection.",steps:[{move:"Right-click it › Rename and type Elm Street Boiler Notes.",why:"Search finds words in names. Untitled document tells nobody what is inside."},{move:"Move it into Elm Street Apartments › Maintenance.",why:"A coworker who browses instead of searching finds it where they expect."},{move:"Leave dates and version words out of the name.",why:"Drive keeps the modified date and the version history for you."}],result:"A file anyone at Parkview can find by searching or by browsing.",takeaway:"Name files for the next person: what it is, plus the building or tenant it belongs to."}]},{heading:"Moving files",blocks:[{type:"list",items:["Drag the file onto the folder in the list, or onto a folder on the left side, and let go.","Or right-click the file › Organize › Move, choose the folder, and click Move.","Select several files first with Ctrl+click (or Shift+click for a range) to move them together.","If you move a file into a shared folder, everyone who has access to that folder gets access to the file."]},{type:"drag-drop",mode:"order",title:"Move a file with Organize",prompt:"Put the steps in order.",items:[{id:"o1",text:"Right-click the file"},{id:"o2",text:"Point to Organize"},{id:"o3",text:"Click Move"},{id:"o4",text:"Choose the destination folder"},{id:"o5",text:"Click Move to confirm"}],explanation:"Right-click, Organize, Move, pick the folder, confirm. Dragging does the same in one motion when the folder is on screen."}]},{heading:"Stars, colors, shortcuts, and copies",blocks:[{type:"table",caption:"Tools for finding what matters",columns:["Tool","How","What it does"],rows:[["Star","Right-click › Organize › Add to starred (or select it and press Ctrl+Alt+S)","Puts the file under Starred on the left side"],["Folder color","Right-click a folder › Organize › choose a color","Makes the folder stand out. Colors show only in your Drive"],["Shortcut","Right-click › Organize › Add shortcut, choose a folder, click Add shortcut","A link to the same file in another folder. Edits show up in both places"],["Make a copy","Right-click a file › Make a copy (or File › Make a copy in the file)","A separate file. Changes to one do not change the other"]]},{type:"drag-drop",mode:"sort",title:"Shortcut, copy, or move?",prompt:"Sort each request.",buckets:[{id:"shortcut",label:"Add a shortcut"},{id:"copy",label:"Make a copy"},{id:"move",label:"Move it"}],items:[{id:"c1",text:"The vendor list should also appear in the Elm Street folder, and stay one list",bucket:"shortcut"},{id:"c2",text:"Riverside needs its own laundry schedule, starting from Elm Street's",bucket:"copy"},{id:"c3",text:"The laundry schedule belongs in the Elm Street folder, not loose in My Drive",bucket:"move"},{id:"c4",text:"Kim wants the boiler log in her Maintenance folder too, and wants to see your updates",bucket:"shortcut"},{id:"c5",text:"You want to try a new layout for the notice without changing the real one",bucket:"copy"}],explanation:"A shortcut points to the one real file, so everyone sees the same updates. A copy is a new, separate file. Moving changes where the one file lives."},{type:"callout",variant:"info",text:"A file can live in only one folder. When it needs to show up in a second folder, add a shortcut instead of a copy, so there is still only one version to keep up to date."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You colored the Elm Street folder green. What does Marcus see in his Drive?",options:["A green folder","The folder in its usual color","A red folder","Nothing, because coloring hides the folder"],correctIndex:1,explanation:"Folder colors apply only to your view of Drive. Other people see their own colors.",optionRationales:["Your colors are yours alone.","Correct. Color changes apply only to your version of Drive.","Colors are not shared, so he sees his own setting.","Coloring never hides anything."]},{type:"knowledge-check",question:"The vendor contact list must appear in both the Elm Street and Riverside folders, and stay one list. What do you do?",options:["Make a copy for each folder","Add a shortcut to the list in the second folder","Download it and upload it twice","Email it to yourself"],correctIndex:1,explanation:"A shortcut shows the same file in another folder. There is still one list to keep current.",optionRationales:["Copies drift apart as people update one and not the other.","Correct. The shortcut points to the one real list.","Uploading twice makes two separate files.","Emailing makes another copy outside Drive."]}]}],challenge:[{type:"paragraph",text:"Organize a corner of your own Drive."},{type:"list",ordered:!0,items:["Create a folder named Job Search, and inside it two folders named Resumes and Cover Letters.","Create or upload one file and move it into Resumes. Rename it Resume - your name.","Star the Job Search folder and give it a color.","Add a shortcut to your resume in the Cover Letters folder.","Make a copy of the resume and name it Resume - your name - Practice."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of your Job Search folder showing the two folders, and one of the Resumes folder, to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"finding-files-fast",title:"Finding Files Fast",description:"Search Drive by name and by the words inside files, narrow results with the Type, People, Modified, and Location filters, and use Recent, Starred, and Shared with me.",objectives:["Search Drive for words in file names and inside files","Narrow results with the Type, People, Modified, and Location filter chips, and clear them","Use search words such as owner:, type:, and before: for exact searches","Choose between search, Recent, Starred, and Shared with me to find a file in seconds"],duration:"15 min",slides:h("finding-files-fast",["Finding files: search first, browse second","Search in Drive: type a word, press Enter","Filter chips: Type, People, Modified, Location","Search words for exact searches: owner:, type:, before:, after:","Recent, Starred, Shared with me: shortcuts to your files","Quick check: which search would you use?"]),sections:[{heading:"Search first",blocks:[{type:"scenario",role:"You answer Denise's file requests all day.",text:"Denise calls from Riverside Commons: she needs the lease for apartment 210, the October rent tracker Priya keeps, and the water shutoff notice she remembers editing last week. Clicking through folders would take minutes. Search takes seconds.",task:"Find each file with search and filters."},{type:"list",ordered:!0,items:["Click Search in Drive at the top of the screen.","Type a word from the file's name or from inside it, such as lease or shutoff, and press Enter.","Results are sorted by relevance. Click a column heading to sort another way.","To clear the search, click the X at the right end of the search box."]},{type:"tip",text:"Drive searches inside Google Docs, Sheets, and Slides and many other files, not only file names. Searching for a tenant's apartment number can find a letter that mentions it."}]},{heading:"Filter chips",blocks:[{type:"paragraph",text:"The filter chips under the search box narrow what you see. Use them with or without words in the search box. A chip turns blue when it is on. To remove one, open it and choose Clear; to remove them all, click Clear filters."},{type:"table",caption:"Drive's filter chips",columns:["Chip","Narrows to","Example"],rows:[["Type","Documents, Spreadsheets, Presentations, PDFs, Photos and images, Folders, and more","Only PDFs, for scanned forms"],["People","Files owned by or shared with a person","Files Priya owns"],["Modified","When the file last changed: Today, Last 7 days, Last 30 days, this year, last year","What changed last week"],["Location","Where the file is: anywhere in Drive, My Drive, Shared with me, Starred, Trash","Only files shared with you"]]},{type:"drag-drop",mode:"match",title:"Pick the chip",prompt:"Match each request to the chip that narrows it.",items:[{id:"f1",text:"Only the scanned forms (PDFs)",match:"Type"},{id:"f2",text:"Only files Kim Nguyen owns",match:"People"},{id:"f3",text:"Only files changed in the last 7 days",match:"Modified"},{id:"f4",text:"Only files other people shared with you",match:"Location"}],explanation:"Type is what kind of file, People is whose file, Modified is when it changed, and Location is where it is."}]},{heading:"Search words for exact searches",blocks:[{type:"table",caption:"Search words you can type in Search in Drive",columns:["Type this","To find"],rows:[['"water shutoff"',"Files with that exact phrase (use quotes)"],["notice -draft","Files with notice but not draft"],["owner:pshah@parkviewpm.example","Files Priya owns"],["type:spreadsheet","Spreadsheets only"],["after:2026-10-01","Files changed after a date (YYYY-MM-DD)"],["is:starred","Your starred files"]]},{type:"paragraph",text:"When you know where to look, the left side is faster than search: Recent for what you opened lately, Starred for what you marked, and Shared with me for what others sent you. To find what is using your storage, open Storage and sort by Storage used."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Denise needs any spreadsheet Priya owns. What is the fastest way?",options:["Open every folder and look","Use the Type chip set to Spreadsheets and the People chip set to Priya Shah","Search for spreadsheet","Check Trash"],correctIndex:1,explanation:"Two chips together narrow Drive to exactly the spreadsheets Priya owns.",optionRationales:["Browsing works but takes far longer.","Correct. Chips combine, so Type plus People gives exactly what she needs.","That finds files with the word spreadsheet in them, not all of Priya's spreadsheets.","Trash holds deleted files."]},{type:"knowledge-check",question:"Which search finds files that contain the exact phrase water shutoff?",options:["water shutoff",'"water shutoff"',"water -shutoff","type:water"],correctIndex:1,explanation:"Quotes match the exact phrase.",optionRationales:["Without quotes, Drive finds files with either word in any order.","Correct. Quotes find the exact phrase.","The minus sign leaves out files that contain shutoff.","type: searches by kind of file, not words."]}]}],challenge:[{type:"paragraph",text:"Search your own Drive."},{type:"list",ordered:!0,items:["Search for a word you know is in one of your files and press Enter. Write down how many results you get.","Add the Type chip to narrow the results to Documents (or another type you have).","Clear the filters. Use the Modified chip to show files changed in the last 7 days.","Type is:starred in the search box and press Enter. Compare the results with Starred on the left side."]},{type:"callout",variant:"success",text:"Deliverable: Submit your answers (the words you searched, the number of results, and what each chip changed) to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"sharing-files-and-folders",title:"Sharing Files and Folders",description:"Share with the right people and the right role, set general access, copy links, add expiration dates, and remove access when it is no longer needed.",objectives:["Share a file or folder with specific people as Viewer, Commenter, or Editor","Set General access to Restricted, your organization, or Anyone with the link, and explain the risk of each","Copy a link to a file and change or remove someone's access","Add an expiration date for a person outside your organization","Explain that sharing a folder shares every file inside it"],duration:"25 min",slides:h("sharing-files-and-folders",["Sharing: the right people, the right role","Viewer, Commenter, Editor: what each can do","General access: Restricted, your organization, or anyone with the link","Sharing a folder shares everything inside it","Clean up: change roles, remove access, add expiration dates","Quick check: which role or access fits?"]),sections:[{heading:"Share, do not attach",blocks:[{type:"scenario",role:"You manage access to Parkview's files.",text:"Marcus needs to edit the tenant handbook, Priya only needs to read it, Tony Russo from Russo Plumbing needs to see photos in the Maintenance folder for a few weeks, and the lobby notice should be readable by everyone at Parkview. You also find an old folder still open to anyone with the link, months after the painting contractor finished.",task:"Give each person the least access they need, and close access nobody needs anymore."},{type:"list",ordered:!0,items:["Select the file (or open it) and click Share.","Type a name or email address and choose the person.","Pick a role: Viewer, Commenter, or Editor.","Leave Notify people checked to send an email, and add a message if it helps. Uncheck it to give access quietly.","Click Send (or Share)."]},{type:"table",caption:"Roles for a file in My Drive",columns:["Role","Can do","Use it for"],rows:[["Viewer","View and download by default","People who only need to read: Priya and the handbook"],["Commenter","View, comment, and suggest edits","Reviewers: a manager checking a draft"],["Editor","View, comment, edit, and share by default","People who work on the file with you: Marcus"],["Owner","Everything, including deleting the file","You, for files you create"]]},{type:"drag-drop",mode:"sort",title:"Which role?",prompt:"Sort each person into the role they need.",buckets:[{id:"viewer",label:"Viewer"},{id:"commenter",label:"Commenter"},{id:"editor",label:"Editor"}],items:[{id:"r1",text:"Priya needs to read the handbook",bucket:"viewer"},{id:"r2",text:"Denise will review the draft notice and leave notes",bucket:"commenter"},{id:"r3",text:"Marcus is writing half of the handbook with you",bucket:"editor"},{id:"r4",text:"Tony from Russo Plumbing needs to look at repair photos",bucket:"viewer"},{id:"r5",text:"Kim will suggest changes to the maintenance procedure for you to accept",bucket:"commenter"}],explanation:"Give the smallest role that lets the person do the job. Editors can change and share the file, so save that role for people who truly work on it."}]},{heading:"General access and links",blocks:[{type:"paragraph",text:"Under General access in the Share box, you choose who can open the file with its link, besides the people you added by name."},{type:"table",caption:"General access options",columns:["Setting","Who can open it","Use it for"],rows:[["Restricted","Only people you added by name","Most files. The safest choice"],["Your organization (Parkview Property Management)","Anyone signed in to a Parkview account who has the link (work accounts only)","Notices and procedures for all staff"],["Anyone with the link","Anyone at all who gets the link, with no sign-in needed","Public information only, never private details"]]},{type:"list",items:["Next to the general access setting, choose the role the link gives: Viewer, Commenter, or Editor.","Click Copy link, then Done. Paste the link into an email or chat.","Which options you see depends on your account. A personal account shows Restricted and Anyone with the link."]},{type:"callout",variant:"warning",text:"An Anyone with the link file can be opened by whoever gets the link, including people it was forwarded to. Never use it for leases, applications, rent records, or anything with a tenant's personal information. Share those with specific people only."},{type:"image",src:`${g}/sharing-files-and-folders/sharing-reference.png`,alt:"Quick reference: Drive sharing roles, general access options, how folder sharing works, cleaning up access, and a checklist before you click Send",caption:"Keep this sharing checklist handy."}]},{heading:"Folders, changes, and expiration dates",blocks:[{type:"paragraph",text:"When you share a folder, every file and folder inside it gets the same access, including files added later. You cannot give someone less access to a file than they have to the folder it is in. Keep private files out of widely shared folders."},{type:"list",items:["Change a role: open Share, click the arrow next to the person's role, and pick a new one.","Remove someone: click the arrow next to their role, choose Remove access, and click Save.","Turn off link sharing: under General access, choose Restricted, then click Done.","Expiration (eligible work and school accounts): click the arrow next to a person's role, choose Add expiration, pick a date within one year, and click Save. Their access ends on that date.","Stop editors from sharing: in Share, click Settings (the gear) and uncheck Editors can change permissions and share."]},{type:"worked-example",title:"Closing the old contractor folder",task:"The Bright Paint Co. folder is still set to Anyone with the link, and the painter still has edit access, months after the job ended.",steps:[{move:"Right-click the folder › Share › Share.",why:"The Share box shows every person and the general access in one place."},{move:"Under General access, choose Restricted.",why:"Anyone holding the old link loses access right away."},{move:"Next to the painter, choose Remove access, then Save.",why:"The job is over, so the access should be too."}],result:"Only Parkview staff who were added by name can open the folder.",takeaway:"Review sharing when a job ends. Old links are one of the easiest ways for files to leak."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Denise needs to review a draft notice and leave notes, without changing the text herself. Which role do you give her?",options:["Viewer","Commenter","Editor","Owner"],correctIndex:1,explanation:"Commenters can comment and suggest edits but cannot change the file directly.",optionRationales:["Viewers cannot comment.","Correct. Commenter lets her leave notes and suggestions.","Editor lets her change the text directly, which she does not need.","Ownership is never needed for a review."]},{type:"knowledge-check",question:"You share the Maintenance folder with Tony Russo as a Viewer. What can he open?",options:["Only the folder name","Every file in the folder, including files added later","Only files you share with him one by one","Nothing until you send each file"],correctIndex:1,explanation:"Files and folders inside a shared folder inherit its sharing.",optionRationales:["Viewers of a folder can open the files in it.","Correct. Everything inside inherits the folder's access, now and later.","Folder sharing covers the files inside it.","No extra step is needed. That is why you check what is in a folder before sharing it."]},{type:"knowledge-check",question:"Which file is safe to share with Anyone with the link?",options:["A tenant's rental application","The rent payment log","The public flyer for an open apartment showing","A lease with a tenant's signature"],correctIndex:2,explanation:"Anyone with the link is for information you would post publicly. Personal and financial records are shared with specific people only.",optionRationales:["Applications contain personal information.","Rent records are private.","Correct. A public flyer is meant for anyone.","Signed leases contain personal details."]}]}],challenge:[{type:"paragraph",text:"Practice sharing with a classmate, a family member, or a second account of your own. Use a practice file with no personal information."},{type:"list",ordered:!0,items:["Create a Google Doc named Sharing Practice and type one sentence in it.","Share it with the other person as a Commenter, with a short message.","Ask them to add a comment. Then change their role to Viewer and ask them to try commenting again.","Under General access, check that the file is Restricted.","Remove the person's access."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of the Share box before you removed access, and two sentences on what changed when you switched the role from Commenter to Viewer, to your instructor or course folder. No one to share with? Complete the practice simulation and submit its results page."}]},{slug:"trash-storage-and-recovery",title:"Trash, Storage, and Getting Files Back",description:"Delete files safely, restore them from Trash within 30 days, know when a deletion is permanent, and keep an eye on your Google storage.",objectives:["Move files to Trash and restore them","Explain that Trash keeps files for 30 days and that Delete forever and Empty trash cannot be undone","Explain what happens when you remove a file you do not own","Check how much storage you use, what counts toward it, and which files use the most"],duration:"15 min",videoUrl:"https://www.youtube.com/embed/CgJZyoX4_ak",slides:h("trash-storage-and-recovery",["Trash and storage: delete safely, get files back","Trash keeps files for 30 days","Restore, Delete forever, Empty trash","Files you do not own: you can remove them from your Drive, not delete them","Storage: 15 GB free, shared by Gmail, Drive, and Photos","Quick check: can you get it back?"]),sections:[{heading:"Trash is a safety net",blocks:[{type:"scenario",role:"You are cleaning up Parkview's My Drive.",text:"My Drive is cluttered with copies of copies, an old flyer draft, and a huge lobby video. Yesterday someone deleted the Riverside pool rules by mistake, and Andre needs them back today.",task:"Clean up without losing anything Parkview needs, and recover the pool rules."},{type:"list",items:["Delete a file you own: select it and click Move to trash (the trash can) in the bar above the list, right-click › Move to trash, or press Delete.","Files in Trash are deleted forever after 30 days.","Restore: open Trash on the left side, right-click the file, and choose Restore. It goes back to where it was.","Delete forever: in Trash, right-click › Delete forever. Empty trash deletes everything in Trash forever."]},{type:"callout",variant:"warning",text:"Delete forever and Empty trash cannot be undone from Drive. Before you empty the Trash, look through it for anything a coworker might still need."},{type:"drag-drop",mode:"sort",title:"Can you get it back?",prompt:"Sort each situation.",buckets:[{id:"yes",label:"Yes, restore it from Trash"},{id:"no",label:"No, it is gone from Drive"}],items:[{id:"t1",text:"Moved to Trash yesterday",bucket:"yes"},{id:"t2",text:"Moved to Trash, then Delete forever",bucket:"no"},{id:"t3",text:"Moved to Trash two weeks ago",bucket:"yes"},{id:"t4",text:"Moved to Trash, then someone clicked Empty trash",bucket:"no"},{id:"t5",text:"Moved to Trash more than 30 days ago",bucket:"no"}],explanation:"Trash holds files for 30 days. Delete forever, Empty trash, or the 30-day limit ends that."}]},{heading:"Files you do not own",blocks:[{type:"paragraph",text:"Only the owner can delete a file. If you remove a file someone else owns, it disappears from your Drive, but the owner and everyone else with access still have it. To get rid of a shared file for everyone, ask its owner."},{type:"tip",text:"Need an earlier version of a file rather than a deleted one? Open the file and use version history (File › Version history › See version history). Module 3 shows how."}]},{heading:"Storage",blocks:[{type:"list",items:["A free Google account has 15 GB of storage, shared by Gmail, Google Drive, and Google Photos. A work account's storage is set by the organization's plan.","What counts: Gmail messages and attachments (including Spam and Trash), files in Drive such as PDFs, images, and videos, and items in Drive's Trash.","Google Docs, Sheets, and Slides files created or edited after June 1, 2021 count too. Files someone shared with you count against the owner's storage, not yours.","To see what uses the most space, click Storage on the left side of Drive, then click Storage used to sort by size."]},{type:"paragraph",text:"When an account runs out of storage, you cannot upload to Drive or create new Docs, Sheets, or Slides files, and Gmail may stop sending and receiving. Deleting large files you no longer need, and then emptying them from Trash, frees space."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Andre deleted the pool rules yesterday. What do you do?",options:["Nothing can be done","Open Trash, right-click the file, and choose Restore","Ask Google to rebuild it","Search the Recycle Bin on the computer"],correctIndex:1,explanation:"Files stay in Trash for 30 days. Restore puts the file back where it was.",optionRationales:["Files stay in Trash for 30 days, so it can be restored.","Correct. Restore returns it to its folder.","Restoring it from Trash takes seconds.","Drive's Trash is in Drive, not on the computer."]},{type:"knowledge-check",question:"You remove the Vendor Contact List, which Denise owns, from your Drive. What happens to Denise's copy?",options:["It is deleted for everyone","Nothing. Only the owner can delete it, so Denise and others still have it","It moves to your Trash","Denise loses edit access"],correctIndex:1,explanation:"You cannot delete files you do not own. Removing one only takes it out of your Drive.",optionRationales:["Only the owner can delete a file for everyone.","Correct. The file stays for the owner and everyone else with access.","It leaves your view; Denise's file is untouched.","Her access does not change."]}]}],challenge:[{type:"paragraph",text:"Practice in your own Drive with a file you do not need."},{type:"list",ordered:!0,items:["Create a Google Doc named Delete Me and move it to Trash.","Open Trash and find the message about how long files stay there. Write it down.","Restore Delete Me. Check that it is back in My Drive.","Open Storage on the left side. Write down how much storage you use and the name of your largest file."]},{type:"callout",variant:"success",text:"Deliverable: Submit what you wrote down (the Trash message, your storage used, and your largest file) to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]}],j="/images/google-workspace/module-3",k=(a,b)=>b.map((b,c)=>({src:`${j}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),l=[{slug:"creating-and-formatting-documents",title:"Creating and Formatting Documents",description:"Start a document, then format text and paragraphs with the toolbar: fonts and sizes, bold and color, alignment, lists and checklists, line spacing, and paint format.",objectives:["Create a Google Doc from Drive, the Docs home screen, or a template","Change font, size, bold, italic, underline, and text color","Align paragraphs and set line and paragraph spacing","Make bulleted lists, numbered lists, and checklists","Copy formatting with Paint format and remove it with Clear formatting"],duration:"25 min",videoUrls:["https://www.youtube.com/embed/afQ7cjZTKDg","https://www.youtube.com/embed/OSh8VjfHX6Y"],slides:k("creating-and-formatting-documents",["Creating and formatting documents in Google Docs","Three ways to start a document","The Docs toolbar, left to right","Lists: bulleted, numbered, and checklists","Paint format copies formatting; Clear formatting removes it","Quick check: which button would you use?"]),sections:[{heading:"Starting a document",blocks:[{type:"scenario",role:"You prepare notices for Parkview's buildings.",text:"The city will shut off the water at Elm Street Apartments for repairs. Marcus typed the notice quickly, and it is one plain block of text. Tenants will skim it on the lobby board, so the time, the date, and what to do must jump out.",task:"Format the notice so the important information is easy to see."},{type:"table",caption:"Ways to start a Google Doc",columns:["From","How"],rows:[["Drive","Open the folder where it belongs, then New › Google Docs › Blank document. The file is saved in that folder."],["The Docs home screen","docs.google.com (or Docs in the Google apps menu), then Blank document or a template."],["An open document","File › New › Document, or File › New › From a template."]]},{type:"paragraph",text:"Name the document right away by clicking Untitled document at the top left. Then just type: there is no Save button, and Saved to Drive shows by the document status icon when your changes are stored."}]},{heading:"Formatting text and paragraphs",blocks:[{type:"table",caption:"The Docs toolbar and its Word equivalents",columns:["Toolbar control","What it does","In Word"],rows:[["Styles box (Normal text)","Paragraph style: Title, Heading 1, and more","Styles gallery"],["Font and Font size","Typeface and size; the minus and plus buttons step the size","Font group"],["Bold, Italic, Underline, Text color, Highlight color","Character formatting for the selected text","Font group"],["Align","Left, center, right, or justified","Paragraph group"],["Line & paragraph spacing","Single, 1.15, 1.5, double, and space before or after","Line and Paragraph Spacing"],["Checklist, Bulleted list, Numbered list","Lists","Bullets and Numbering"],["Paint format and Clear formatting","Copy formatting, or remove it","Format Painter and Clear All Formatting"]]},{type:"list",items:["Select first, then format. Click in a paragraph to format the whole paragraph (alignment, spacing, lists); select words to format only those words (bold, color).","The same commands are in the Format menu: Format › Text, Format › Align & indent, Format › Line & paragraph spacing, Format › Bullets & numbering.","Shortcuts match Word: Ctrl+B, Ctrl+I, Ctrl+U, Ctrl+Shift+E (center), Ctrl+Shift+7 (numbered list), Ctrl+Shift+8 (bulleted list).","If the toolbar is too narrow, the rest of the buttons are under More (the three dots) at its right end."]},{type:"drag-drop",mode:"match",title:"Match the button to the job",prompt:"Drag each toolbar control onto the job it does.",items:[{id:"b1",text:"Make the shutoff time stand out",match:"Bold"},{id:"b2",text:"Put the title in the middle of the line",match:"Center align"},{id:"b3",text:"Turn three instructions into a list",match:"Bulleted list"},{id:"b4",text:"Give tenants boxes to check off",match:"Checklist"},{id:"b5",text:"Copy the heading's look to another heading",match:"Paint format"}],explanation:"Character formatting (bold, color) acts on the words you select. Paragraph formatting (alignment, lists, spacing) acts on the whole paragraph you click in."},{type:"image",src:`${j}/creating-and-formatting-documents/docs-shortcuts.png`,alt:"Quick reference: where to format, structure, review, and finish in Google Docs, with the Word equivalents and common keyboard shortcuts",caption:"Google Docs at a glance. You will use the Structure, Review, and Finish tools in the next lessons."}]},{heading:"Lists, Paint format, and Clear formatting",blocks:[{type:"list",items:["Bulleted list: select the lines and click Bulleted list. Click the arrow next to it to choose a bullet style.","Numbered list: for steps that happen in order.","Checklist: each line gets a box you can click to check it off (the text is crossed out).","Paint format (the paint roller): click text with the formatting you want, click Paint format, then click or select the text to change. Double-click Paint format to apply it more than once.","Clear formatting (Ctrl+\\): returns the selected text to plain Normal text."]},{type:"worked-example",title:"Formatting the water shutoff notice",task:"Make a plain notice readable at a glance on the lobby board.",steps:[{move:"Center the title and make it 24 pt.",why:"Tenants see what the notice is about from across the lobby."},{move:"Bold the sentence with the shutoff time.",why:"The time is the one fact every tenant needs; bold makes it the first thing the eye lands on."},{move:"Turn the three to-do lines into a bulleted list.",why:"Lists are faster to skim than a paragraph."},{move:"Set the body to 1.5 line spacing.",why:"More space between lines is easier to read on a printed notice."}],result:"A notice tenants understand in a few seconds.",takeaway:"Format for the reader: the most important fact should be the easiest to see."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You click inside a paragraph without selecting anything and click Center align. What gets centered?",options:["Nothing, you must select text first","The whole paragraph","Only the word you clicked","The whole document"],correctIndex:1,explanation:"Alignment is paragraph formatting. Clicking anywhere in a paragraph is enough.",optionRationales:["Paragraph formatting does not need a selection.","Correct. Alignment applies to the whole paragraph.","Alignment never applies to single words.","Only the paragraph with the cursor (or the selected paragraphs) changes."]},{type:"knowledge-check",question:"You want three headings to look like the first one you formatted. What is the fastest way?",options:["Format each heading again by hand","Double-click Paint format, then click each heading","Copy and paste the first heading three times","Use Clear formatting"],correctIndex:1,explanation:"Double-clicking Paint format keeps it on so you can apply the formatting several times. (Even better for headings: paragraph styles, in the next lesson.)",optionRationales:["That works, but it is slow and easy to get slightly wrong.","Correct. Double-click keeps Paint format on until you click it again or press Esc.","Pasting copies the words too, not only the look.","Clear formatting removes formatting instead of copying it."]}]}],challenge:[{type:"paragraph",text:"Make a notice in your own Google account."},{type:"list",ordered:!0,items:["Create a Google Doc named Practice Notice - your name.","Type a title, one sentence with a time and place, and three instructions on their own lines.","Center the title and make it 24 pt. Bold the time and place.","Turn the three instructions into a bulleted list, and set the document to 1.5 line spacing.","Add a checklist of two items at the end, and check one off."]},{type:"callout",variant:"success",text:"Deliverable: Submit your notice as a PDF (File › Download › PDF Document) or share it with your instructor as a Viewer. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"headings-outline-and-page-setup",title:"Headings, the Outline, and Page Setup",description:"Give a long document real structure with paragraph styles, move around it with tabs and outlines, add a table of contents, headers, footers, page numbers, and breaks, and choose pages or pageless.",objectives:["Apply Title and Heading styles from the styles box, the Format menu, or Ctrl+Alt+1 to 6","Use the Show tabs & outlines panel to see and jump between headings","Insert a table of contents, header, footer, and page numbers with Insert › Page elements, and a page break with Insert › Break","Change page setup: pages or pageless, orientation, and margins"],duration:"25 min",videoUrl:"https://www.youtube.com/embed/4dNybOXJ9GU",slides:k("headings-outline-and-page-setup",["Headings, the outline, and page setup","Paragraph styles: Title, Heading 1, Heading 2","Show tabs & outlines: your document's map","Insert, then Page elements: table of contents, header, footer, page number","Pages or pageless?","Quick check: style, page element, or page setup?"]),sections:[{heading:"Headings are structure, not just big text",blocks:[{type:"scenario",role:"You are finishing the Parkview tenant handbook.",text:"The handbook is eight pages long. Every section title is just bold text, so there is no table of contents and readers scroll forever to find the parking rules. Denise wants proper headings, a table of contents, page numbers, and the company name at the top of every page before it is printed for new tenants.",task:"Structure the handbook with styles and page elements."},{type:"list",items:["Click the section title, open the styles box on the toolbar (it shows Normal text), and choose Heading 1. Use Heading 2 for sections inside a section.","Or use Format › Paragraph styles › Heading 1 › Apply 'Heading 1', or press Ctrl+Alt+1 (Ctrl+Alt+2 for Heading 2, Ctrl+Alt+0 for Normal text).","Use Title once, for the document's name at the top.","To change how every Heading 1 looks, format one heading, then choose Format › Paragraph styles › Heading 1 › Update 'Heading 1' to match."]},{type:"callout",variant:"info",text:"Headings are what the outline and the table of contents read. Bold, bigger Normal text looks like a heading, but Docs does not treat it as one."}]},{heading:"Tabs and outlines",blocks:[{type:"paragraph",text:"At the top left of a document, click Show tabs & outlines. A panel opens on the left with the document's tabs and, under each tab, an outline of its headings. Click a heading to jump to it. Click Hide tabs & outlines (the arrow at the top of the panel) to close it."},{type:"list",items:["Every document starts with one tab, Tab 1. Add tab in the panel adds another, like adding a sheet in Google Sheets. A tab is a good home for a separate part, such as an appendix of forms.","Tab options (the three dots next to a tab) let you rename it, choose an emoji, add a subtab, or hide its outline.","If you know Word: the outline works like Word's Navigation pane."]}]},{heading:"Page elements and breaks",blocks:[{type:"table",caption:"Insert › Page elements and Insert › Break",columns:["To add","Go to","Notes"],rows:[["Table of contents","Insert › Page elements › Table of contents","Built from your headings. After adding headings, click the table of contents and click Refresh to update it"],["Header or footer","Insert › Page elements › Header (or Footer)","Text that repeats on every page, like the company name"],["Page numbers","Insert › Page elements › Page number","Choose where the number goes"],["Footnote","Insert › Page elements › Footnote","A numbered note at the bottom of the page"],["Page break","Insert › Break › Page break (Ctrl+Enter)","Starts the next section on a new page"]]},{type:"drag-drop",mode:"sort",title:"Style, page element, or page setup?",prompt:"Sort each request by where you would go.",buckets:[{id:"style",label:"Paragraph style"},{id:"element",label:"Insert › Page elements or Break"},{id:"setup",label:"File › Page setup"}],items:[{id:"e1",text:"Make Parking Rules a Heading 1",bucket:"style"},{id:"e2",text:"Put Parkview Property Management at the top of every page",bucket:"element"},{id:"e3",text:"Number the pages",bucket:"element"},{id:"e4",text:"Turn the page sideways for a wide schedule",bucket:"setup"},{id:"e5",text:"Start the Forms section on a new page",bucket:"element"},{id:"e6",text:"Make the margins narrower",bucket:"setup"}],explanation:"Styles shape paragraphs, page elements add things that belong to pages, and page setup changes the page itself."}]},{heading:"Page setup: pages or pageless",blocks:[{type:"list",items:["File › Page setup opens a box with two choices at the top: Pages and Pageless. Click OK to apply, or Set as default to use it for new documents.","Pages shows separate pages, like Word. On the Pages tab you set orientation (portrait or landscape), paper size, page color, and margins.","Pageless is one long scroll, like a web page. Images and tables stretch to fit your screen. It is good for documents people only read on screen.","Pageless hides headers, footers, and watermarks (they come back if you switch to Pages) and turns off features such as columns and page numbers.","To switch quickly, use Format › Switch to Pageless format (or Switch to Pages format)."]},{type:"tip",text:"Anything that will be printed, like the handbook, belongs in Pages format. An internal how-to that people read on screen works well pageless."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You inserted a table of contents, then added two more Heading 1 sections. The table of contents does not show them. What do you do?",options:["Delete it and insert a new one","Click the table of contents and click Refresh","Type the headings into it by hand","Switch to pageless"],correctIndex:1,explanation:"The table of contents updates when you refresh it.",optionRationales:["That works, but Refresh is faster and keeps your choice of style.","Correct. Refresh rebuilds it from your current headings.","Typed entries would not update or link to the headings.","Pageless does not update the table of contents, and it limits how you can format one."]},{type:"knowledge-check",question:"Denise wants Parkview Property Management at the top of every printed page. Where do you go?",options:["File › Page setup","Insert › Page elements › Header","Format › Paragraph styles › Title","Insert › Break"],correctIndex:1,explanation:"A header repeats on every page. Type the name once in the header.",optionRationales:["Page setup changes the page size, orientation, and margins.","Correct. A header repeats on every page.","Title is a style for the first line, which appears only once.","Breaks start new pages; they do not add repeating text."]},{type:"knowledge-check",question:"You switch a document to Pageless. What happens to its header?",options:["It is deleted","It is hidden, and comes back if you switch to Pages","It moves to the end of the document","It turns into a heading"],correctIndex:1,explanation:"Pageless hides headers, footers, and watermarks without deleting them.",optionRationales:["Switching to pageless does not delete them.","Correct. Switch back to Pages and the header is there.","Headers are hidden, not moved.","Headers do not change into paragraphs."]}]}],challenge:[{type:"paragraph",text:"Structure a document of your own, such as notes from this course."},{type:"list",ordered:!0,items:["Create a document with a Title and at least three section titles, each with a sentence or two under it.","Make the section titles Heading 1 (Ctrl+Alt+1). Open Show tabs & outlines and check that all three appear.","Insert a table of contents at the top: Insert › Page elements › Table of contents.","Add a header with your name and page numbers: Insert › Page elements.","Insert a page break before the last section (Ctrl+Enter). Open File › Page setup and note whether the document is Pages or Pageless."]},{type:"callout",variant:"success",text:"Deliverable: Submit a PDF of the document (File › Download › PDF Document) to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"tables-images-and-smart-chips",title:"Tables, Images, Smart Chips, and Voice Typing",description:"Add tables and images, insert smart chips for people, dates, and files, drop in building blocks like meeting notes, and dictate with voice typing.",objectives:["Insert a table, type in it, and add or delete rows and columns","Insert an image from your computer, Drive and Photos, or a URL","Insert smart chips for a person, a date, and a file with @ or Insert › Smart chips","Add a building block such as Meeting notes","Start voice typing with Tools › Voice typing"],duration:"25 min",videoUrl:"https://www.youtube.com/embed/6PhT84sVcE8",slides:k("tables-images-and-smart-chips",["Tables, images, smart chips, and voice typing","Tables: Insert, then Table; right-click to add rows and columns","Images: upload, Stock & web, Drive & Photos, Camera, By URL","Smart chips: type @ for people, dates, and files","Building blocks and voice typing","Quick check: which tool fits?"]),sections:[{heading:"Tables",blocks:[{type:"scenario",role:"You write the weekly maintenance update for Elm Street Apartments.",text:"Kim Nguyen sends you the week's repairs in a text message, and Denise wants them in a tidy update: who prepared it, the date, a table of repairs, a photo of the finished work, and a link to the vendor list.",task:"Build the update with a table, an image, and smart chips."},{type:"list",items:["Click where the table goes, then Insert › Table and point to the size you want (columns x rows). Tables can be up to 20 x 20.","Click a cell to type. Press Tab to move to the next cell.","Right-click a cell for Insert row above, Insert row below, Insert column left, Insert column right, Delete row, Delete column, and Delete table.","Format › Table › Table options sets sizes, cell padding, and alignment. Under Row, Pin header row(s) repeats the header row on each page.","Right-click the table › Sort table to sort the rows in ascending or descending order."]}]},{heading:"Images",blocks:[{type:"list",items:["Click where the image goes, then Insert › Image and choose a source: Upload from computer, Stock & web, Drive & Photos, Camera, or By URL.","You can also drag an image file from your computer into the document.","Click the image to see its options: In line, Wrap text, Break text, Behind text, or In front of text. Drag a corner to resize it.","Only use images you have the right to use. Photos Parkview took, and the stock images Docs offers, are safe choices."]},{type:"callout",variant:"info",text:"In a pageless document, the text-wrapping layouts are not available; images stay in line with the text."}]},{heading:"Smart chips and building blocks",blocks:[{type:"paragraph",text:"A smart chip is a small, clickable box in the text for a person, a date, a file, a place, or a calendar event. Type @ anywhere in a document (or use Insert › Smart chips) and pick from the list. Hovering over a people chip shows the person's details; clicking a file chip opens the file."},{type:"table",caption:"Smart chips you will use most",columns:["Chip","How","Good for"],rows:[["People","Type @ and the person's name, then pick them","Who prepared a document, who owns a task"],["Date","Type @today, @tomorrow, @date, or a date such as @11/3/2026","Dates that everyone sees in the same format"],["File","Type @ and part of a file's name","A link to the vendor list or the lease form"]]},{type:"callout",variant:"warning",text:"A people chip does not share the document with that person. If they need to open it, share it with them separately."},{type:"paragraph",text:"Building blocks are ready-made pieces: Insert › Building blocks, or type @ and choose one. Meeting notes adds notes filled in with the details of a Google Calendar event you pick. Email draft adds an email with a To field, a subject, and a body that you can write together; when it is ready, click Preview in Gmail at the top left of the draft to open it in Gmail and send it."},{type:"drag-drop",mode:"match",title:"Which tool fits?",prompt:"Match each job to the tool for it.",items:[{id:"t1",text:"A grid of repairs: apartment, problem, status",match:"Table"},{id:"t2",text:"Show who prepared the update",match:"People chip"},{id:"t3",text:"Link the vendor list so readers can open it",match:"File chip"},{id:"t4",text:"A photo of the repaired faucet",match:"Insert › Image"},{id:"t5",text:"An agenda with attendees and action items",match:"Meeting notes building block"}],explanation:"Tables organize facts in rows and columns. Chips turn names, dates, and files into live links. Building blocks give you a ready-made layout."}]},{heading:"Voice typing",blocks:[{type:"list",ordered:!0,items:["Click where the text should go, then Tools › Voice typing. A microphone box appears.","Click the microphone (allow the browser to use it the first time) and speak clearly.","Say punctuation out loud: period, comma, exclamation point, question mark, new line, new paragraph.","Click the microphone again to stop. Check what was typed and fix mistakes."]},{type:"callout",variant:"info",text:"Voice typing works in the latest versions of Chrome, Edge, and Safari. Voice commands such as punctuation work only when the account and document language are English."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You add a people chip for Tony Russo to an update. Can Tony open the document now?",options:["Yes, a chip shares the document","Only if you also share the document with him","Only if he is at Parkview","Yes, as an Editor"],correctIndex:1,explanation:"Mentioning someone in a chip does not give them access. Share the document separately.",optionRationales:["Chips do not change sharing.","Correct. Share the document with Tony if he needs to open it.","Sharing, not his company, decides access.","A chip never grants any role."]},{type:"knowledge-check",question:"Your table needs one more row at the bottom. What do you do?",options:["Insert › Table again","Right-click a cell in the last row › Insert row below","Press Enter at the end of the table","Delete the table and start over"],correctIndex:1,explanation:"Right-click menus in a table add and remove rows and columns.",optionRationales:["That makes a second table.","Correct. Insert row below adds a row under the one you clicked.","Enter adds a new line inside the cell.","There is no need to start over."]}]}],challenge:[{type:"paragraph",text:"Build a one-page update in your own Google account."},{type:"list",ordered:!0,items:["Create a document named Weekly Update - your name. Type Prepared by: and insert a people chip for yourself (type @ and your name).","Type Date: and insert @today.","Insert a 3 x 3 table and fill in a header row (Task, Status, Notes) and two rows.","Insert an image from Stock & web.","Insert the Meeting notes building block at the end. Then try Tools › Voice typing to dictate one sentence (skip this step if your computer has no microphone)."]},{type:"callout",variant:"success",text:"Deliverable: Submit a PDF of your update to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"comments-suggestions-and-version-history",title:"Comments, Suggestions, and Version History",description:"Review documents with your team: comment, reply, and assign tasks, suggest edits instead of making them, accept or reject suggestions, and name and restore versions.",objectives:["Add a comment, reply to one, and resolve it","Assign a comment to a person with an @mention","Switch to Suggesting mode, suggest an edit, and accept or reject suggestions","Open version history, name the current version, and restore an earlier one"],duration:"25 min",slides:k("comments-suggestions-and-version-history",["Reviewing together: comments, suggestions, and version history","Comments: Ctrl+Alt+M, reply, resolve","Assign a comment with an @mention","Suggesting mode: edits become suggestions the owner accepts or rejects","Version history: name versions, restore old ones","Quick check: comment, suggest, or restore?"]),sections:[{heading:"Comments",blocks:[{type:"scenario",role:"You own the draft of Parkview's new pet policy.",text:"Denise and Marcus have read the draft. Denise left a comment, Marcus suggested two changes, and Priya still needs to confirm the monthly pet fee. You need to work through the feedback without losing track of the original wording.",task:"Handle comments and suggestions, assign the open question, and mark the reviewed version."},{type:"list",items:["Select the text, then click Add comment on the toolbar, choose Insert › Comment, or press Ctrl+Alt+M. Type the comment and click Comment.","Comments show in the right margin, attached to the text. Click one to reply.","When a comment is handled, click Resolve (the check mark in the top corner of the comment) to close it. To see closed comments again, click Comments at the top right; Re-open brings one back.","To assign a comment, type @ and the person's name in it, check Assign to, and click Assign. The person is notified and is responsible for marking it done."]}]},{heading:"Suggesting mode",blocks:[{type:"paragraph",text:"In Suggesting mode, your edits do not change the text. They appear as colored suggestions with your name, and the document's editors accept or reject each one. It is the Google Docs version of Word's Track Changes."},{type:"list",items:["Switch modes with the mode button at the right end of the toolbar (it shows Editing): choose Suggesting. Or use View › Mode › Suggesting, or press Ctrl+Alt+Shift+X.","Type, delete, or replace text as usual. Each change becomes a suggestion card in the margin.","To accept or reject one, click the check mark or the X on its card. Tools › Review suggested edits shows them all, with Accept all and Reject all.","Viewing mode shows the document without suggestions or comments, as it would print."]},{type:"drag-drop",mode:"sort",title:"Comment, suggest, or edit?",prompt:"Sort what you would do in each case.",buckets:[{id:"comment",label:"Add a comment"},{id:"suggest",label:"Suggest an edit"},{id:"edit",label:"Edit directly"}],items:[{id:"x1",text:"You think the fee is wrong but are not sure, and want Priya to check",bucket:"comment"},{id:"x2",text:"Denise's document: you want to change one sentence and let her decide",bucket:"suggest"},{id:"x3",text:"Your own draft has a typo",bucket:"edit"},{id:"x4",text:"You have a question about what a rule means",bucket:"comment"},{id:"x5",text:"Marcus's notice: you would reword the second paragraph",bucket:"suggest"}],explanation:"Comment to ask or discuss, suggest to propose a change in someone else's document, and edit directly in your own work."}]},{heading:"Version history",blocks:[{type:"list",items:["Open it with the Last edit (clock) icon at the top right, File › Version history › See version history, or Ctrl+Alt+Shift+H.","Click a version on the right to see what it looked like and who changed what.","Restore: choose the earlier version, click Restore this version at the top, then click Restore. The file goes back to the way it was in that version.","Name a version to find it later: File › Version history › Name current version, or in the list, choose More › Name this version. A document can have up to 40 named versions.","Only people who can edit the file can see its version history."]},{type:"worked-example",title:"Marking the reviewed pet policy",task:"The team has reviewed the draft, and you expect more changes later.",steps:[{move:"Accept and reject the suggestions, and resolve the comments that are handled.",why:"The margin should show only what is still open."},{move:"File › Version history › Name current version: Reviewed by office.",why:"If later edits go wrong, you can find and restore this exact version by name."}],result:"A clean draft, plus a named version to return to.",takeaway:"Name a version at every milestone: first draft, reviewed, final."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You want Denise to decide whether to change a sentence in her document. What do you use?",options:["Edit it directly","Suggesting mode","Delete the sentence","Version history"],correctIndex:1,explanation:"A suggestion shows your change without making it, and Denise accepts or rejects it.",optionRationales:["Editing changes her text without asking.","Correct. Suggesting mode lets her decide.","Deleting changes the text directly.","Version history restores old versions; it is not for proposing changes."]},{type:"knowledge-check",question:"Someone pasted over half of the policy by mistake. How do you get the old text back?",options:["Press Ctrl+S","Open version history and restore the earlier version","Ask Google to recover it","It cannot be recovered"],correctIndex:1,explanation:"Version history keeps earlier versions. Restoring one keeps the current text as a version too.",optionRationales:["Docs has no Save to undo; changes are already saved.","Correct. Restore this version brings back the earlier text.","You can do it yourself in seconds.","Version history makes it recoverable."]}]}],challenge:[{type:"paragraph",text:"Review a document with a classmate or a second account of your own."},{type:"list",ordered:!0,items:["Share a practice document with your partner as a Commenter.","Ask them to add a comment and to suggest one change in Suggesting mode.","Reply to the comment and resolve it. Accept or reject the suggestion.","Name the current version Reviewed. Then make an edit and restore the Reviewed version from version history."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of version history showing your named version to your instructor or course folder. No partner? Complete the practice simulation and submit its results page."}]},{slug:"proofreading-printing-and-sending",title:"Proofreading, Printing, and Sending Documents",description:"Finish a document the professional way: check spelling and grammar, use word count and find and replace, then print, download, email, or copy it.",objectives:["Check spelling and grammar and fix or ignore each suggestion","Use Word count and Find and replace","Print a document or save it as a PDF from the Print box","Email a document as an attachment and make a copy for a new purpose"],duration:"20 min",slides:k("proofreading-printing-and-sending",["Proofreading, printing, and sending","Spelling and grammar: change, ignore, or fix it yourself","Word count and Find and replace","Print: printer or Save as PDF","Send: download, email as an attachment, or make a copy","Quick check: which finishing step?"]),sections:[{heading:"Proofread before anyone else reads it",blocks:[{type:"scenario",role:"You are sending the move-in letter to a new tenant at Elm Street Apartments.",text:"The letter has a spelling mistake, it says Elm St. in some places and Elm Street in others, and it must be printed for the move-in packet and emailed to the tenant as a PDF. Denise also wants a copy to reuse for the next new tenant.",task:"Proofread, print, and send the letter, and keep a reusable copy."},{type:"list",items:["When spelling and grammar suggestions are on, Docs underlines misspelled words in red and grammar suggestions in blue. Right-click an underlined word and click the suggested word to accept it, or click Ignore.","To go through the whole document, click Spelling and grammar check on the toolbar (at the top left). A box opens at the top right: click Change to use a suggestion or Ignore to skip it. More › Accept all or Ignore all handles every suggestion at once.","Read it yourself too. A checker cannot tell that you typed the wrong apartment number."]}]},{heading:"Word count and Find and replace",blocks:[{type:"list",items:["Tools › Word count (Ctrl+Shift+C) shows pages, words, and characters. Check Display word count while typing to keep a count on screen.","Edit › Find and replace (Ctrl+H): type what to find and what to replace it with, then click Replace or Replace all. Check Match case when capital letters matter."]},{type:"drag-drop",mode:"order",title:"Finish a document in order",prompt:"Put the finishing steps in a sensible order.",items:[{id:"s1",text:"Run Spelling and grammar check"},{id:"s2",text:"Use Find and replace to make names consistent"},{id:"s3",text:"Read the whole document yourself"},{id:"s4",text:"Print or download the final copy"},{id:"s5",text:"Send it to the reader"}],explanation:"Fix errors first, then read it as the reader will, and only then print or send. Every copy you send is a copy you cannot fix later."}]},{heading:"Print, download, email, or copy",blocks:[{type:"table",caption:"Ways to get a document to someone",columns:["Task","How"],rows:[["Print","File › Print (Ctrl+P). Choose the printer as the Destination, set copies, and click Print."],["Save a PDF on the computer","File › Download › PDF Document (.pdf), or in the Print box choose Save as PDF as the Destination."],["Email it as an attachment","File › Email › Email this file. Enter the address and subject, choose the format (such as PDF), and click Send."],["Email everyone working on it","File › Email › Email collaborators."],["Reuse it for something new","File › Make a copy. Give the copy a name; the original stays as it is."]]},{type:"callout",variant:"warning",text:"Before you email a document outside Parkview, check that it contains only what the reader should see. Delete comments and suggestions, or send a PDF, so internal notes do not go out with it."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"The letter says Elm St. in six places. You want them all to say Elm Street. What is fastest?",options:["Fix each by hand","Edit › Find and replace, then Replace all","Spelling and grammar check","Word count"],correctIndex:1,explanation:"Find and replace changes every match at once.",optionRationales:["It works, but it is slow and easy to miss one.","Correct. Replace all fixes all six at once.","Elm St. is not a spelling mistake, so the checker will not flag it.","Word count only counts."]},{type:"knowledge-check",question:"You need next month's move-in letter to start from this one, without changing this one. What do you do?",options:["Edit this letter next month","File › Make a copy","Download it as Word","Rename it"],correctIndex:1,explanation:"Make a copy creates a separate file you can change freely.",optionRationales:["Then this tenant's letter would change too.","Correct. The copy is a new file; the original stays as it is.","A download is a copy on your computer, outside Drive.","Renaming does not make a second file."]}]}],challenge:[{type:"paragraph",text:"Finish a document in your own account."},{type:"list",ordered:!0,items:["Open any practice document and click Spelling and grammar check on the toolbar. Change or ignore each suggestion.","Use Edit › Find and replace to replace one word everywhere it appears.","Open File › Print and choose Save as PDF as the Destination. Save the PDF.","Use File › Make a copy to make a copy named Copy for Next Time."]},{type:"callout",variant:"success",text:"Deliverable: Submit the PDF you saved to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]}],m="/images/google-workspace/module-4",n=(a,b)=>b.map((b,c)=>({src:`${m}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),o=[{slug:"sheets-basics-and-formatting",title:"Spreadsheet Basics: Entering and Formatting Data",description:"Learn the Sheets screen, enter and edit data, format cells and numbers, freeze the header row, and work with sheet tabs.",objectives:["Name the parts of the Sheets screen: cells, rows, columns, the name box, the formula bar, and sheet tabs","Enter, edit, and clear data, and move between cells with Enter and Tab","Format cells: bold, fill color, borders, and number formats such as currency and dates","Freeze the header row, and add and rename sheets"],duration:"25 min",videoUrls:["https://www.youtube.com/embed/pFUwRebuAd0","https://www.youtube.com/embed/-SJYIQTOehQ"],slides:n("sheets-basics-and-formatting",["Spreadsheet basics in Google Sheets","The Sheets screen: cells, name box, formula bar, sheet tabs","Entering data: Enter moves down, Tab moves right","Formatting cells and number formats","Freeze the header row; add and rename sheets","Quick check: which tool fits?"]),sections:[{heading:"The Sheets screen",blocks:[{type:"scenario",role:"You keep Parkview's rent roll.",text:"Priya, the bookkeeper, keeps the rent roll for Elm Street Apartments in a Google Sheet. It is hard to read: the headers look like the data, the rents have no dollar signs, and the header row scrolls away when you look at the bottom of the list. A new tenant also needs to be added.",task:"Add the new tenant and format the sheet so anyone can read it."},{type:"table",caption:"Parts of a Google Sheet",columns:["Part","What it is","Same in Excel?"],rows:[["Cell","One box, named by column letter and row number, like B4","Yes"],["Name box","Left of the formula bar; shows the selected cell and lets you jump to one","Yes"],["Formula bar (fx)","Shows what is really in the cell: text, a number, or a formula","Yes"],["Sheet tabs","At the bottom; one spreadsheet can hold many sheets. + adds a sheet","Yes (worksheets)"],["Toolbar","Undo, print, number formats, font, bold, fill color, borders, and more","Like the Home tab"]]},{type:"list",items:["Click a cell and type. Press Enter to save the entry and move down, or Tab to move right.","To change a cell, click it and type over it, or double-click it (or press F2) to edit part of it.","To clear cells, select them and press Delete.","Like Docs, Sheets saves every change to Drive. There is no Save button."]}]},{heading:"Formatting cells and numbers",blocks:[{type:"list",items:["Select the cells first: click and drag, or click a column letter or row number to select the whole column or row.","Bold, text color, Fill color, Borders, and Merge cells are on the toolbar.","Number formats: Format as currency ($) and Format as percent (%) are on the toolbar. More formats (123) and Format › Number list the rest: Number, Date, Time, Accounting, and more.","Shortcuts: Ctrl+Shift+4 currency, Ctrl+Shift+5 percent, Ctrl+Shift+1 number with decimals.","Decrease or increase decimal places with the .0 and .00 buttons.","Widen a column: drag the line at the right edge of its letter, or double-click that line to fit the longest entry."]},{type:"callout",variant:"info",text:"A number format changes how a number looks, not the number. 1450 formatted as currency shows $1,450.00, and formulas still use 1450."},{type:"image",src:`${m}/sheets-basics-and-formatting/sheets-and-excel.png`,alt:"Quick reference: where formatting, calculating, organizing, and sharing tools are in Google Sheets, for people who know Excel, with common shortcuts",caption:"Google Sheets for Excel users. You will use every tool on this sheet in this module."},{type:"drag-drop",mode:"match",title:"Pick the format",prompt:"Match each column to the number format it needs.",items:[{id:"n1",text:"Monthly rent",match:"Currency"},{id:"n2",text:"Share of apartments rented",match:"Percent"},{id:"n3",text:"Lease end",match:"Date"},{id:"n4",text:"Number of bedrooms",match:"Number (no decimals)"}],explanation:"Choose the format readers expect: dollar signs for money, a percent sign for shares, and a date format for dates."}]},{heading:"Freeze rows and work with sheets",blocks:[{type:"list",items:["View › Freeze › 1 row keeps the header row on screen while you scroll. Choose No rows to unfreeze.","Add a sheet with + at the bottom left (or Shift+F11). Double-click a sheet tab to rename it.","Right-click a tab to duplicate, delete, color, hide, or protect a sheet."]},{type:"worked-example",title:"Making the rent roll readable",task:"Turn a plain list into a rent roll anyone can read.",steps:[{move:"Bold the header row and give it a light fill color.",why:"Readers instantly tell the labels from the data."},{move:"Format the rent column as currency.",why:"Dollar signs and two decimals show it is money."},{move:"View › Freeze › 1 row.",why:"The labels stay visible at the bottom of a long list."},{move:"Rename the tab Elm Street.",why:"When Riverside gets its own tab, everyone knows which is which."}],result:"A rent roll that is easy to scan and hard to misread.",takeaway:"Format the header, the numbers, and the tabs before you share a sheet."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"C4 shows $1,450.00. What does the formula bar show when you click C4?",options:["$1,450.00","1450","C4","Currency"],correctIndex:1,explanation:"The formula bar shows the value in the cell. Currency is only how it is displayed.",optionRationales:["That is the display. The formula bar shows the stored value.","Correct. The value is 1450; the format adds the dollar sign and decimals.","C4 is the cell's name, shown in the name box.","Currency is the format, not the content."]},{type:"knowledge-check",question:"The header row disappears when you scroll to row 80. What fixes it?",options:["Bold the header row","View › Freeze › 1 row","Sort the sheet","Insert a new sheet"],correctIndex:1,explanation:"Freezing keeps rows on screen while the rest scrolls.",optionRationales:["Bold makes the header stand out but does not keep it on screen.","Correct. Freeze 1 row keeps the header visible.","Sorting reorders data; it does not keep the header visible.","A new sheet does not change scrolling."]}]}],challenge:[{type:"paragraph",text:"Build a small list in your own Google account."},{type:"list",ordered:!0,items:["Create a spreadsheet named Budget Practice. In row 1, type Item, Category, Cost, and Date.","Enter at least five rows of practice expenses (use Tab to move right and Enter to move down).","Bold the header row and give it a fill color. Format the Cost column as currency and the Date column as a date.","Freeze the header row. Rename the sheet tab Expenses."]},{type:"callout",variant:"success",text:"Deliverable: Share the spreadsheet with your instructor as a Viewer, or submit a screenshot, to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"formulas-and-functions",title:"Formulas and Functions",description:"Calculate with formulas, use SUM, AVERAGE, MIN, MAX, COUNT, IF, and COUNTIF, copy formulas with the fill handle, and lock a reference with a dollar sign.",objectives:["Write formulas that start with = and use cell references","Use SUM, AVERAGE, MIN, MAX, COUNT, and COUNTA","Copy a formula with the fill handle or Ctrl+D, and explain relative and absolute references","Make decisions with IF and count matches with COUNTIF"],duration:"30 min",videoUrls:["https://www.youtube.com/embed/n_Vys5oPmTY","https://www.youtube.com/embed/aa58VJqZJ3g"],slides:n("formulas-and-functions",["Formulas and functions in Google Sheets","Every formula starts with =","Functions you will use every week","The fill handle copies formulas; references adjust","Lock a reference with $ (F4)","Quick check: which formula?"]),sections:[{heading:"Formulas",blocks:[{type:"scenario",role:"You track repair costs for Kim Nguyen.",text:"Kim keeps the cost of every repair in a sheet: parts and labor. Denise wants the total for each repair, the totals for the month, and a flag on any repair that went over Parkview's $300 limit, without anyone adding numbers on a calculator.",task:"Let the sheet do the math."},{type:"list",items:["A formula starts with an equals sign: =C2+D2 adds the values in C2 and D2.","Operators: + add, - subtract, * multiply, / divide, and parentheses for order: =(C2+D2)*1.08.","Type the formula and press Enter. The cell shows the result; the formula bar shows the formula.","Instead of typing a reference, you can click the cell while you type the formula.","When a referenced cell changes, the result updates by itself."]}]},{heading:"Functions",blocks:[{type:"table",caption:"Functions you will use every week",columns:["Function","What it does","Example"],rows:[["SUM","Adds a range","=SUM(E2:E8)"],["AVERAGE","The average of a range","=AVERAGE(E2:E8)"],["MIN and MAX","The smallest and largest value","=MAX(E2:E8)"],["COUNT and COUNTA","Counts cells with numbers; counts cells that are not empty","=COUNTA(A2:A8)"],["IF","One result if a test is true, another if not",'=IF(E2>300,"Over","OK")'],["COUNTIF","Counts cells that match a condition",'=COUNTIF(F2:F8,"Over")']]},{type:"list",items:["Insert › Function, or Functions (Σ) on the toolbar, starts a function for you.","As you type =SU, Sheets suggests matching functions and shows a help box with what each part means.","Select a range of numbers and look at the bottom right: Sheets shows their sum without a formula.","If you know Excel: these functions, and many more such as VLOOKUP and XLOOKUP, work the same way."]},{type:"drag-drop",mode:"match",title:"Which function?",prompt:"Match each question to the function that answers it.",items:[{id:"fx1",text:"What did all the repairs cost together?",match:"SUM"},{id:"fx2",text:"What does a typical repair cost?",match:"AVERAGE"},{id:"fx3",text:"What was the most expensive repair?",match:"MAX"},{id:"fx4",text:"Was this repair over the limit?",match:"IF"},{id:"fx5",text:"How many repairs went over the limit?",match:"COUNTIF"}],explanation:"SUM adds, AVERAGE finds the typical value, MAX finds the largest, IF makes a yes-or-no decision, and COUNTIF counts how many match."}]},{heading:"Copying formulas: relative and absolute references",blocks:[{type:"list",items:["Click the cell with the formula and drag the small blue square at its bottom right corner (the fill handle) down the column. Or select the cell and the cells below and press Ctrl+D.","References change as the formula is copied: =C2+D2 in row 2 becomes =C3+D3 in row 3. These are relative references.","To keep a reference from changing, add dollar signs: $H$2 always points to H2. Press F4 while typing a reference to add them."]},{type:"worked-example",title:"Flagging repairs over the limit",task:"The $300 limit is in H2. Flag each repair in column F.",steps:[{move:'In F2, type =IF(E2>$H$2,"Over","OK").',why:"E2 should change row by row, but every row must compare with the same limit in H2."},{move:"Fill F2 down to F8.",why:"Each row gets its own test: E3, E4, and so on, always against $H$2."},{move:'In F10, type =COUNTIF(F2:F8,"Over").',why:"Denise wants one number: how many went over."}],result:"Every repair is flagged, and the count updates when Kim changes a cost or Denise changes the limit.",takeaway:"Put values that may change, like a limit or a tax rate, in their own cell and point to it with $."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You copy =C2+D2 from E2 down to E3. What is the formula in E3?",options:["=C2+D2","=C3+D3","=$C$3+$D$3","=E2"],correctIndex:1,explanation:"Relative references move with the formula: one row down, so row 2 becomes row 3.",optionRationales:["That would happen only with absolute references ($C$2).","Correct. Relative references adjust to the new row.","Copying does not add dollar signs.","The fill handle copies the formula, not a reference to the cell above."]},{type:"knowledge-check",question:"Every row must compare its total with the limit in H2. Which reference do you use for the limit?",options:["H2","$H$2","H$","=H2"],correctIndex:1,explanation:"$H$2 stays the same in every row when the formula is copied.",optionRationales:["H2 would become H3, H4, and so on as you fill down.","Correct. The dollar signs lock both the column and the row.","That is not a valid reference.","The equals sign starts a formula; it does not lock a reference."]}]}],challenge:[{type:"paragraph",text:"Add formulas to the Budget Practice sheet from the last lesson (or make a new list of five costs)."},{type:"list",ordered:!0,items:["Below the costs, use SUM for the total, AVERAGE for the average, and MAX for the highest cost.","Type a spending limit in a cell to the right, such as 50.","In a new column, use IF with an absolute reference to the limit to show Over or OK, and fill it down.","Use COUNTIF to count how many items are Over."]},{type:"callout",variant:"success",text:"Deliverable: Share the spreadsheet with your instructor as a Viewer, or submit a screenshot showing the formula bar for your IF formula. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"sort-filter-and-conditional-formatting",title:"Sorting, Filtering, and Conditional Formatting",description:"Sort a range, filter rows, save a filter view that only changes your view, highlight what matters with conditional formatting, and turn a list into a table.",objectives:["Sort a range with a header row using Data › Sort range","Filter rows with Data › Create a filter","Create and save a filter view that does not change what others see","Highlight cells with conditional formatting rules","Convert a range to a table with Format › Convert to table"],duration:"30 min",slides:n("sort-filter-and-conditional-formatting",["Sorting, filtering, and conditional formatting","Sort range: include the header row, choose the column","Filters change what everyone sees; filter views change only your view","Conditional formatting: rules that color cells for you","Tables: Format, then Convert to table","Quick check: filter, filter view, or rule?"]),sections:[{heading:"Sorting",blocks:[{type:"scenario",role:"You keep the maintenance request log with Kim.",text:"The log has dozens of requests from both buildings. Kim wants the requests grouped by building, Denise wants to see only what is still open, Marcus wants his own Riverside view without changing anyone else's, and the high-priority requests should stand out at a glance.",task:"Sort, filter, and highlight the log for each person's needs."},{type:"list",ordered:!0,items:["Select the data, including the header row.","Data › Sort range › Advanced range sorting options.","Check Data has header row, choose the column to sort by, and choose A to Z or Z to A. Add another sort column for a second level.","Click Sort."]},{type:"callout",variant:"warning",text:"Select every column of the data before you sort. If you sort only one column, it no longer lines up with the rest of its row, and the log is scrambled. If that happens, press Ctrl+Z right away."}]},{heading:"Filters and filter views",blocks:[{type:"list",items:["Filter: select the data and choose Data › Create a filter (or right-click › Create a filter). Click the filter button in a header to filter by values, by condition, or by color. Data › Remove filter turns it off.","A filter changes the sheet for everyone who has it open, and anyone who can edit can change it.","Filter view: Data › Create filter view. Filter or sort, then click Save view at the top right, name it, and click Save. It changes only your view, so several people can use different views at the same time.","Find saved views later with Data › Change view."]},{type:"drag-drop",mode:"sort",title:"Filter or filter view?",prompt:"Sort each situation.",buckets:[{id:"filter",label:"Filter (everyone sees it)"},{id:"view",label:"Filter view (only your view)"}],items:[{id:"v1",text:"Marcus wants to see only Riverside requests while Kim works on Elm Street",bucket:"view"},{id:"v2",text:"You are alone in the sheet and want a quick look at open requests",bucket:"filter"},{id:"v3",text:"Denise wants a saved view of high-priority requests she can reopen every morning",bucket:"view"},{id:"v4",text:"Three people are editing at once and each needs a different list",bucket:"view"}],explanation:"When others are working in the same sheet, use a filter view so you do not change their screen. Save it if you will want it again."}]},{heading:"Conditional formatting and tables",blocks:[{type:"list",ordered:!0,items:["Select the cells, then Format › Conditional formatting. The Conditional format rules panel opens on the right.","Under Format cells if…, choose a condition, such as Text is exactly, Greater than, or Is empty, and type the value.","Under Formatting style, choose how matching cells look.","Click Done. The rule keeps working as data changes."]},{type:"paragraph",text:"A table turns a range into a structured list: select the data and choose Format › Convert to table. The table gets a header style and a name, and you can set a type for each column (such as number, date, dropdown, or checkbox) so entries that do not fit are flagged."},{type:"table",caption:"If you know Excel",columns:["Google Sheets","Excel"],rows:[["Data › Sort range","Data › Sort"],["Data › Create a filter","Data › Filter"],["Data › Create filter view","Sheet views (in shared workbooks)"],["Format › Conditional formatting","Home › Conditional Formatting"],["Format › Convert to table","Insert › Table"]]}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Kim and Marcus are both in the log. Marcus wants to see only Riverside rows without changing Kim's screen. What should he use?",options:["Data › Create a filter","Data › Create filter view","Sort the sheet by building","Delete the Elm Street rows"],correctIndex:1,explanation:"A filter view changes only Marcus's view.",optionRationales:["A filter changes the sheet for everyone, including Kim.","Correct. A filter view affects only the person using it.","Sorting reorders the rows for everyone and still shows Elm Street.","Deleting data is never the way to hide it."]},{type:"knowledge-check",question:"You want every High priority cell to turn red automatically, now and when new requests are added. What do you use?",options:["Fill color on each cell","A conditional formatting rule","A filter","Bold"],correctIndex:1,explanation:"A conditional formatting rule checks the cells for you and keeps working as data changes.",optionRationales:["Manual fill must be redone for every new request.","Correct. Text is exactly High with a red fill keeps working automatically.","A filter hides rows; it does not color them.","Bold is manual formatting too."]}]}],challenge:[{type:"paragraph",text:"Use your Budget Practice sheet (add more rows if it has fewer than eight)."},{type:"list",ordered:!0,items:["Sort the data by Category, A to Z, with Data has header row checked.","Create a filter and show only one category. Then remove the filter.","Create a filter view that shows only costs over a number you choose. Save it with a name.","Add a conditional formatting rule that colors costs greater than your limit."]},{type:"callout",variant:"success",text:"Deliverable: Share the spreadsheet with your instructor as a Viewer and tell them the name of your saved filter view, or submit screenshots. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"charts-and-pivot-tables",title:"Charts and Pivot Tables",description:"Turn numbers into a chart with Insert › Chart and the chart editor, and summarize a long list with a pivot table.",objectives:["Insert a chart from selected data and change its type in the chart editor's Setup tab","Add a chart title in the Customize tab","Create a pivot table on a new sheet and add rows, columns, and values","Explain when a chart or a pivot table is the better tool"],duration:"25 min",slides:n("charts-and-pivot-tables",["Charts and pivot tables","Insert, then Chart: select the data first","The chart editor: Setup and Customize","Pick the chart that fits the question","Pivot tables summarize long lists","Quick check: chart or pivot table?"]),sections:[{heading:"Charts",blocks:[{type:"scenario",role:"You prepare numbers for the monthly owners' meeting.",text:"Marcus presents to the building owners each month. He wants a chart of repair requests by month, and a summary of rent by building from the 40-row rent roll, without retyping any numbers.",task:"Make the chart and the summary from the data you already have."},{type:"list",ordered:!0,items:["Select the data, including the labels (for example, Month and Repairs).","Insert › Chart. Sheets picks a chart type and opens the chart editor on the right.","On the Setup tab, choose a different Chart type if you need one, and check the data range.","On the Customize tab, open Chart & axis title to type a title and change its font.","Drag the chart to move it; drag the blue markers to resize it. Double-click it to reopen the chart editor."]},{type:"table",caption:"Pick the chart that fits the question",columns:["Question","Chart"],rows:[["How do the months compare?","Column chart"],["Is it going up or down over time?","Line chart"],["What share does each part make up?","Pie chart (a few parts only)"],["Which of many items is biggest?","Bar chart"]]},{type:"drag-drop",mode:"match",title:"Match the chart",prompt:"Match each question to the best chart.",items:[{id:"c1",text:"Are repair requests rising month by month?",match:"Line chart"},{id:"c2",text:"Which building had more requests in October?",match:"Column chart"},{id:"c3",text:"What share of apartments are one-bedroom units?",match:"Pie chart"}],explanation:"Lines show change over time, columns compare amounts, and pies show parts of a whole when there are only a few parts."}]},{heading:"Pivot tables",blocks:[{type:"paragraph",text:"A pivot table summarizes a long list: total rent by building, number of repairs by type, average cost by vendor. You do not write formulas; you choose which column to group by and which to add up."},{type:"list",ordered:!0,items:["Select the data. Every column needs a header.","Insert › Pivot table. Check the data range, choose New sheet, and click Create.","In the pivot table editor on the right, next to Rows, click Add and pick a column to group by (Building).","Next to Values, click Add and pick the column to summarize (Rent). Sheets adds it up with SUM; choose another way, like AVERAGE or COUNTA, under Summarize by.","Add a field under Columns to split the summary across the top (Status).","The pivot table updates when the source data changes. Click it and choose Edit to reopen the editor."]},{type:"callout",variant:"info",text:"Sheets may show Suggested pivot tables in the editor. They can be a good start; check that they answer your question."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Marcus needs total rent for each building from a 40-row rent roll. What is fastest?",options:["Add the rents on a calculator","A pivot table with Building in Rows and Rent in Values","A pie chart","Sort the sheet"],correctIndex:1,explanation:"A pivot table groups the rows by building and adds the rents for you.",optionRationales:["Slow, and the result would not update.","Correct. Rows group by building; Values sums the rent.","A chart shows numbers; it does not compute the totals by building table.","Sorting groups rows but does not total them."]},{type:"knowledge-check",question:"Where do you change a chart's title?",options:["Setup tab","Customize tab › Chart & axis title","Format › Number","Data › Sort range"],correctIndex:1,explanation:"Titles and fonts are on the Customize tab of the chart editor.",optionRationales:["Setup is for the chart type and the data range.","Correct. Customize › Chart & axis title.","Number formats change cells, not the chart title.","Sorting changes the data order."]}]}],challenge:[{type:"paragraph",text:"Use your Budget Practice sheet."},{type:"list",ordered:!0,items:["Select the Category and Cost columns and insert a chart. Change it to a column chart and give it a title.","Create a pivot table on a new sheet with Category in Rows and Cost in Values.","Change one cost in your data and check that the pivot table and chart update."]},{type:"callout",variant:"success",text:"Deliverable: Share the spreadsheet with your instructor as a Viewer, or submit a screenshot of your chart and pivot table. No Google account? Complete the practice simulation and submit its results page."}]},{slug:"dropdowns-protection-and-sharing-sheets",title:"Dropdowns, Protected Ranges, and Sharing Sheets",description:"Keep shared sheets clean with dropdowns and checkboxes, protect formulas from accidental edits, leave notes and comments, and download a sheet as Excel or CSV.",objectives:["Add a dropdown with Insert › Dropdown or Data › Data validation, and add checkboxes","Protect a range so only you can edit it, and explain why protection is not a security measure","Choose between a note and a comment","Share a sheet and download it as Microsoft Excel or CSV"],duration:"25 min",slides:n("dropdowns-protection-and-sharing-sheets",["Dropdowns, protected ranges, and sharing sheets","Dropdowns keep entries consistent","Checkboxes: Insert, then Checkbox","Protect sheets and ranges","Notes or comments?","Quick check: which tool fits?"]),sections:[{heading:"Dropdowns and checkboxes",blocks:[{type:"scenario",role:"You manage the shared supply order sheet.",text:"Four people add items to the monthly supply order. Categories are typed five different ways (cleaning, Cleaning, cleaning supplies), someone typed over the Total formulas last month, and Priya needs a copy in Excel for the accounting system.",task:"Make the sheet hard to break, then share and download it."},{type:"list",items:["Select the cells, then Insert › Dropdown (or Data › Data validation › Add rule, or right-click › Dropdown). The Data validation rules panel opens.","Under Criteria, keep Dropdown and type each option, clicking Add another item for more. Choose Dropdown from a range to use a list already in the sheet.","Advanced options: under If the data is invalid, entries that are not on the list are rejected by default; choose Show a warning to allow them with a warning. Display style can be Chip, Arrow, or Plain text.","Click Done. A dropdown appears in each cell.","Checkboxes: select the cells and choose Insert › Checkbox. Click a box to check it. You can use checkboxes with filters, charts, pivot tables, and functions."]}]},{heading:"Protecting formulas",blocks:[{type:"list",ordered:!0,items:["Select the cells, then Data › Protect sheets and ranges. A panel opens on the right.","Click Add a sheet or range. Check the Range (or choose Sheet), and type a description.","Click Set permissions. Choose Restrict who can edit this range and pick Only you (or Custom to add people), or choose Show a warning when editing this range.","Click Done."]},{type:"callout",variant:"warning",text:"Protection prevents accidents; it is not a security measure. People who can view the sheet can still print, copy, paste, and export protected content. Share sheets only with people who should see what is in them."},{type:"table",caption:"Notes or comments?",columns:["","Note","Comment"],rows:[["Add it","Right-click › Insert note, or Shift+F2","Right-click › Comment, or Ctrl+Alt+M"],["Looks like","A small black triangle in the cell's corner","A yellow triangle, with the discussion in a card"],["Use it for","A quiet explanation, like Price went up in October","A question or task for someone, with replies and @mentions"]]},{type:"drag-drop",mode:"sort",title:"Which tool fits?",prompt:"Sort each request.",buckets:[{id:"dropdown",label:"Dropdown"},{id:"protect",label:"Protected range"},{id:"note",label:"Note"},{id:"comment",label:"Comment"}],items:[{id:"d1",text:"Everyone must pick the category from the same three choices",bucket:"dropdown"},{id:"d2",text:"Nobody but you should change the Total formulas",bucket:"protect"},{id:"d3",text:"Explain that a price is higher because the vendor changed",bucket:"note"},{id:"d4",text:"Ask Priya whether the order needs approval",bucket:"comment"}],explanation:"Dropdowns control what people enter, protection stops accidental edits, notes explain, and comments start a conversation."}]},{heading:"Sharing and downloading",blocks:[{type:"list",items:["Share a sheet the same way as any file: Share at the top right, add people, pick Viewer, Commenter, or Editor.","File › Download › Microsoft Excel (.xlsx) downloads every sheet as an Excel workbook.","File › Download › Comma Separated Values (.csv) saves plain data for another system. A CSV file holds one sheet of data with no formatting, so open the sheet you need first.","File › Version history shows earlier versions. Restoring a spreadsheet version clears the cell-by-cell edit history for earlier changes; make a copy instead if you need to keep that history."]}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You protected the Total column so only you can edit it. Can a coworker who can view the sheet copy those cells into another file?",options:["No, protection blocks copying","Yes. Protection stops edits, not copying, printing, or exporting","Only if they are an Editor","Only on a phone"],correctIndex:1,explanation:"Protection prevents accidental changes. It is not a way to keep data private.",optionRationales:["Copying is still possible.","Correct. Share only with people who should see the data.","Viewers can copy too.","Device does not matter."]},{type:"knowledge-check",question:"Priya's accounting system needs the current sheet as plain data. Which download?",options:["PDF","Comma Separated Values (.csv)","Microsoft Excel (.xlsx)","Web page"],correctIndex:1,explanation:"A CSV file is plain data, one sheet with no formatting, that most systems can import.",optionRationales:["A PDF is a picture of the page, not data a system can import.","Correct. CSV is plain data for other systems.","Excel keeps formatting and every sheet; use it when the person works in Excel.","A web page is for publishing, not importing."]}]}],challenge:[{type:"paragraph",text:"Finish your Budget Practice sheet."},{type:"list",ordered:!0,items:["Add a dropdown to the Category column with three or four categories.","Add a column named Paid with checkboxes.","Protect the cells with your SUM and AVERAGE formulas so only you can edit them.","Add a note to one cost explaining it.","Download the spreadsheet as Microsoft Excel (.xlsx) and open it to check it."]},{type:"callout",variant:"success",text:"Deliverable: Submit the .xlsx file to your instructor or course folder. No Google account? Complete the practice simulation and submit its results page."}]}],p="/images/google-workspace/module-5",q=(a,b)=>b.map((b,c)=>({src:`${p}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),r=[{slug:"start-a-presentation",title:"Start a Presentation in Google Slides",description:"Create and name a presentation, find your way around the Google Slides screen, pick a theme, and add slides with the right layouts.",objectives:["Create a Google Slides presentation from Google Drive and give it a clear name","Name the parts of the Slides screen: menus, toolbar, filmstrip, slide, speaker notes, Slideshow, and Share","Apply a theme and explain what a theme changes","Add slides, choose a layout for each one, and type into placeholders"],duration:"20 min",videoUrl:"https://www.youtube.com/embed/gmxkBPN2xhc",slides:q("start-a-presentation",["Google Slides: presentations that live in Google Drive","Create and name a presentation","The Google Slides screen","Themes: one choice styles every slide","New slide and Layout: pick the right layout for the content","Quick check: which layout?"]),sections:[{heading:"A presentation for new tenants",blocks:[{type:"scenario",role:"You are the office assistant at Parkview Property Management.",text:"Denise Carter, the office manager, wants a short welcome presentation for new tenants at Riverside Commons. It will play on the lobby screen, Denise will present it at tenant orientation, and new tenants will get a copy by email. Everyone at Parkview uses Google Workspace, so you build it in Google Slides.",task:"Start the presentation, give it a name people can find, choose a theme, and set up the first slides."},{type:"paragraph",text:"Google Slides is Google's presentation app, the Google Workspace counterpart to Microsoft PowerPoint. It runs in a web browser, saves every change automatically to Google Drive, and lets several people work on the same presentation at once. You can use it with a personal Google Account or a work or school account."},{type:"key-terms",terms:[{term:"Presentation",definition:"A Google Slides file. PowerPoint calls it a deck or a presentation, too."},{term:"Filmstrip",definition:"The column of slide thumbnails on the left. Select a thumbnail to work on that slide."},{term:"Theme",definition:"A matched set of colors, fonts, backgrounds, and layouts that styles every slide at once."},{term:"Layout",definition:"The arrangement of placeholders on a slide, such as Title and body or Title and two columns."},{term:"Placeholder",definition:"A box on a new slide that says Click to add title or Click to add text. Click it and type."},{term:"Speaker notes",definition:"Notes under the slide for the presenter. The audience doesn't see them."}]}]},{heading:"Create and name a presentation",blocks:[{type:"list",ordered:!0,items:["In Google Drive, open the folder the presentation belongs in (for Parkview, Riverside Commons).","Select New › Google Slides. Choose Blank presentation, or From a template to start from a design. (You can also go to slides.google.com and start a new presentation there.)","The new presentation opens in a new tab, named Untitled presentation. Click that name at the top left, type a name, and press Enter.","There's no Save button. Slides saves each change to Drive as you work."]},{type:"tip",text:"Name files so a coworker can find them by searching Drive: what it is, plus the building or date it's for. “New Tenant Welcome - Riverside Commons” is easy to find. “Untitled presentation” and “slides final v2” are not."}]},{heading:"The Google Slides screen",blocks:[{type:"image",src:`${p}/start-a-presentation/infographic.png`,alt:"Quick reference: the parts of the Google Slides screen, how to add slides and change layouts, and the main presenting and sharing buttons.",caption:"Google Slides at a glance."},{type:"table",caption:"Google Slides on a computer",columns:["Part","What it is for"],rows:[["Presentation name (top left)","Click it to rename the file"],["Menus","File, Edit, View, Insert, Format, Slide, Arrange, Tools, Extensions, Help"],["Toolbar","New slide, Undo, Insert image, Shape, Background, Layout, Theme, Transition, and text formatting"],["Filmstrip (left)","Thumbnails of every slide. Select one to edit it; drag to reorder. The buttons at the bottom left switch between filmstrip and grid view"],["Slide (center)","The slide you're editing"],["Speaker notes (under the slide)","Notes for the presenter"],["Slideshow (top right)","Present the slides. The arrow next to it has more ways to present"],["Share (top right)","Give other people access to the file"]]}]},{heading:"Choose a theme",blocks:[{type:"paragraph",text:"A theme styles the whole presentation at once: background, colors, fonts, and the look of every layout. Choose the theme early, before you style individual slides, so all slides match."},{type:"list",items:["Select Slide › Change theme (or Theme on the toolbar). The Themes panel opens on the right.","Select a theme to apply it to every slide. Close the panel when you're done.","Your organization may give you a branded theme or template. In the Themes panel, Import theme brings in the theme from another presentation.","To change the theme's colors for the whole file, use Slide › Edit theme. Changes there apply to every slide that uses the theme."]},{type:"callout",variant:"info",text:"PowerPoint users: Slides' themes work like the themes on PowerPoint's Design tab, and Slide › Edit theme is similar to PowerPoint's Slide Master view."}]},{heading:"Add slides and pick layouts",blocks:[{type:"list",items:["To add a slide, select New slide (+) at the top left. The new slide uses the same layout as the slide you're on.","To add a slide with a different layout, select the arrow next to New slide and choose the layout.","To change the layout of an existing slide, select the slide, then select Layout on the toolbar (or Slide › Apply layout) and choose a new one. Your text moves into the new placeholders.","Click a placeholder (Click to add title, Click to add text) and type. Text in a body placeholder becomes a bulleted list when you press Enter."]},{type:"drag-drop",mode:"match",title:"Which layout fits?",prompt:"Drag the best layout onto each slide in the welcome presentation.",items:[{id:"a",text:"The first slide: “Welcome to Riverside Commons” and Parkview's name",match:"Title slide"},{id:"b",text:"Three bullet points about the first week",match:"Title and body"},{id:"c",text:"Building A rules next to Building B rules",match:"Title and two columns"},{id:"d",text:"A divider slide before the section on rent and payments",match:"Section header"},{id:"e",text:"Just the lobby photo, nothing else",match:"Blank"}],explanation:"Pick the layout that matches the content: a title slide to open, title and body for a list, two columns to compare, a section header between topics, and blank for a full-slide picture."},{type:"worked-example",title:"Setting up the welcome presentation",task:"Create the presentation and the first two slides.",steps:[{move:"In Drive, open Riverside Commons, then New › Google Slides.",why:"Creating it inside the building's folder means it's filed, and shared, with that building's files from the start."},{move:"Rename it New Tenant Welcome - Riverside Commons.",why:"A clear name makes it easy to search for."},{move:"Choose the Streamline theme.",why:"Choosing a theme first styles every slide you add afterward."},{move:"Type the title on slide 1, then New slide › Title and body and type “Your First Week”.",why:"Each slide gets the layout that fits its content."}],result:"A named, themed presentation with a title slide and a first content slide.",takeaway:"Folder, name, theme, then slides: in that order, the file stays organized and consistent."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Where do you change a Google Slides file's name?",options:["File › Save as","Click the name at the top left, type, and press Enter","Slide › Edit theme","The name can only be changed in Microsoft PowerPoint"],correctIndex:1,explanation:"The presentation's name at the top left is a text box. Click it, type the new name, and press Enter. You can also rename it from Drive.",optionRationales:["Slides has no Save as. Changes save automatically.","Correct.","Edit theme changes colors and layouts, not the file name.","Slides files are renamed in Slides or Drive."]},{type:"knowledge-check",question:"You want every slide in the presentation to use the same colors and fonts. What's the quickest way?",options:["Format each slide by hand","Apply a theme","Use the Title slide layout everywhere","Download it as a PDF"],correctIndex:1,explanation:"A theme styles every slide at once, including slides you add later.",optionRationales:["That's slow, and slides you add later won't match.","Correct. A theme sets colors, fonts, and backgrounds for every slide.","A layout arranges placeholders on one slide; it doesn't set colors and fonts.","Downloading makes a copy; it doesn't change how slides look."]},{type:"knowledge-check",question:"Slide 4 has a title and bullet points, but you now want to compare two buildings side by side. What do you do?",options:["Delete the slide and start over","Select the slide and choose Layout › Title and two columns","Change the theme","Add a speaker note"],correctIndex:1,explanation:"Changing the layout keeps your text and rearranges the placeholders.",optionRationales:["You don't need to start over; the layout can change.","Correct.","The theme changes the look of every slide, not the arrangement of one.","Speaker notes are for the presenter; they don't change the slide."]}]}],challenge:[{type:"paragraph",text:"Build the start of a presentation in your own Google Account (a free personal account works) or your school account."},{type:"list",ordered:!0,items:["In Google Drive, create a folder named Slides Practice. In it, select New › Google Slides › Blank presentation.","Name the presentation “Welcome to [your town or school]”.","Apply any theme.","Add three more slides: one Title and body, one Title and two columns, and one Section header. Type a title on each.","Change the layout of one slide to a different layout."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot showing the presentation's name and the filmstrip with all four slides to your instructor or course folder. If you can't use Google Slides, complete the practice simulation and submit its results page."}]},{slug:"design-with-images-and-backgrounds",title:"Images, Shapes, and Backgrounds",description:"Insert and replace pictures, add shapes, change a slide's background, and duplicate, reorder, and delete slides.",objectives:["Insert an image from your computer, Drive, or the web, and replace it without losing its size and position","Add a shape and text box to a slide","Change the background of one slide, or of every slide through the theme","Duplicate, move, and delete slides in the filmstrip"],duration:"20 min",slides:q("design-with-images-and-backgrounds",["Make the slides look finished","Insert › Image: five places a picture can come from","Shapes and text boxes","Change background: one slide or the whole theme","Organize slides: duplicate, move, delete","Design checklist for a clear slide"]),sections:[{heading:"Pictures make the point",blocks:[{type:"scenario",role:"You're finishing the Riverside Commons welcome presentation.",text:"The words are in place, but the slides look plain. Denise sent you a photo of the Riverside Commons lobby, wants the Who to Call slide to stand out, and asks for a copy of the first-week slide that you can adapt for Elm Street Apartments.",task:"Add the photo, a shape, and a background color, and organize the slides."},{type:"list",ordered:!0,items:["Select the slide, then select Insert › Image (or Insert image on the toolbar).","Choose where the picture comes from: Upload from computer, Stock & web (stock images, GIFs, stickers, and Google images), Drive & Photos, Camera, or By URL.","Pick the image and select Insert or Open. Drag the image to move it; drag a corner handle to resize it.","To swap a picture and keep its size and place, right-click it, choose Replace image, and pick the new source and image."]},{type:"callout",variant:"warning",text:"Use only pictures you have the right to use: photos the company took, its logo, or images whose license allows it. A picture of a tenant or employee needs their permission before it goes on a lobby screen."}]},{heading:"Shapes and text boxes",blocks:[{type:"list",items:["Insert › Shape (or Shape on the toolbar) offers shapes, arrows, callouts, and equations. Choose one, then click or drag on the slide.","Insert › Text box adds text anywhere, outside the layout's placeholders.","With a shape selected, the toolbar shows Fill color and Border color. Type while a shape is selected to put text in it.","Arrange › Order brings an object forward or sends it behind others; Arrange › Align lines objects up."]}]},{heading:"Change the background",blocks:[{type:"list",ordered:!0,items:["Select the slide in the filmstrip.","Select Slide › Change background (or Background on the toolbar).","To the right of Color, click the box and pick a color. Or, to the right of Image, select Choose to use a picture.","Select Done to change only this slide, or select the Add to theme button to use that background for the whole presentation."]},{type:"tip",text:"Keep enough contrast between the text and the background. Dark text on a light background (or light on dark) is readable on a lobby screen from across the room; mid-tone on mid-tone isn't."}]},{heading:"Organize your slides",blocks:[{type:"table",caption:"Working with slides in the filmstrip",columns:["To","Do this"],rows:[["Duplicate a slide","Right-click it › Duplicate slide"],["Move a slide","Drag it to a new place in the filmstrip, or right-click › Move slide to end (or to the beginning)"],["Move several at once","Ctrl+click to select them, then drag"],["Delete a slide","Select it and press Delete, or right-click › Delete"],["See all slides at once","Grid view (button at the bottom left of the filmstrip)"]]},{type:"drag-drop",mode:"order",title:"Copy a slide for the other building",prompt:"Put the steps in order to make an Elm Street Apartments version of the First Week slide at the end of the presentation.",items:[{id:"1",text:"Select the First Week slide in the filmstrip"},{id:"2",text:"Right-click it and choose Duplicate slide"},{id:"3",text:"Right-click the copy and choose Move slide to end"},{id:"4",text:"Change Riverside Commons to Elm Street Apartments on the copy"}],explanation:"Duplicating keeps the layout, formatting, and text, so you only change what's different."}]},{heading:"Design for your audience",blocks:[{type:"drag-drop",mode:"sort",title:"Clear slide or cluttered slide?",prompt:"Sort each choice for a slide that tenants will read on a lobby screen.",buckets:[{id:"good",label:"Helps"},{id:"bad",label:"Gets in the way"}],items:[{id:"a",text:"Three short bullet points",bucket:"good"},{id:"b",text:"A full paragraph in small type",bucket:"bad"},{id:"c",text:"One clear photo of the laundry room",bucket:"good"},{id:"d",text:"Four different fonts on one slide",bucket:"bad"},{id:"e",text:"Dark text on a light background",bucket:"good"},{id:"f",text:"Yellow text on a white background",bucket:"bad"}],explanation:"Short text, one strong picture, consistent fonts (the theme's), and high contrast make a slide readable from a distance."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You want a new lobby photo in the exact spot and size of the old one. What's the fastest way?",options:["Delete the old photo, insert the new one, and resize it","Right-click the old photo › Replace image","Change the background","Duplicate the slide"],correctIndex:1,explanation:"Replace image swaps the picture and keeps its size and position.",optionRationales:["That works, but you have to size and place it again.","Correct.","A background goes behind everything; it doesn't replace a picture on the slide.","Duplicating copies the slide with the old photo still on it."]},{type:"knowledge-check",question:"In Change background, you choose a light blue color. What does Done do?",options:["Applies it to every slide","Applies it to the selected slide only","Saves the presentation","Applies it to the speaker notes"],correctIndex:1,explanation:"Done changes the selected slide. The Add to theme button changes the whole presentation.",optionRationales:["That's what Add to theme does.","Correct.","Slides saves automatically; Done applies the color to the selected slide.","Backgrounds apply to slides, not notes."]}]}],challenge:[{type:"paragraph",text:"Continue in the presentation you started in the last lesson (or create a new one)."},{type:"list",ordered:!0,items:["Insert a picture you took yourself, or one from Insert › Image › Stock & web.","Add a shape with a short label in it, such as “Office hours”.","Change the background of one slide only (Done). Then change another background with Add to theme and see what happens to the other slides.","Duplicate a slide, move the copy to the end, and delete one slide you don't need."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot in grid view showing your slides to your instructor or course folder. If you can't use Google Slides, complete the practice simulation and submit its results page."}]},{slug:"transitions-animations-and-notes",title:"Transitions, Animations, and Speaker Notes",description:"Add slide transitions and object animations in the Motion panel, control when animations start, and write speaker notes for whoever presents.",objectives:["Add a transition to one slide or to every slide","Animate an object, choose when the animation starts, and play it back","Show the speaker notes area and write notes for the presenter","Use motion so it helps the audience instead of distracting them"],duration:"20 min",slides:q("transitions-animations-and-notes",["Motion: transitions between slides, animations on objects","Add a transition: Slide › Transition","Animate an object: Insert › Animation","On click, After previous, With previous","Speaker notes: what to say, not what to show","Quick check: transition, animation, or note?"]),sections:[{heading:"Motion with a purpose",blocks:[{type:"scenario",role:"The welcome presentation will run two ways.",text:"On the lobby screen, the slides play by themselves, so bullet points can't wait for a click. At tenant orientation, Denise presents it and wants reminders of what to hand out and say. Both need gentle motion, not spinning text.",task:"Add a transition, animate the first-week list, and write speaker notes."},{type:"table",caption:"Two kinds of motion",columns:["","Transition","Animation"],rows:[["What moves","The whole slide, as it replaces the one before","One object on a slide: a text box, picture, or shape"],["Where to set it","Slide › Transition (or Transition on the toolbar)","Insert › Animation (or View › Motion)"],["Examples","Dissolve, Fade, Slide from right","Fade in, Fly in from left, Zoom in"],["PowerPoint","Transitions tab","Animations tab"]]}]},{heading:"Add a transition",blocks:[{type:"list",ordered:!0,items:["Select the slide in the filmstrip.","Select Slide › Transition. The Motion panel opens on the right.","Under Slide transition, choose a transition, such as Dissolve. Drag the speed slider to make it faster or slower.","To use the same transition everywhere, select Apply to all slides.","Select Play to preview it."]}]},{heading:"Animate an object",blocks:[{type:"list",ordered:!0,items:["Select the object on the slide, such as the bulleted text.","Select Insert › Animation (or View › Motion) to open the Motion panel. If no animation is listed for the object under Object Animations, select Add animation. New object animations are set to Appear (On click) by default.","Choose the animation you want from the drop-down, such as Fade in.","Choose when it starts: On click, After previous, or With previous. For text, check By paragraph to bring in one bullet at a time.","Drag the speed slider if needed, and select Play to preview."]},{type:"drag-drop",mode:"match",title:"When should it start?",prompt:"Drag the right start option onto each situation.",items:[{id:"a",text:"Denise wants each bullet to appear only when she's ready to talk about it",match:"On click"},{id:"b",text:"On the lobby screen, the list should appear by itself right after the slide arrives",match:"After previous"},{id:"c",text:"A photo and its caption should fade in at the same moment",match:"With previous"}],explanation:"On click waits for the presenter. After previous starts by itself when the previous animation (or the slide) finishes. With previous runs at the same time as the animation before it."},{type:"tip",text:"Use one or two kinds of motion for the whole presentation. If every slide spins, bounces, and flies, people watch the motion instead of reading the message."}]},{heading:"Speaker notes",blocks:[{type:"paragraph",text:"Speaker notes sit under each slide. They're for the presenter: reminders, details, and what to hand out. The audience doesn't see them during the slideshow. If the notes area is hidden, choose View › Show speaker notes, then click in it (it says Click to add speaker notes) and type."},{type:"worked-example",title:"Notes for the First Week slide",task:"Help whoever presents the welcome presentation cover everything on slide 2.",steps:[{move:"Keep the slide short: three bullet points.",why:"Tenants read the slide; the presenter adds the details."},{move:"In the notes, write “Hand out the key fob form here.”",why:"It's an action for the presenter, not something tenants need to read on screen."},{move:"Add the office phone hours to the notes.",why:"If someone asks, the presenter has the answer without adding clutter to the slide."}],result:"A clean slide for the audience, and a script for the presenter.",takeaway:"Put what the audience must see on the slide; put what the presenter must say or do in the notes."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You want the bullet points on slide 2 to appear one at a time when you click. What do you add?",options:["A slide transition","An animation on the text, starting On click, by paragraph","A speaker note","A new theme"],correctIndex:1,explanation:"An animation on the text box set to On click, with By paragraph checked, brings in one bullet per click.",optionRationales:["A transition moves the whole slide, not individual bullets.","Correct.","Notes are for the presenter; they don't change what's on screen.","A theme changes colors and fonts, not motion."]},{type:"knowledge-check",question:"What's the best use of speaker notes?",options:["Long paragraphs the audience should read","Reminders and details for the presenter","The presentation's title","A list of animations"],correctIndex:1,explanation:"Speaker notes are for the presenter and aren't shown on the audience's screen.",optionRationales:["The audience doesn't see the notes during the slideshow.","Correct.","The title belongs on the title slide.","Animations are listed in the Motion panel."]}]}],challenge:[{type:"paragraph",text:"In your own practice presentation:"},{type:"list",ordered:!0,items:["Add a transition to one slide, then select Apply to all slides.","Animate the text on one slide with Fade in, By paragraph, starting On click. Play it.","Write a speaker note on at least two slides.","Start the slideshow and click through the animated slide to check the timing."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot showing the Motion panel and a slide with speaker notes to your instructor or course folder. If you can't use Google Slides, complete the practice simulation and submit its results page."}]},{slug:"present-share-and-download",title:"Present, Share, and Download",description:"Skip slides you're not ready to show, present with presenter view or in Google Meet, share the presentation at the right access level, and download PowerPoint and PDF copies.",objectives:["Skip a slide so it doesn't appear in the slideshow","Present from the beginning and use presenter view with speaker notes","Present Google Slides in a Google Meet call","Share a presentation as Viewer, Commenter, or Editor, and download it as a PowerPoint or PDF file"],duration:"20 min",slides:q("present-share-and-download",["From draft to presentation","Skip a slide instead of deleting it","Slideshow and presenter view","Present in Google Meet","Share or download?","Presenter checklist"]),sections:[{heading:"Ready for orientation",blocks:[{type:"scenario",role:"The welcome presentation is almost done.",text:"A draft slide about parking isn't approved yet. Denise will present at orientation, sometimes over Google Meet for tenants who can't come in. Andre Wallace, the leasing agent, wants to suggest changes. The lobby screen needs a PowerPoint copy, and new tenants get a PDF by email.",task:"Hide the draft slide, rehearse, share with Andre, and make both downloads."},{type:"list",items:["To skip a slide, right-click it in the filmstrip and choose Skip slide. It stays in the file but doesn't appear in the slideshow. Choose it again to show the slide.","Skipping is safer than deleting a slide you'll need later: the content and its notes stay in the presentation."]}]},{heading:"Present your slides",blocks:[{type:"list",items:["Slideshow (top right) presents full screen from the slide you're on. The arrow next to Slideshow has Present from beginning and Presenter view.","Presenter view opens a separate window with your speaker notes, a timer, and the next slide, while the audience sees only the slides. It works best with a second screen or projector.","Move through the slides with the arrow keys. Home goes to the first slide and End to the last; type a slide number and press Enter to jump to it.","While presenting, press S to open speaker notes, L for the laser pointer, and B or W for a blank black or white screen (press any key to return).","Press Esc to stop presenting."]},{type:"callout",variant:"info",text:"Present in Google Meet (work or school accounts, in Chrome): in the Meet call, select Present now › A tab, choose the presentation's tab, and select Share. Then select Start slideshow in Meet. You can show your speaker notes and add a co-presenter. In PowerPoint and Teams, the matching step is sharing PowerPoint Live in the Teams meeting."},{type:"drag-drop",mode:"order",title:"Rehearse, then present",prompt:"Put Denise's steps in order for orientation day.",items:[{id:"1",text:"Right-click the draft parking slide › Skip slide"},{id:"2",text:"Arrow next to Slideshow › Presenter view, and read through the notes"},{id:"3",text:"End the rehearsal"},{id:"4",text:"Arrow next to Slideshow › Present from beginning"},{id:"5",text:"Press Esc when the last slide is done"}],explanation:"Hide what isn't ready, rehearse with your notes, then present from the first slide."}]},{heading:"Share or download?",blocks:[{type:"paragraph",text:"Share the Google Slides file when people should see the current version and work with you. Download a copy when someone needs a separate file: a PowerPoint for a screen that runs PowerPoint, or a PDF for people who only need to read it. A downloaded copy doesn't update when you change the original."},{type:"table",caption:"Choose the access level (see Module 2 for the full Share box)",columns:["Role","Can","Good for"],rows:[["Viewer","See the presentation","Staff who only need to watch or read it"],["Commenter","See it and add comments","Andre, who should suggest changes without changing slides"],["Editor","Change slides and share the file","Denise, who co-owns the work"]]},{type:"list",items:["Share: select Share (top right), type the person's name or email, choose Viewer, Commenter, or Editor, and select Send.","PowerPoint copy: File › Download › Microsoft PowerPoint (.pptx).","PDF copy: File › Download › PDF Document (.pdf)."]},{type:"drag-drop",mode:"match",title:"Share it or send a copy?",prompt:"Drag the best choice onto each request.",items:[{id:"a",text:"Denise will keep editing the presentation with you",match:"Share as Editor"},{id:"b",text:"Andre will leave suggestions in comments",match:"Share as Commenter"},{id:"c",text:"A new tenant needs a copy to read at home",match:"Download a PDF"},{id:"d",text:"The lobby screen only plays PowerPoint files",match:"Download a .pptx"}],explanation:"Share the Slides file with people who work on it. Send a PDF to people who only read it, and a .pptx when a PowerPoint file is required."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"A slide isn't approved yet, but you'll need it next week. What should you do before presenting?",options:["Delete it","Skip it","Move it to the end","Change its background"],correctIndex:1,explanation:"A skipped slide stays in the file but doesn't appear in the slideshow.",optionRationales:["Deleting removes the slide and its notes.","Correct.","It would still appear at the end of the slideshow.","Changing the background doesn't hide the slide."]},{type:"knowledge-check",question:"You want to see your speaker notes while the audience sees only the slides. What do you use?",options:["Slideshow","Presenter view","Grid view","File › Download"],correctIndex:1,explanation:"Presenter view shows your notes, a timer, and the next slide in a separate window.",optionRationales:["Slideshow shows only the slides.","Correct.","Grid view is for organizing slides while editing.","Downloading makes a copy of the file."]},{type:"knowledge-check",question:"Andre should be able to suggest changes in comments but not change the slides. Which role do you give him?",options:["Viewer","Commenter","Editor","Owner"],correctIndex:1,explanation:"Commenters can add comments but can't change the slides.",optionRationales:["Viewers can't add comments.","Correct.","Editors can change slides.","Ownership isn't needed to suggest changes."]}]}],challenge:[{type:"paragraph",text:"Finish your practice presentation in your own Google Account."},{type:"list",ordered:!0,items:["Skip one slide. Then start the slideshow from the beginning and check that it doesn't appear.","Open presenter view and practice with your speaker notes.","Share the presentation with a classmate (or a second account of your own) as a Commenter.","Download it as a PDF and as a PowerPoint (.pptx) file. Open the PDF to check it."]},{type:"callout",variant:"success",text:"Deliverable: Submit the PDF of your presentation and a screenshot of the Share box showing the Commenter to your instructor or course folder. If you can't use Google Slides, complete the practice simulation and submit its results page."}]}],s="/images/google-workspace/module-6",t=(a,b)=>b.map((b,c)=>({src:`${s}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),u=[{slug:"gmail-inbox-basics",title:"Find Your Way Around Gmail",description:"Learn the parts of the Gmail screen, how inbox tabs sort your mail, how stars and importance markers flag what matters, and when to archive a message instead of deleting it.",objectives:["Name the main parts of Gmail on a computer: Compose, the main menu, Search mail, Settings, inbox tabs, and the side panel","Explain what the Primary, Promotions, Social, Updates, and Forums tabs hold, move a message to another tab, and choose which tabs to show","Flag messages with stars and importance markers, and find them again","Decide whether to archive or delete a message, and find archived mail in All Mail and deleted mail in Trash"],duration:"20 min",videoUrl:"https://www.youtube.com/embed/l-WyP9iW_qE",slides:t("gmail-inbox-basics",["Gmail at work: the same app for personal and Google Workspace accounts","The Gmail screen: main menu, Compose, Search mail, Settings, tabs, side panel","Inbox tabs: Primary, Promotions, Social, Updates, Forums","Stars and importance markers: two ways to flag a message","Archive or delete? Archive keeps it in All Mail; Trash empties after 30 days","Quick check: archive, delete, or keep?"]),sections:[{heading:"Your new work inbox",blocks:[{type:"scenario",role:"You are the new office assistant at Parkview Property Management, a small company that manages apartment buildings.",text:"On your first morning, Denise Carter, the office manager, tells you the whole office runs on Google Workspace: email in Gmail, schedules in Google Calendar, files in Google Drive, and meetings in Google Meet. When you open Gmail, there are already messages from coworkers, a plumbing company, the water utility, and a store you have never heard of.",task:"Learn the Gmail screen well enough to sort a busy inbox in a few minutes."},{type:"paragraph",text:"Gmail is Google's email service. A personal Google Account has an address that ends in @gmail.com. A work or school account on Google Workspace uses the organization's own domain, such as jlee@parkviewpm.example. Either way, you use the same Gmail app in a web browser at mail.google.com, so what you practice here works for both."},{type:"key-terms",terms:[{term:"Google Workspace",definition:"Google's set of work apps (Gmail, Calendar, Drive, Docs, Sheets, Slides, Meet, Chat) that an organization manages for its people."},{term:"Conversation",definition:"A message and all of its replies, shown together. Gmail groups replies with the original message."},{term:"Inbox tabs (categories)",definition:"Primary, Promotions, Social, Updates, and Forums. Gmail sorts incoming mail into the tabs you turn on."},{term:"Archive",definition:"Removes a message from the inbox but keeps it. You can still find it in All Mail and by searching."},{term:"Trash",definition:"Where deleted messages go. You can recover them for up to 30 days; after that they are permanently deleted."},{term:"Star",definition:"A flag you add to a message so you can find it again under Starred."}]}]},{heading:"The parts of the Gmail screen",blocks:[{type:"image",src:`${s}/gmail-inbox-basics/infographic.png`,alt:"Quick reference: the parts of the Gmail screen, the five inbox tabs, and what archive, delete, star, and importance markers do.",caption:"Keep this quick reference handy while you learn Gmail."},{type:"table",caption:"Gmail on a computer, from left to right",columns:["Part","What it is for"],rows:[["App switcher (far left)","Switch between Mail, Chat, and Meet without leaving Gmail"],["Main menu (three lines)","Show or hide the list of mailboxes: Inbox, Starred, Snoozed, Sent, Drafts, and More (Important, Scheduled, All Mail, Spam, Trash), plus your labels"],["Compose","Start a new message"],["Search mail","Find messages by words, people, or search operators. Show search options opens a form for detailed searches and filters"],["Settings (gear)","Quick settings, such as which inbox tabs to show, and See all settings for everything else"],["Inbox tabs","Primary, Promotions, Social, Updates, and Forums (only the tabs you turn on appear)"],["Side panel (far right)","Open Calendar, Keep, Tasks, and Contacts next to your mail"]]},{type:"tip",text:"On a shared or public computer, sign out when you finish: select your profile picture or initial at the top right, then Sign out. Closing the tab can leave you signed in for the next person."}]},{heading:"Inbox tabs sort mail for you",blocks:[{type:"paragraph",text:"Gmail can sort incoming mail into tabs across the top of the inbox. Primary holds messages from people you know and anything that doesn't fit another tab. Promotions holds deals and offers. Social holds messages from social networks and media sites. Updates holds confirmations, receipts, bills, and statements. Forums holds messages from online groups and mailing lists. Gmail decides where each message goes, and you can correct it."},{type:"list",ordered:!0,items:["To move a message to the right tab, drag it from the message list onto the tab. A notice appears at the bottom left with Undo in case you dropped it in the wrong place.","To choose which tabs appear, select Settings (gear) at the top right. In Quick settings, under Inbox type, make sure Default is selected, then select Customize.","Select one or more tabs (categories) and select Save at the bottom of the window. To turn tabs off completely, choose a different inbox type."]},{type:"drag-drop",mode:"sort",title:"Which tab would Gmail use?",prompt:"Drag each message to the inbox tab it most likely lands in.",buckets:[{id:"primary",label:"Primary"},{id:"promotions",label:"Promotions"},{id:"social",label:"Social"},{id:"updates",label:"Updates"}],items:[{id:"a",text:"Denise Carter: “Welcome aboard, Jordan!”",bucket:"primary"},{id:"b",text:"Office Supply Depot: “30% off printer paper this week”",bucket:"promotions"},{id:"c",text:"City Water Utility: “Your October statement is ready”",bucket:"updates"},{id:"d",text:"Neighborly: “3 neighbors posted near Elm Street”",bucket:"social"},{id:"e",text:"Andre Wallace: “Showing at Elm Street Apartments moved to Thursday”",bucket:"primary"},{id:"f",text:"An online store: “Your order has shipped”",bucket:"updates"}],explanation:"Messages from people go to Primary. Deals go to Promotions, social network notices go to Social, and bills, receipts, and shipping notices go to Updates. If Gmail guesses wrong, drag the message to the right tab."},{type:"callout",variant:"info",text:"If you also use Outlook, the idea is similar to Outlook's Focused and Other tabs: the app sorts mail so the messages from people stand out. In Gmail you can have up to five tabs instead of two."}]},{heading:"Stars and importance markers",blocks:[{type:"paragraph",text:"A star is a flag you set yourself. To star a message, select the star to the left of it in the inbox, or open the message and select the star next to the date. Every starred message appears under Starred in the main menu, and you can search for is:starred."},{type:"paragraph",text:"The importance marker is the tag-shaped marker next to the star. Gmail fills it in yellow when it thinks a message matters, based on things like whom you email often and which messages you open and reply to. Select the marker to correct Gmail; that also teaches it what you consider important. Search for is:important to see every message marked important. If you don't want markers, go to Settings, See all settings, the Inbox tab, and choose No markers under Importance markers."},{type:"table",caption:"Star or importance marker?",columns:["","Star","Importance marker"],rows:[["Who sets it","You","Gmail, and you can correct it"],["Use it for","Messages you need to come back to: a task, a question to answer, a document to read","A signal that a sender or topic matters, so Gmail ranks similar mail higher"],["Find them","Starred in the main menu, or search is:starred","Search is:important (Important under More)"]]}]},{heading:"Archive or delete?",blocks:[{type:"paragraph",text:"Archiving takes a message out of the inbox without deleting it. It stays in All Mail, it still shows up when you search, and if someone replies, the conversation comes back to your inbox. Use Archive (the box with a down arrow, or the E key) for anything you are done with but might need later: a confirmation, an FYI, a finished conversation."},{type:"paragraph",text:"Deleting moves a message to Trash. You can recover it for up to 30 days: open Trash (under More), check the message, select Move to, and choose where it goes. After 30 days it is permanently deleted. Use Delete for things you will never need, such as an expired sale."},{type:"worked-example",title:"Clearing the inbox on your first morning",task:"Get the Parkview inbox down to the messages that still need you.",steps:[{move:"Open the Promotions tab and delete the printer paper sale.",why:"A sale email has no business value later, so it can go to Trash."},{move:"Archive Kim's FYI about the pest control visit.",why:"It needs no action, but the office might need to know when the visit happened. Archive keeps it searchable."},{move:"Star Denise's welcome message.",why:"It lists things to ask about this week, so you want to find it quickly under Starred."},{move:"Leave Andre's showing message in the inbox.",why:"It still needs a reply. The inbox works best as a to-do list of what still needs you."}],result:"The inbox holds only conversations that need action, and nothing useful was thrown away.",takeaway:"Archive what you are done with; delete only what you will never need; star what you must come back to."},{type:"drag-drop",mode:"sort",title:"Archive, delete, or keep in the inbox?",prompt:"Drag each message to the best action for the Parkview office.",buckets:[{id:"archive",label:"Archive"},{id:"delete",label:"Delete"},{id:"keep",label:"Keep in the inbox (still needs you)"}],items:[{id:"a",text:"Invoice receipt from Russo Plumbing that Priya already paid",bucket:"archive"},{id:"b",text:"Last week's expired coupon from an office supply store",bucket:"delete"},{id:"c",text:"A tenant asking when the hallway will be painted",bucket:"keep"},{id:"d",text:"Confirmation that the fire alarm inspection is booked",bucket:"archive"},{id:"e",text:"Grace Holloway asking for the roof estimate",bucket:"keep"},{id:"f",text:"A message you sent to yourself to test your new account",bucket:"delete"}],explanation:"Finished business records (paid invoices, confirmations) belong in the archive, where you can search for them later. Junk and tests can be deleted. Anything that still needs an answer stays in the inbox until you handle it."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You archived a message from Kim last week. Where can you find it now?",options:["In Trash","In All Mail, or by searching for it","Nowhere; archiving removes it from Gmail","Only in the Sent folder"],correctIndex:1,explanation:"Archiving only removes a message from the inbox. It stays in All Mail and still appears in search results.",optionRationales:["Trash holds deleted messages, not archived ones.","Correct. Archived mail stays in All Mail and shows up in searches.","Archive is the safe choice precisely because it keeps the message.","Sent holds messages you sent. Kim's message was sent to you."]},{type:"knowledge-check",question:"You deleted a vendor's message by mistake three days ago. What should you do?",options:["Nothing; deleted messages are gone immediately","Open Trash, check the message, select Move to, and choose Inbox","Ask the vendor to resend it; Trash can't be opened","Search All Mail; deleted messages stay there"],correctIndex:1,explanation:"Deleted messages stay in Trash for up to 30 days, so a message deleted three days ago can still be moved back.",optionRationales:["Messages stay in Trash for up to 30 days before Gmail permanently deletes them.","Correct. Move it out of Trash within 30 days and it's back.","You can open Trash from the main menu (under More) any time.","All Mail doesn't include Trash. Look in Trash itself."]},{type:"knowledge-check",question:"Which statement about stars and importance markers is true?",options:["Only Gmail can add stars","You add stars yourself; Gmail sets importance markers and you can correct them","Importance markers delete unimportant mail","Stars and importance markers are the same thing"],correctIndex:1,explanation:"Stars are your own flags. Importance markers are Gmail's guesses, and selecting a marker corrects Gmail and helps it learn.",optionRationales:["Stars are yours: select the star next to a message.","Correct.","Markers only flag messages; they never delete anything.","They look different and do different jobs: one is your flag, the other is Gmail's ranking."]}]}],challenge:[{type:"paragraph",text:"Practice in your own Gmail. Use a personal Google Account (you can create one for free at accounts.google.com) or your school account if it includes Gmail."},{type:"list",ordered:!0,items:["Open Gmail at mail.google.com. Write down which inbox tabs you see across the top.","Open Settings (gear) › Quick settings › Inbox type › Customize. Write down which tabs are checked, then select Cancel (or Save if you changed something on purpose).","Star one message you want to come back to. Open Starred to see it.","Archive one message you no longer need in the inbox. Then open More › All Mail and find it.","Write two sentences: when you would archive a work message, and when you would delete one."]},{type:"callout",variant:"success",text:"Deliverable: Submit your list of tabs, your two sentences, and a screenshot of the archived message in All Mail to your instructor or course folder. If you can't use Gmail on your computer, complete the practice simulation and submit its results page (Print or save results on the finish card)."}]},{slug:"compose-reply-forward",title:"Write, Reply, Forward, and Attach",description:"Compose clear messages, choose To, Cc, or Bcc, pick Reply, Reply all, or Forward, send files as attachments or Google Drive links, and undo a message you just sent.",objectives:["Compose a message and decide who goes in To, Cc, and Bcc","Choose Reply, Reply all, or Forward for the situation","Attach a file from your computer, and insert a Google Drive file as a link with the right access","Explain the 25 MB attachment limit for personal Gmail and what Gmail does with larger files","Undo a message right after you send it"],duration:"25 min",slides:t("compose-reply-forward",["Compose: To, Cc, Bcc, Subject, message, Send","To, Cc, or Bcc? Who acts, who needs to know, who stays private","Reply, Reply all, or Forward","Attachments and Drive links: the 25 MB rule","Undo Send: a few seconds to catch a mistake","Quick check: which reply button?"]),sections:[{heading:"Writing a new message",blocks:[{type:"scenario",role:"You are the office assistant at Parkview Property Management.",text:"Andre's showing moved to Thursday and the whole team needs to know. A plumbing invoice has to get to Priya, the bookkeeper. A tenant needs a repair notice, three tenants need the same water shutoff notice, and Denise wants a walkthrough video that is far too big to attach.",task:"Send each message to exactly the right people, with the right files, the first time."},{type:"list",ordered:!0,items:["At the top left, select Compose. A New Message window opens at the bottom right.","In To, type a name or address. Pick the person from the suggestions. To add more than one, put a comma between addresses.","To copy someone, select Cc. To add someone privately, select Bcc.","Add a short, specific subject, such as “Plumbing repair scheduled for Unit 4B”.","Write the message, then select Send at the bottom."]},{type:"table",caption:"To, Cc, or Bcc?",columns:["Field","Who goes here","Who can see it","Parkview example"],rows:[["To","People who need to read and act","Everyone on the message","Darnell, the tenant whose sink will be repaired"],["Cc","People who should know but don't need to act","Everyone on the message","Kim, the maintenance coordinator"],["Bcc","People whose addresses should stay private","Only you. Other recipients don't know they were added, and Reply all doesn't reach them","Three tenants getting the same shutoff notice"]]},{type:"callout",variant:"warning",text:"Tenant, customer, and client email addresses are private information. When you send one message to many people who don't know each other, put them in Bcc and put your own address (or the office's) in To."}]},{heading:"Reply, Reply all, or Forward",blocks:[{type:"paragraph",text:"Open a message, and below it you'll see Reply, Reply all (when there's more than one recipient), and Forward. Reply sends your answer only to the sender. Reply all sends it to the sender and everyone in the To and Cc lines. Forward sends the message, with its attachments, to someone new, and you can add a note at the top."},{type:"drag-drop",mode:"match",title:"Pick the right button",prompt:"Drag the right choice onto each situation.",items:[{id:"a",text:"Andre wrote to you, Denise, and Kim that a showing moved, and everyone needs your confirmation.",match:"Reply all"},{id:"b",text:"Denise welcomed you by email and copied the whole office. You want to thank her.",match:"Reply"},{id:"c",text:"A vendor sent you an invoice that Priya, the bookkeeper, must pay.",match:"Forward"},{id:"d",text:"You need to tell a tenant about a new parking rule, and there's no earlier email about it.",match:"Compose a new message"}],explanation:"Reply all only when everyone on the thread needs your answer. A thank-you goes to one person. Forward when someone who wasn't on the message needs it. A new topic gets a new message with its own clear subject."},{type:"tip",text:"Before you select Reply all, look at who is on the message. A reply meant for one person that goes to the whole office is one of the most common workplace email mistakes. You can change which button is the default in Settings › See all settings › General › Default reply behavior."}]},{heading:"Attachments and Google Drive links",blocks:[{type:"paragraph",text:"To attach a file from your computer, select Attach files (the paper clip) at the bottom of the compose window, choose the file, and select Open. In a personal Gmail account, attachments can total up to 25 MB; in a work or school account, your Google Workspace administrator sets the limit. If a file is larger than the limit, Gmail doesn't attach it. It adds a Google Drive link instead."},{type:"paragraph",text:"To share a file that's already in Google Drive, select Insert files using Drive (the Drive icon), pick the file, and select Insert. A Drive link works for any file in Drive, including Google Docs, Sheets, Slides, and Forms. Sending a Drive file as an attachment works only for files that weren't created in Docs, Sheets, Slides, or Forms. When you send, Gmail checks whether your recipients can open the file. If they can't, it prompts you to change the file's sharing settings first. If you choose Anyone with the link, you pick whether people can view, comment in, or edit the file; to limit access to the people on the email, select More options."},{type:"table",caption:"Attachment or Drive link?",columns:["","Attachment","Google Drive link"],rows:[["What the recipient gets","Their own copy of the file","A link to the one file in your Drive"],["Edits after you send","Your later changes don't reach them","They always see the current version"],["Size","Up to 25 MB in personal Gmail","Works for large files"],["Access","Anyone who gets the email has the copy","Only people you give access to can open it"]]},{type:"worked-example",title:"Sending the Tenant Handbook to a new applicant",task:"Rosa Delgado applied for an apartment and needs the Tenant Handbook, a Google Doc in the office Drive.",steps:[{move:"Compose a message to Rosa and select Insert files using Drive.",why:"The handbook is a Google Doc, so it can only be sent as a Drive link."},{move:"Pick Tenant Handbook and select Insert, then Send.",why:"Gmail checks access when you send."},{move:"Gmail prompts you to change the file's sharing settings. Select More options, limit access to the email's recipients, and give view access. Then send.",why:"Rosa needs to read the handbook, not change it. View access for just the people on the email keeps the office's copy safe; Anyone with the link would let anyone who gets the link open it."}],result:"Rosa can open and read the current handbook, and only the office can edit it.",takeaway:"Share Drive files with the least access the person needs: view to read, comment to suggest, edit only for coworkers who maintain the file."}]},{heading:"Undo Send",blocks:[{type:"paragraph",text:"Right after you select Send, a “Message sent” notice appears at the bottom left with Undo and View message. Select Undo and Gmail cancels the send and reopens your message so you can fix it. You only have a few seconds. To give yourself more time, go to Settings › See all settings and, next to Undo Send, choose a cancellation period of 5, 10, 20, or 30 seconds, then select Save Changes at the bottom."},{type:"callout",variant:"info",text:"Undo Send works because Gmail waits those few seconds before it actually sends. Once the period is over, the message is gone and can't be pulled back, so read it once more before you select Send."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You need to email 12 tenants about a parking lot repaving. They don't know each other. How should you address it?",options:["Put all 12 in To","Put all 12 in Cc","Put your own address in To and the 12 tenants in Bcc","Send 12 separate copies with Forward"],correctIndex:2,explanation:"Bcc keeps each tenant's address private, and Reply all from a tenant won't reach the others.",optionRationales:["Everyone in To can see everyone else's address.","Cc addresses are visible to everyone too.","Correct. Bcc protects their privacy.","Forward is for passing along a message you received. It's also slow and easy to get wrong."]},{type:"knowledge-check",question:"In your personal Gmail, you attach a 180 MB video. What happens?",options:["Gmail refuses to send anything","Gmail adds a Google Drive link instead of an attachment","Gmail shrinks the video to 25 MB","The video is split into several emails"],correctIndex:1,explanation:"Files over the 25 MB limit are sent as Google Drive links.",optionRationales:["Gmail offers Drive instead of failing.","Correct.","Gmail doesn't compress files.","Gmail doesn't split files across messages."]},{type:"knowledge-check",question:"Andre emailed you and Denise, with Kim in Cc. Only Andre needs your answer. Which button?",options:["Reply","Reply all","Forward","Compose"],correctIndex:0,explanation:"Reply goes only to the sender. Reply all would send your answer to Denise and Kim too.",optionRationales:["Correct.","Reply all includes everyone in To and Cc.","Forward sends the message to someone new.","A new message loses the thread's context."]}]}],challenge:[{type:"paragraph",text:"Use your own Gmail account. Send these messages to yourself (put your own address in To) so no one else receives practice mail."},{type:"list",ordered:!0,items:["Compose a message to yourself with the subject “Practice: attachment” and attach any small file from your computer. Send it.","Compose another message to yourself with the subject “Practice: Drive link”. Use Insert files using Drive to insert any file from your Google Drive (create a blank Google Doc first if your Drive is empty). Send it.","Open Settings › See all settings and set Undo Send to 30 seconds. Select Save Changes.","Send yourself a third message and select Undo in the “Message sent” notice. Notice that the message reopens. Then discard it.","Open your Sent folder and take a screenshot that shows the two practice messages."]},{type:"callout",variant:"success",text:"Deliverable: Submit the screenshot of your Sent folder and one sentence explaining when you would send a Drive link instead of an attachment. If you can't use Gmail, complete the practice simulations and submit their results pages."}]},{slug:"send-later-and-settings",title:"Schedule Send, Confidential Mode, Signatures, and Vacation Replies",description:"Schedule messages for later, protect sensitive messages with confidential mode, add a professional signature, and set up a vacation responder when you're away.",objectives:["Schedule a message to send later, find it in Scheduled, and cancel the send","Send a message in confidential mode and explain what it does and does not prevent","Create a signature and set it as the default for new messages and replies","Turn on the vacation responder for a date range and know how to end it"],duration:"25 min",videoUrl:"https://www.youtube.com/embed/M3zdSdW-0gs",slides:t("send-later-and-settings",["Schedule send: write now, deliver later","Confidential mode: expiration and passcodes","What confidential mode can't stop","A professional signature in four steps","The vacation responder: who gets it and when it ends","Quick check: which setting solves it?"]),sections:[{heading:"Schedule a message",blocks:[{type:"scenario",role:"You handle the office mailbox at Parkview Property Management.",text:"Denise likes owner reports to arrive Monday morning, even when you finish them on a Wednesday. Priya needs a heads-up about suspicious bank details without that message getting forwarded around. And you'll be away at a training next week, so people who email you need to know whom to contact.",task:"Use Gmail's sending options and settings so your mail works even when you aren't at your desk."},{type:"list",ordered:!0,items:["Write the message as usual.","Instead of selecting Send, select the arrow next to Send (More send options), then Schedule send.","Choose one of the suggested times, or select Pick date & time, set the date and time, and select Schedule send.","To check it, open Scheduled in the main menu (under More). The message waits there until it goes out.","To stop it, open the message in Scheduled and select Cancel send. The message goes back to Drafts so you can edit it or send it now."]},{type:"callout",variant:"info",text:"You can have up to 100 scheduled messages at a time. A scheduled message may go out a few minutes after the time you picked, and it's sent according to the time zone you chose when you scheduled it."}]},{heading:"Confidential mode",blocks:[{type:"paragraph",text:"Confidential mode adds limits to a message. Recipients can't forward, copy and paste, print, or download the message text and attachments, and you can make the message expire. To use it, select Toggle confidential mode (the lock with a clock) at the bottom of the compose window, choose an expiration date, choose whether recipients need an SMS passcode, and select Save."},{type:"table",caption:"Passcode options",columns:["Option","What the recipient does"],rows:[["No SMS passcode","Recipients can open the email directly in Gmail."],["SMS passcode","Gets a passcode by text message on their phone and enters it to open the email. You need their phone number."]]},{type:"callout",variant:"warning",text:"Confidential mode is not a lock. Recipients can still take screenshots or photos of the message. Don't treat it as permission to email information your office's policy says shouldn't be emailed at all, such as full bank account or Social Security numbers."}]},{heading:"Your signature",blocks:[{type:"paragraph",text:"A signature is the text added to the end of your messages: your name, title, company, and work phone. In Gmail on a computer, open Settings (gear) › See all settings. On the General tab, scroll to Signature, create your signature, and type the text. You can set a default signature for new emails and another for replies and forwards. Select Save Changes at the bottom of the page. A signature can be up to 10,000 characters, and images count toward that limit."},{type:"drag-drop",mode:"order",title:"Put the signature steps in order",prompt:"Drag the steps into the order you'd do them.",items:[{id:"1",text:"Select Settings (gear), then See all settings"},{id:"2",text:"On the General tab, scroll to Signature and select Create new"},{id:"3",text:"Name the signature and type your name, title, company, and phone"},{id:"4",text:"Under Signature defaults, choose it for new emails and for replies and forwards"},{id:"5",text:"Scroll to the bottom and select Save Changes"}],explanation:"Settings changes on the See all settings pages don't take effect until you select Save Changes at the bottom."},{type:"tip",text:"While writing a message, the Insert signature button (a pen) at the bottom of the compose window lets you switch signatures or remove the signature from that one message."}]},{heading:"The vacation responder",blocks:[{type:"paragraph",text:"The vacation responder sends an automatic reply while you're away. Open Settings › See all settings. On the General tab, find Vacation responder and select Vacation responder on. Enter the first day, an optional last day, a subject, and a message, and choose whether only people in your Contacts get the reply. Select Save Changes."},{type:"list",items:["Most people get the automatic reply only the first time they email you. If they write again more than four days later and the responder is still on, they get it again.","To stop it early, select End now on the banner across the top of your inbox.","If you set a last day, it ends at 11:59 PM that day.","A good away message says when you'll be back and whom to contact instead. Don't announce that your home is empty or share personal details."]},{type:"callout",variant:"info",text:"Outlook calls this feature automatic replies. The idea is the same: dates, a message, and an option to limit replies to people you know."},{type:"drag-drop",mode:"match",title:"Which Gmail feature solves it?",prompt:"Match each problem with the feature that solves it.",items:[{id:"a",text:"You finished the owner report Wednesday night, but it should arrive Monday at 8:00 AM.",match:"Schedule send"},{id:"b",text:"You'll be at a training all week and people need to know whom to contact.",match:"Vacation responder"},{id:"c",text:"Every message you send should end with your name, title, and the office phone.",match:"Signature"},{id:"d",text:"A note about a vendor's bank details shouldn't be forwarded and should expire.",match:"Confidential mode"},{id:"e",text:"You want 30 seconds to catch mistakes after selecting Send.",match:"Undo Send setting"}],explanation:"Each of these is a few clicks once you know where it lives: Schedule send is under the arrow next to Send, confidential mode is in the compose toolbar, and the others are in Settings › See all settings › General."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You scheduled a message for Monday, but the client asked for it today. What's the quickest fix?",options:["Delete it from Sent","Open it in Scheduled, select Cancel send, then send the draft now","Wait until Monday","Change your computer's clock"],correctIndex:1,explanation:"Cancel send returns the scheduled message to Drafts, where you can send it immediately.",optionRationales:["Scheduled messages aren't in Sent yet.","Correct.","The client wanted it today.","Gmail schedules on its servers; your clock doesn't matter."]},{type:"knowledge-check",question:"Which is true about confidential mode?",options:["Recipients can't take screenshots","It turns off forwarding, copying, printing, and downloading, but recipients can still take screenshots","It encrypts the message so no one at Google can see it","It only works with an SMS passcode"],correctIndex:1,explanation:"Confidential mode limits what recipients can do in Gmail, but it can't stop screenshots or photos.",optionRationales:["Google warns that screenshots and photos are still possible.","Correct.","That's not what confidential mode promises; it limits recipient actions.","No SMS passcode is an option too."]},{type:"knowledge-check",question:"Your vacation responder is on. A tenant emails you Monday and again Tuesday. How many automatic replies do they get?",options:["Two, one per message","One; most people get it only the first time, and again only after four days","None; tenants aren't in your Contacts","One per hour"],correctIndex:1,explanation:"Gmail replies once, then again only if the person writes after four days while the responder is still on (or after you edit the reply).",optionRationales:["Gmail avoids replying to every message.","Correct.","Only if you checked the Contacts-only option and they aren't a contact.","Gmail doesn't reply hourly."]}]}],challenge:[{type:"paragraph",text:"Use your own Gmail account for these steps, and send practice messages only to yourself."},{type:"list",ordered:!0,items:["Create a signature with your name and the line “BEOC Office Assistant student”. Set it as the default for new emails and select Save Changes.","Compose a message to yourself and schedule it for tomorrow morning. Open Scheduled and take a screenshot. Then cancel the send.","Compose a message to yourself in confidential mode that expires in 1 day. Send it, open it from your inbox, and notice what's missing (for example, the Forward option).","Turn on the vacation responder for any future date range with a short professional message. Take a screenshot of the settings, then turn it off and select Save Changes."]},{type:"callout",variant:"success",text:"Deliverable: Submit your three screenshots (Scheduled, the confidential message, and the vacation responder settings) to your instructor or course folder. If you can't use Gmail, complete the practice simulation and submit its results page."}]},{slug:"organize-labels-filters-search",title:"Organize with Labels, Filters, Search, and Snooze",description:"Use labels instead of folders, find any message in seconds with search operators, let filters sort mail as it arrives, and snooze messages until you need them.",objectives:["Create a label, apply it to a conversation, and explain how labels differ from folders","Find messages with search operators such as from:, subject:, has:attachment, and older_than:","Create a filter from your search and apply it to mail you already have","Snooze a message so it returns to your inbox when you need it"],duration:"25 min",videoUrl:"https://www.youtube.com/embed/1Z81HZNCuto",slides:t("organize-labels-filters-search",["Labels, not folders: one message can have several labels","Create and apply a label","Search operators: find anything in seconds","Filters: rules that sort mail as it arrives","Snooze: make a message come back later","Quick check: match the operator"]),sections:[{heading:"Labels instead of folders",blocks:[{type:"scenario",role:"You keep the Parkview office mailbox organized.",text:"Vendor invoices from Russo Plumbing and Bright Clean Services are scattered through the inbox. Denise wants all vendor mail in one place, out of the inbox, without losing anything, and Grace Holloway's question about the roof estimate shouldn't clutter your inbox until the estimate is ready.",task:"Set up Gmail so vendor mail sorts itself and nothing slips through the cracks."},{type:"paragraph",text:"Gmail organizes mail with labels. A label works like a tag: one conversation can have several labels, such as Vendors and Elm Street Apartments, and still be in the inbox. A folder can only hold a message in one place. Labels are private: only you see the labels you put on your mail, and the people you write to don't."},{type:"list",ordered:!0,items:["To create a label, on the left next to Labels, select Create new label (+). Enter a name and select Create. To put it inside another label, check Nest label under and pick the parent.","To label a conversation, check the box next to it (or open it), select Labels (the tag icon) at the top, check the label, and select Apply.","To move a conversation to a label, select Move to instead. Move to adds the label and takes the conversation out of the inbox.","To see everything with a label, select the label on the left."]},{type:"callout",variant:"info",text:"If you're used to Outlook, a Gmail label is like a folder you can use more than once, and a Gmail filter is like an Outlook rule."}]},{heading:"Search like a pro",blocks:[{type:"paragraph",text:"Type in Search mail at the top and press Enter. Plain words search everything. Search operators narrow it down. You can combine them: from:russo has:attachment finds only Russo Plumbing messages with attachments."},{type:"table",caption:"Search operators you'll use most",columns:["Operator","Finds","Example"],rows:[["from:","Mail from a person","from:priya"],["to:","Mail sent to a person","to:grace"],["subject:","Words in the subject","subject:invoice"],["has:attachment","Messages with attachments","from:russo has:attachment"],["filename:","Attachments by name or type","filename:pdf"],["is:unread / is:starred","Unread or starred mail","is:unread label:vendors"],["label:","Mail with a label","label:vendors"],["older_than: / newer_than:","Mail older or newer than a period (d, m, y)","older_than:1y"],['" " (quotes)',"An exact phrase",'"roof estimate"'],["- (minus)","Leave out a word","invoice -paid"],["in:anywhere","Include Spam and Trash","in:anywhere lease"]]},{type:"drag-drop",mode:"match",title:"Match the search to the job",prompt:"Drag each search onto what it finds.",items:[{id:"a",text:"Every message Priya sent you",match:"from:priya"},{id:"b",text:"Messages with a PDF attached",match:"filename:pdf"},{id:"c",text:"Mail with “invoice” in the subject",match:"subject:invoice"},{id:"d",text:"Messages older than one year",match:"older_than:1y"},{id:"e",text:"Unread messages",match:"is:unread"}],explanation:"Each operator ends in a colon, with no space before the value. Combine them with spaces to narrow your search."}]},{heading:"Filters sort mail as it arrives",blocks:[{type:"paragraph",text:"A filter is a rule Gmail runs on new mail. It checks each message against your search and then does what you chose: skip the inbox (archive it), mark it as read, star it, apply a label, forward it, delete it, never send it to Spam, always or never mark it as important, or put it in a category."},{type:"list",ordered:!0,items:["In the search box, select Show search options (the sliders icon).","Fill in what to look for, such as From: tony@russoplumbing.example. Select Search first if you want to preview the matches.","Select Create filter.","Check what the filter should do, for example Skip the Inbox (Archive it) and Apply the label: Vendors.","To sort the mail you already have too, check Also apply filter to matching conversations.","Select Create filter."]},{type:"paragraph",text:"You can also start a filter from a message: check the box next to it, select More (three dots), and choose Filter messages like these. To change or remove a filter later, go to Settings › See all settings › Filters and Blocked Addresses, and select edit or delete next to it."},{type:"callout",variant:"warning",text:"Be careful with Delete it and Skip the Inbox. A filter that's too broad (for example, everything with the word “invoice”) can hide messages you needed. Test the search first and look at what it finds."}]},{heading:"Snooze",blocks:[{type:"paragraph",text:"Snooze takes a message out of your inbox until a time you choose, then brings it back to the top of the inbox. Point to the message and select Snooze (the clock) on the right, or open it and select Snooze at the top. Choose a time such as Later today or Tomorrow, or pick a date and time. Snoozed messages wait under Snoozed in the main menu, and you can search for in:snoozed."},{type:"worked-example",title:"Organizing vendor mail",task:"Keep vendor mail together and out of the inbox.",steps:[{move:"Create a Vendors label.",why:"One place to see every vendor message, whichever building it's about."},{move:"Search from:russo has:attachment.",why:"Checks exactly which messages a Russo Plumbing filter would catch, before anything moves."},{move:"Create a filter: From tony@russoplumbing.example, Skip the Inbox, Apply the label Vendors, and apply it to matching conversations.",why:"Old and new invoices land under Vendors automatically, so the inbox stays a to-do list."},{move:"Snooze Grace's roof estimate question until tomorrow.",why:"You can't answer until the estimate arrives. Snooze brings it back when you can."}],result:"Vendor mail sorts itself, and the inbox shows only what needs you today.",takeaway:"Search first, then turn a good search into a filter."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How is a Gmail label different from a folder?",options:["A message can have several labels, and it can stay in the inbox","Labels delete mail after 30 days","Other people can see your labels","Labels only work on sent mail"],correctIndex:0,explanation:"Labels work like tags. A folder holds a message in one place; labels can overlap.",optionRationales:["Correct.","Labels never delete anything; Trash empties after 30 days.","Only you can see your labels.","Labels work on any conversation."]},{type:"knowledge-check",question:"Which search finds messages from Russo Plumbing that have attachments?",options:["russo attachment","from:russo has:attachment","has:russo from:attachment","subject:russo"],correctIndex:1,explanation:"from: names the sender and has:attachment requires an attachment.",optionRationales:["Plain words also match messages that just mention Russo Plumbing or attachments.","Correct.","The operators are swapped.","That only checks the subject line."]},{type:"knowledge-check",question:"You created a filter that skips the inbox, but last month's matching messages are still in your inbox. Why?",options:["Filters only work on Mondays","You didn't check Also apply filter to matching conversations","Filters only work in Outlook","The messages are too large"],correctIndex:1,explanation:"Filters run on new mail. To sort existing mail too, check Also apply filter to matching conversations when you create it.",optionRationales:["Filters run on every new message.","Correct.","Gmail filters work in Gmail.","Size doesn't matter unless your filter checks size."]}]}],challenge:[{type:"paragraph",text:"Organize part of your own Gmail."},{type:"list",ordered:!0,items:["Create a label named BEOC.","Search for messages from one sender who writes to you often, using from: and the sender's name or address. Write down the search you used.","Turn that search into a filter that applies the BEOC label (don't choose Delete it). Check Also apply filter to matching conversations.","Open the BEOC label and take a screenshot.","Snooze one message until tomorrow, and open Snoozed to see it."]},{type:"callout",variant:"success",text:"Deliverable: Submit your search, a screenshot of the BEOC label, and a screenshot of Snoozed to your instructor or course folder. If you can't use Gmail, complete the practice simulation and submit its results page."}]},{slug:"spam-phishing-safety",title:"Stay Safe: Spam, Phishing, and Unwanted Mail",description:"Spot phishing messages before they trick you, report phishing and spam, rescue real mail from Spam, block senders, and unsubscribe from mail you signed up for.",objectives:["Recognize the warning signs of a phishing message","Report a message as phishing or spam, and mark a real message as not spam","Block a sender and unsubscribe from mail you no longer want","Know what to do if you clicked a suspicious link"],duration:"20 min",slides:t("spam-phishing-safety",["Phishing: messages built to steal passwords and money","Five warning signs of phishing","Report phishing, report spam, or unsubscribe?","Rescue real mail from Spam","If you clicked a suspicious link","Quick check: phishing or real?"]),sections:[{heading:"What phishing looks like",blocks:[{type:"scenario",role:"You check the Parkview mailbox first thing every morning.",text:"Today there's a message from “Parkview IT Support” saying your mailbox will be deactivated in 24 hours unless you verify your account. There's also a gift card prize, a landlord newsletter you signed up for months ago, and a missing water bill that Priya is asking about.",task:"Decide which messages are dangerous, report them correctly, and make sure the real bill isn't lost in Spam."},{type:"paragraph",text:"Phishing is email (or a text or call) designed to trick you into giving away a password, money, or personal information, or into opening a harmful link or file. Gmail checks for phishing and warns you about many dangerous messages, but some get through, so you are the last line of defense. Google's own rule is simple: Gmail will never ask for your password or other personal information by email."},{type:"table",caption:"Warning signs",columns:["Sign","In the fake IT message"],rows:[["The sender's address doesn't match the name","“Parkview IT Support” but the address is it-support@parkview-pm-help.example, not parkviewpm.example"],["Urgency or a threat","“DEACTIVATED within 24 hours”"],["A request for a password or personal information","“Verify your account now”"],["A link that doesn't go where it says","Point to the link: it goes to parkview-pm-help.example"],["Too good to be true, or an unexpected fee","The gift card that needs a $4.99 “processing fee”"]]},{type:"tip",text:"On a computer, point to a link without clicking. The real address appears at the bottom of the browser window. If it doesn't match the company that supposedly sent the message, don't click."},{type:"drag-drop",mode:"sort",title:"Phishing or probably real?",prompt:"Drag each message to the right group. Look for the warning signs.",buckets:[{id:"phish",label:"Looks like phishing"},{id:"real",label:"Probably real"}],items:[{id:"a",text:"“Your mailbox will be deactivated. Enter your password here to keep it,” from a lookalike domain",bucket:"phish"},{id:"b",text:"Denise, from dcarter@parkviewpm.example: “Staff meeting moved to 2:00 PM”",bucket:"real"},{id:"c",text:"“You won a $500 gift card! Pay a $4.99 fee to claim it”",bucket:"phish"},{id:"d",text:"A vendor's “new bank details, please pay today” message you didn't expect",bucket:"phish"},{id:"e",text:"City Water, from billing@citywater.example: “Your October statement is ready” with no request for a password",bucket:"real"},{id:"f",text:"“IT here. Reply with your login so we can fix your account”",bucket:"phish"}],explanation:"Requests for passwords, payment pressure, prizes with fees, and lookalike addresses are classic phishing. Even a message that seems real deserves a second look if it asks you to change how money is paid; call the vendor at a number you already have."}]},{heading:"Report it the right way",blocks:[{type:"table",caption:"Which action?",columns:["The message is…","Do this","How"],rows:[["Trying to steal a password, money, or personal information","Report phishing","Open the message › More (three dots, next to Reply) › Report phishing"],["Junk you never asked for","Report spam","Check the box (or open it) › Report spam at the top"],["From someone you never want to hear from","Block the sender","Open the message › More › Block “sender”. Their future messages go to Spam."],["A newsletter or list you signed up for","Unsubscribe","Select Unsubscribe next to the sender's name (or Go to website)"],["Real mail that landed in Spam","Not spam","More › Spam › check the message › Not spam"]]},{type:"callout",variant:"warning",text:"Only unsubscribe from mail you actually signed up for. Selecting Unsubscribe (or any link) in a phishing or spam message can confirm that your address is active. For those, use Report phishing or Report spam instead."},{type:"paragraph",text:"Check Spam now and then. When a real message is there, such as a bill or a reply from a new tenant, mark it Not spam. That moves it to your inbox and helps Gmail sort similar mail correctly."}]},{heading:"If you clicked",blocks:[{type:"list",items:["If a page asks for your password, don't enter it. Close it and go to the real website by typing its address yourself.","If you already typed your password, change it right away from the real site (for a Google Account, at myaccount.google.com).","Review your recent security activity at myaccount.google.com/notifications.","Turn on 2-Step Verification so a stolen password alone can't open your account.","At work, tell your manager or IT contact right away. Reporting quickly protects the whole office."]}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"A message from “Gmail Team” says your account will close unless you reply with your password. What do you do?",options:["Reply with your password","Report phishing","Unsubscribe","Forward it to coworkers to warn them"],correctIndex:1,explanation:"Gmail never asks for your password by email. Report it as phishing.",optionRationales:["Never send a password by email.","Correct.","Unsubscribing from a scam can confirm your address is active.","Forwarding spreads the dangerous message. Report it, and tell IT or your manager."]},{type:"knowledge-check",question:"Priya says the water bill never arrived. Where should you look first?",options:["Trash","Spam","Sent","Drafts"],correctIndex:1,explanation:"Real mail sometimes lands in Spam. If it's there, mark it Not spam.",optionRationales:["Trash only holds mail someone deleted.","Correct.","Sent holds mail you sent.","Drafts holds your unsent messages."]},{type:"knowledge-check",question:"Which is the safest way to stop a newsletter you subscribed to on purpose?",options:["Report phishing","Unsubscribe next to the sender's name","Delete every issue","Reply STOP"],correctIndex:1,explanation:"For mail you signed up for, Unsubscribe is the right tool.",optionRationales:["It isn't phishing; you signed up.","Correct.","Deleting doesn't stop new issues.","Replying usually doesn't unsubscribe you."]}]}],challenge:[{type:"paragraph",text:"Practice spotting phishing without clicking anything dangerous."},{type:"list",ordered:!0,items:["In your own Gmail, open More › Spam. Without opening any links or attachments, look at three messages there. For each, write the sender's address and one warning sign you see.","Find one newsletter you signed up for but no longer read. Write down whether Gmail shows Unsubscribe next to the sender's name. (Unsubscribing is optional.)","Visit myaccount.google.com, select Security, and write down whether 2-Step Verification is on for your account."]},{type:"callout",variant:"success",text:"Deliverable: Submit your three sender addresses and warning signs, your newsletter note, and your 2-Step Verification status to your instructor or course folder. If you can't use Gmail, complete the practice simulation and submit its results page."}]}],v="/images/google-workspace/module-7",w=(a,b)=>b.map((b,c)=>({src:`${v}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),x=[{slug:"calendar-basics",title:"Plan Your Week in Google Calendar",description:"Move around Google Calendar, create events and tasks, add notifications, and use separate calendars so the office's schedule stays easy to read.",objectives:["Move around Google Calendar with Today, the arrows, the mini calendar, and the Day, Week, and Month views","Create an event by clicking a time or with Create, and add details with More options","Add a location and notifications, including an email notification, to an event","Add a task with a date and mark it complete","Create a new calendar and show or hide calendars"],duration:"20 min",videoUrl:"https://www.youtube.com/embed/wOgGpQLMbjg",slides:w("calendar-basics",["Google Calendar: the office's shared schedule","The Calendar screen: Create, Today, views, My calendars","Create an event in three clicks","Notifications: a pop-up, an email, or both","Tasks and separate calendars","Quick check: event, task, or appointment schedule?"]),sections:[{heading:"Your calendar at Parkview",blocks:[{type:"scenario",role:"You are the office assistant at Parkview Property Management.",text:"Denise Carter wants every inspection, showing, and vendor visit on a calendar, with reminders, so nothing depends on someone's memory. You also have your own to-dos, like ordering light bulbs for the Riverside Commons lobby.",task:"Set up Google Calendar so you can see the week at a glance and get reminded before anything starts."},{type:"paragraph",text:"Google Calendar opens at calendar.google.com, or from the Google apps menu in Gmail. Like Gmail, it works the same with a personal Google Account and a work account on Google Workspace. Your main calendar has your name, and you can add more calendars for different kinds of events."},{type:"table",caption:"The Google Calendar screen",columns:["Part","What it does"],rows:[["Create (top left)","Make a new Event, Task, or Appointment schedule"],["Mini calendar","Jump to any date"],["My calendars / Other calendars","Your calendars and ones shared with you. Check or uncheck a calendar to show or hide its events"],["Today and the arrows","Go back to today, or move to the previous or next day, week, or month"],["View menu (top right)","Switch between Day, Week, Month, and other views"],["Settings menu (gear)","Settings for time zones, notifications, and each calendar"]]},{type:"key-terms",terms:[{term:"Event",definition:"Something at a set time, such as a meeting, a showing, or an inspection."},{term:"Task",definition:"A to-do with a date (and optionally a time) that you check off when it's done."},{term:"Notification",definition:"A reminder before an event: a pop-up notification or an email."},{term:"Calendar",definition:"A group of events with its own color, such as Leasing Showings. You can show, hide, and share each one."}]}]},{heading:"Create an event",blocks:[{type:"list",ordered:!0,items:["Click an empty time on the calendar (or select Create, then Event, or press Shift + C).","Type a title in Add title and time and check the date and time.","Select Save. To add more details first, select More options.","For an event that lasts all day, such as a building's moving day, check All day."]},{type:"paragraph",text:"More options opens the full event page. There you can set the time, check All day, choose whether it repeats, add Google Meet video conferencing, add a location, set notifications, pick which calendar it belongs to, write a description, and add guests. Select Save at the top when you're done."},{type:"worked-example",title:"Booking the fire alarm inspection",task:"Put Thursday's fire alarm inspection at Riverside Commons on the calendar, with reminders.",steps:[{move:"Click 9:00 AM on Thursday, type “Fire alarm inspection, Riverside Commons”, and select Save.",why:"Clicking the time fills in the date and a one-hour slot, so only the title is left to type."},{move:"Open the event, select Edit event, and add the location.",why:"Anyone who opens the event sees where to go without asking."},{move:"Add an email notification 1 day before, and keep the 30-minute pop-up.",why:"The email gives a day to notify tenants; the pop-up is the last reminder before the inspector arrives."},{move:"Select Save.",why:"Changes on the event page aren't kept until you save."}],result:"The inspection is on the calendar with a location and two reminders.",takeaway:"Put everything with a time on the calendar, and add the reminders you'd need if you forgot it completely."}]},{heading:"Notifications",blocks:[{type:"paragraph",text:"To change the reminders on one event, open it, select Edit event, and under the notifications choose a notification (a pop-up on your screen or phone) or an email, and how long before. Select Add notification for another one, then Save. To change the reminders Calendar adds to every new event, open Settings, choose your calendar under Settings for my calendars, and edit Event notifications."},{type:"tip",text:"If pop-up notifications never appear on your computer, your browser may be blocking them. Allow notifications for calendar.google.com in your browser's site settings."}]},{heading:"Tasks and separate calendars",blocks:[{type:"paragraph",text:"A task is a to-do with a date. Select Create, then Task (or click a time and choose Task), type a title, set the date and an optional time, and select Save. Tasks with a date show on your calendar when Tasks is checked under My calendars. When you finish, open the task and mark it completed. You can also open Tasks from the side panel in Gmail and Calendar."},{type:"paragraph",text:"Separate calendars keep different kinds of events apart. To make one, next to Other calendars select Add other calendars (+), then Create new calendar. Give it a name and description, and select Create calendar. Each calendar gets its own color, and you can check or uncheck it to show or hide its events. To remove one from the list entirely, point to it and choose Options, then Hide from list."},{type:"drag-drop",mode:"sort",title:"Event, task, or appointment schedule?",prompt:"Drag each item to what you'd create in Google Calendar.",buckets:[{id:"event",label:"Event"},{id:"task",label:"Task"},{id:"appt",label:"Appointment schedule"}],items:[{id:"a",text:"Fire alarm inspection Thursday 9:00 to 10:00 AM",bucket:"event"},{id:"b",text:"Order lobby light bulbs by Friday",bucket:"task"},{id:"c",text:"Times tenants can book a 30-minute call with the office",bucket:"appt"},{id:"d",text:"Weekly staff huddle every Monday at 9:00 AM",bucket:"event"},{id:"e",text:"Renew the office's domain name before the end of the month",bucket:"task"},{id:"f",text:"Open slots for applicants to book apartment tours",bucket:"appt"}],explanation:"Events happen at a time. Tasks are things you check off by a date. Appointment schedules offer open times that other people book."},{type:"callout",variant:"info",text:"If you also use Outlook, its calendar works much the same way. Google Calendar's Tasks play the role that Microsoft To Do plays next to Outlook."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You want an email reminder the day before an inspection. Where do you set it?",options:["In Gmail's Settings","On the event: Edit event › notifications › Email, 1 day before › Save","In the mini calendar","You can't; Calendar only shows pop-ups"],correctIndex:1,explanation:"Each event can have several notifications, and each one can be a pop-up notification or an email.",optionRationales:["Gmail settings don't control event reminders.","Correct.","The mini calendar is for moving between dates.","Calendar offers email notifications too."]},{type:"knowledge-check",question:"What's the difference between hiding a calendar by unchecking it and choosing Hide from list?",options:["There's no difference","Unchecking hides its events for now; Hide from list removes it from the left panel","Unchecking deletes the calendar","Hide from list deletes its events"],correctIndex:1,explanation:"Unchecking is a quick on/off switch. Hide from list takes the calendar out of the list; you can bring it back from Settings.",optionRationales:["They do different things.","Correct.","Unchecking never deletes anything.","Hiding doesn't delete events."]}]}],challenge:[{type:"paragraph",text:"Use Google Calendar with your own Google Account."},{type:"list",ordered:!0,items:["Create an event called “Study session” for a time this week, with the location “BEOC”.","Edit it to add an email notification 1 day before. Save.","Create a task called “Finish Module 7 challenge” with a date.","Create a new calendar named “BEOC Classes” and move the study session to it (Edit event › choose the calendar › Save).","Take a screenshot of the week view showing the event in its new color and the task."]},{type:"callout",variant:"success",text:"Deliverable: Submit your screenshot to your instructor or course folder. If you can't use Google Calendar on your computer, complete the practice simulation and submit its results page (Print or save results on the finish card)."}]},{slug:"invite-and-find-a-time",title:"Invite Guests, Find a Time, and Answer Invitations",description:"Invite coworkers and clients, pick a time everyone is free with Find a time, add a Google Meet link, answer invitations, and schedule across time zones.",objectives:["Add guests to an event, mark a guest optional, choose guest permissions, and send invitations","Use Find a time to choose a time when your guests are free","Add Google Meet video conferencing to an event","Answer an invitation with Yes, No, or Maybe, and know where to add a note or propose a new time","Schedule an event in another time zone and show a secondary time zone on your calendar"],duration:"25 min",slides:w("invite-and-find-a-time",["Invite guests: Guests panel, optional guests, permissions","Find a time: everyone's busy times side by side","Add Google Meet video conferencing","Answer an invitation: Yes, No, or Maybe","Time zones: the event's zone and your secondary zone","Quick check: which answer or setting?"]),sections:[{heading:"Invite guests",blocks:[{type:"scenario",role:"You schedule meetings for Parkview's office.",text:"Denise wants a lease renewal review with Priya on Thursday, at the first hour all three of you are free. Grace Holloway, the owner of Riverside Commons, lives in Los Angeles and needs a call at a time that makes sense for her. And two invitations are waiting for your answer.",task:"Schedule meetings people can actually attend, and answer invitations so organizers know who's coming."},{type:"list",ordered:!0,items:["Open the event's full page (create the event and select More options, or open an event and select Edit event).","On the right, under Guests, start typing a name or email and choose the person.","To make someone optional, select Mark optional next to their name.","Under Guest permissions, choose whether guests can modify the event, invite others, or see the guest list.","Select Save. Calendar asks whether to send invitation emails to the guests; choose Send to email them."]},{type:"callout",variant:"info",text:"Guests answer Yes, No, or Maybe from the invitation email or from their own calendar. You'll see their answers on the event."}]},{heading:"Find a time",blocks:[{type:"paragraph",text:"After you add guests on the event page, open the Find a time tab. It shows your calendar and your guests' calendars side by side for that day, with busy times blocked out. Click a time when everyone is free and the event moves there. You can only see someone's busy times if they share their calendar with you or their calendar is shared within your organization; if not, you can ask them to share it."},{type:"worked-example",title:"Scheduling the lease renewal review",task:"Find the first free hour after 1:00 PM on Thursday for you, Denise, and Priya.",steps:[{move:"Create the event, name it, set Thursday, and select More options.",why:"Find a time is on the full event page."},{move:"Add Denise and Priya under Guests.",why:"Find a time can only show people who are on the guest list."},{move:"Open Find a time and look at the three columns after 1:00 PM.",why:"Denise is busy 1:00 to 2:00 and Priya is busy 3:00 to 4:00, so 2:00 to 3:00 is the first hour everyone is free."},{move:"Click 2:00 PM, add Google Meet video conferencing, and select Save, then Send.",why:"The Meet link lets anyone join from wherever they are, and the invitation puts it on their calendars."}],result:"A one-hour review on Thursday at 2:00 PM that everyone can attend, with a Meet link.",takeaway:"Add guests first, then use Find a time instead of trading emails about availability."},{type:"paragraph",text:"To add a video call to any event, select Add Google Meet video conferencing on the event. Calendar creates a meeting link that every guest can use; it appears on the event and in the invitation."}]},{heading:"Answer an invitation",blocks:[{type:"paragraph",text:"Open the event on your calendar and choose Yes, No, or Maybe next to Going?. You can also answer from the invitation email in Gmail. To explain your answer, select the arrow next to Maybe and choose Add note; your note is visible to all invitees. If the time doesn't work, choose Propose a new time from the same menu, pick a different time, and select Send proposal. (Propose a new time isn't available for all-day events or events with more than 200 guests.)"},{type:"drag-drop",mode:"match",title:"How would you answer?",prompt:"Drag the best response onto each invitation.",items:[{id:"a",text:"The weekly leasing huddle, and you're free",match:"Yes"},{id:"b",text:"An owner call that may overlap with a showing you can't move",match:"Maybe, with a note"},{id:"c",text:"A vendor demo during your vacation",match:"No"},{id:"d",text:"A meeting you must attend, but the time conflicts with a doctor's appointment",match:"Propose a new time"}],explanation:"Answer every invitation so the organizer can plan. A note or a proposed time saves a round of emails."}]},{heading:"Time zones",blocks:[{type:"paragraph",text:"Calendar shows events in your time zone, and each guest sees the event in their own time zone. When you schedule with someone in another zone, you can set the event in their zone: on the event page, select Time zone next to the time and choose theirs. To keep another zone in view, open Settings › General › Time zone, check Show additional time zones, and choose a Secondary time zone. It appears as a second column of times next to yours."},{type:"table",caption:"One call, two clocks",columns:["Grace Holloway in Los Angeles sees","You in New York see"],rows:[["1:00 PM to 1:30 PM Pacific Time","4:00 PM to 4:30 PM Eastern Time"]]},{type:"callout",variant:"warning",text:"Before you send an invitation across time zones, check the time on your own calendar. A call set for 1:00 PM in Los Angeles is 4:00 PM in New York."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Find a time shows Priya's whole day as unknown instead of free or busy. Why?",options:["Priya hasn't shared her calendar with you","Priya is on vacation","Find a time only works on Mondays","You forgot to add Google Meet"],correctIndex:0,explanation:"You can only see busy times on calendars shared with you or within your organization. You can ask Priya to share hers.",optionRationales:["Correct.","Vacation would show as busy if you could see her calendar.","Find a time works any day.","A Meet link doesn't affect availability."]},{type:"knowledge-check",question:"You can attend an owner call but might be 10 minutes late. What's the best answer?",options:["No","Ignore the invitation","Yes, with a note that you may be 10 minutes late","Delete the event"],correctIndex:2,explanation:"Answer and add a note (arrow next to Maybe › Add note) so the organizer knows what to expect.",optionRationales:["You can attend, so No is misleading.","Organizers rely on answers to plan.","Correct.","Deleting the event doesn't tell the organizer anything."]},{type:"knowledge-check",question:"Where do you add a second column of times for Pacific Time?",options:["Settings › General › Time zone › Show additional time zones","On every event's page","In Gmail's settings","In the mini calendar"],correctIndex:0,explanation:"A secondary time zone is a Calendar setting, and it shows on every day and week view.",optionRationales:["Correct.","The event page sets one event's zone, not your view.","Gmail doesn't control Calendar's view.","The mini calendar only picks dates."]}]}],challenge:[{type:"paragraph",text:"Use your own Google Calendar."},{type:"list",ordered:!0,items:["Create an event called “Practice video call” and select Add Google Meet video conferencing. Save it.","If a classmate or family member agrees, add their email as a guest and send the invitation. (Otherwise, skip this step.)","Open Settings › General › Time zone and add a secondary time zone for a city where someone you know lives.","Take a screenshot of your week view showing both time columns and the event with its Meet link open."]},{type:"callout",variant:"success",text:"Deliverable: Submit your screenshot and one sentence explaining when you'd use Find a time. If you can't use Google Calendar, complete the practice simulation and submit its results page."}]},{slug:"share-calendars-and-booking",title:"Share Calendars and Offer Bookable Appointments",description:"Share a calendar with coworkers at the right permission level, understand the risk of a public calendar, and set up an appointment schedule so people can book time with you.",objectives:["Share a calendar with specific people and choose the right permission level","Explain what making a calendar public does and when not to","Create an appointment schedule with a duration, weekly availability, and a booking form","Copy a booking page link to share"],duration:"20 min",slides:w("share-calendars-and-booking",["Share a calendar: Settings and sharing › Shared with","Five permission levels, from free/busy to manage sharing","Public calendars: visible to the world","Appointment schedules: open times others can book","Share your booking page","Quick check: which permission?"]),sections:[{heading:"Share a calendar",blocks:[{type:"scenario",role:"You keep the Leasing Showings calendar for Parkview.",text:"Andre Wallace, the leasing agent, needs to see every showing. Kim Nguyen needs to add and change showings when maintenance work moves them. And Denise is tired of tenants emailing back and forth to set up quick calls with the office.",task:"Give each person exactly the access they need, and let tenants book their own times."},{type:"list",ordered:!0,items:["In the left panel under My calendars, point to the calendar and select Options (three dots), then Settings and sharing.","On the left, select Shared with, then Add people and groups.","Type the person's email address or name.","Choose a permission level, then select Send."]},{type:"table",caption:"Permission levels",columns:["Permission","They can"],rows:[["See only free/busy (hide details)","See when you're busy, but not what the events are"],["See event details","See every event's details, but not change them"],["Make changes (see private events as free/busy)","Add and change events; private events show only as busy"],["Make changes and see event details","Add and change events and see all details"],["Make changes and manage sharing","Everything you can do, including sharing the calendar with others"]]},{type:"drag-drop",mode:"match",title:"Pick the permission",prompt:"Drag the permission each person needs onto their situation.",items:[{id:"a",text:"Andre needs to see what each showing is and where, but shouldn't change them.",match:"See event details"},{id:"b",text:"Kim moves and adds showings when repairs run long.",match:"Make changes and see event details"},{id:"c",text:"A vendor only needs to know when the office is busy.",match:"See only free/busy (hide details)"},{id:"d",text:"Denise, as office manager, decides who else gets access.",match:"Make changes and manage sharing"}],explanation:"Give each person the least access that lets them do their job. You can always raise it later."}]},{heading:"Public calendars",blocks:[{type:"paragraph",text:"In Settings and sharing, under Access permissions for events, Make available to public lets anyone see the calendar, including through Google search. That suits something like a community room's open hours. It doesn't suit a calendar with tenants' names, unit numbers, or anyone's personal appointments."},{type:"callout",variant:"warning",text:"Never make a calendar public if it holds names, addresses, phone numbers, or other personal details. Share it with specific people instead."}]},{heading:"Appointment schedules",blocks:[{type:"paragraph",text:"An appointment schedule offers open times that other people book on a booking page, so nobody has to email back and forth. You can create one with a personal Google Account or a Google Workspace account on a computer (not in the Calendar phone app). Some features need an eligible Google Workspace or Google One subscription, and a work account's administrator may need to turn it on."},{type:"list",ordered:!0,items:["Select Create, then Appointment schedule.","In the Bookable appointment schedule panel, add a title and choose the Appointment duration.","Under General availability, set the days and hours you're available each week.","Optionally set the Scheduling window (how far ahead people can book; the shortest notice is 4 hours by default) and Booked appointment settings such as buffer time and a daily limit.","Select Next. Choose the location or video conferencing, add a description, and set up the booking form. First name, last name, and email are always required; you can add items such as a phone number and require email verification.","Select Save."]},{type:"paragraph",text:"To share it, find it under Booking pages on the left side of Calendar, point to it, and select Copy link. Paste the link into an email or your website. A booking page is always public: anyone with the link can see the booking page, your profile photo, and your account name."},{type:"tip",text:"Give the schedule a title tenants will understand, such as “Tenant office hours”, and keep the description short: what the call is for and what to have ready."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"A coworker should be able to add events to your calendar but not share it with anyone else. Which permission?",options:["See only free/busy (hide details)","See event details","Make changes and see event details","Make changes and manage sharing"],correctIndex:2,explanation:"Make changes and see event details lets them edit events; only manage sharing lets them share the calendar.",optionRationales:["They couldn't add events.","They could only look.","Correct.","That would let them share the calendar too."]},{type:"knowledge-check",question:"Who can see your appointment schedule's booking page?",options:["Only people in your organization","Anyone who has the link","Only your Contacts","Nobody until you approve them"],correctIndex:1,explanation:"Booking pages are always public. Anyone with the link sees the page, your profile photo, and your account name.",optionRationales:["Booking pages aren't limited to your organization.","Correct.","There's no Contacts-only option.","People book directly from the page."]}]}],challenge:[{type:"paragraph",text:"Use your own Google Calendar on a computer."},{type:"list",ordered:!0,items:["Create an appointment schedule called “Study help” with 30-minute appointments on two weekday afternoons.","Add a phone number field to the booking form and save.","Under Booking pages, copy the link, paste it into a new browser tab, and take a screenshot of your booking page.","Optional: delete the schedule afterward if you don't want to keep it."]},{type:"callout",variant:"success",text:"Deliverable: Submit the screenshot of your booking page. If you can't create one, complete the practice simulation and submit its results page."}]},{slug:"join-and-take-part-in-meet",title:"Join and Take Part in a Google Meet Call",description:"Join Google Meet calls from Calendar, a link, or a code; check your camera and microphone; use captions, chat, reactions, and raise hand; present a tab or window; and leave cleanly.",objectives:["Join a Google Meet call from Google Calendar, a link, or a meeting code","Check your microphone, camera, and visual effects before you join","Use captions, chat, reactions, and raise hand during a call","Present a tab, a window, or your entire screen, and stop presenting","Change the layout, find Meeting tools, explain when recording is available, and leave the call"],duration:"25 min",videoUrl:"https://www.youtube.com/embed/9Y8BRUKQmqY",slides:w("join-and-take-part-in-meet",["Three ways to join a Google Meet call","Before you join: microphone, camera, effects","The Meet controls at the bottom of the screen","Present now: a tab, a window, or your entire screen","Layouts, Meeting tools, and recording","Quick check: which control?"]),sections:[{heading:"Join a call",blocks:[{type:"scenario",role:"You join Parkview's weekly leasing huddle from a busy front office.",text:"The huddle starts in two minutes. Coworkers are talking behind you, Andre will ask you about the showing calendar, and Denise wants you to share the lease renewal slides.",task:"Join on time, sound and look professional, take part without interrupting, and share only what you mean to share."},{type:"table",caption:"Three ways to join",columns:["From","Do this"],rows:[["Google Calendar","Open the event and select Join with Google Meet"],["A link in an email or chat","Click the meet.google.com link"],["A meeting code","Go to meet.google.com, type the code in Enter a code or nickname, and select Join"]]},{type:"paragraph",text:"You see a preview screen before you join. If you're on the invitation and signed in, select Join now. If you aren't on the invitation, or you aren't signed in to a Google Account, select Ask to join; someone in the meeting has to let you in."}]},{heading:"Before you join",blocks:[{type:"list",items:["Use the microphone and camera buttons on the preview to turn each one on or off. A red button means it's off.","Select Apply visual effects to blur your background or choose a background image, which hides a busy office or a home.","Use More options › Settings to pick a different microphone, speaker, or camera, and to test your speakers.","Then select Join now (or Ask to join)."]},{type:"tip",text:"Join with your microphone off in a noisy place, and turn it on when you speak. Keyboard shortcut: Ctrl + D turns the microphone on or off and Ctrl + E does the same for the camera."}]},{heading:"During the call",blocks:[{type:"image",src:`${v}/join-and-take-part-in-meet/infographic.png`,alt:"Quick reference: Google Meet controls for joining, getting ready, taking part, presenting, and leaving.",caption:"Google Meet controls at a glance."},{type:"table",caption:"Meet controls",columns:["Control","What it does"],rows:[["Microphone and camera","Turn your audio and video on or off"],["Turn on captions (CC)","Shows live captions at the bottom. Change their font and size in More options › Settings › Captions"],["Send a reaction","Shows an emoji such as a thumbs up for a moment, without interrupting"],["Present now","Share a tab, a window, or your entire screen"],["Raise hand (hand icon)","Lets the speaker know you have a question. It lowers when you speak, or select Lower hand"],["More options (three dots)","Change layout, full screen, visual effects, and settings"],["Leave call (red)","Leaves the meeting"],["Bottom right","Meeting details (joining info), People, Chat, and Meeting tools"]]},{type:"paragraph",text:"Select Chat at the bottom right to send messages to everyone in the call. Unless your organization uses continuous meeting chat, people who join late don't see earlier messages, and the messages disappear when the call ends, so don't put anything there that needs to be kept."},{type:"drag-drop",mode:"match",title:"Which control?",prompt:"Drag the control onto what you need to do.",items:[{id:"a",text:"You have a question but don't want to interrupt the speaker.",match:"Raise hand"},{id:"b",text:"It's hard to hear the speaker over the office noise.",match:"Turn on captions"},{id:"c",text:"You want to show your slides to everyone.",match:"Present now"},{id:"d",text:"You agree with Denise's point without speaking.",match:"Send a reaction"},{id:"e",text:"You need to post the link to the showing calendar.",match:"Chat"}],explanation:"Meet gives you quiet ways to take part: captions to follow along, reactions and chat to respond, and raise hand to get a turn."}]},{heading:"Present your screen",blocks:[{type:"list",ordered:!0,items:["Select Present now.","Choose A tab, A window, or Your entire screen.","Pick the tab or window and select Share.","When you're done, select Stop presenting."]},{type:"paragraph",text:"Presenting a tab shares that tab's sound too. For a window or your entire screen, turn on Also share system audio in the sharing window if people need to hear it. A meeting allows up to 10 presentations at the same time, and your organization's settings or the meeting host can turn presenting off."},{type:"callout",variant:"warning",text:"Share a tab or a window, not your entire screen, whenever you can. Your entire screen shows everything, including email notifications and any tenant information that pops up."}]},{heading:"Layouts, Meeting tools, and recording",blocks:[{type:"paragraph",text:"To change how people appear, select More options › Change layout. Auto (dynamic) is the default and adjusts to the meeting. Tiled (legacy) shows people in a grid. Spotlight fills the window with the speaker or the presentation. Sidebar shows the speaker or presentation large with others at the side."},{type:"paragraph",text:"Meeting tools at the bottom right holds features such as Recording. Recording is only available with certain Google Workspace editions (and Google One plans with 2 TB or more), and an administrator has to allow it; a free personal account can't record. When a meeting is recorded, the recording is saved to the organizer's Google Drive in a Google Meet folder."},{type:"callout",variant:"info",text:"If you use Microsoft Teams, the ideas carry over: Teams also has raise hand, reactions, live captions, chat, and sharing a window or screen."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You're joining from a loud front office. What should you do on the preview screen?",options:["Join with your microphone on","Turn off your microphone, consider blurring your background, then join","Turn off your camera and microphone and never turn them on","Leave and rejoin later"],correctIndex:1,explanation:"Start muted in a noisy place and turn the microphone on when you speak. A blurred background hides the busy office.",optionRationales:["Background noise disrupts the call.","Correct.","You'll need to speak when it's your turn.","Joining late isn't necessary."]},{type:"knowledge-check",question:"Which is the safest way to show one slide deck?",options:["Present now › Your entire screen","Present now › A tab, and choose the slides' tab","Email the slides during the call","Hold your phone up to the camera"],correctIndex:1,explanation:"Sharing one tab shows only that tab, so notifications and other windows stay private.",optionRationales:["Everything on your screen would be visible, including pop-ups.","Correct.","That doesn't let you walk people through it live.","That's hard to see and unprofessional."]},{type:"knowledge-check",question:"Can you record a Google Meet call with a free personal Google Account?",options:["Yes, always","No; recording needs an eligible Google Workspace edition or a Google One plan with 2 TB or more","Only on Mondays","Only if you're presenting"],correctIndex:1,explanation:"Recording depends on your edition and your administrator's settings.",optionRationales:["Recording isn't included with free personal accounts.","Correct.","Days don't matter.","Presenting doesn't affect recording."]}]}],challenge:[{type:"paragraph",text:"Try Google Meet with your own Google Account."},{type:"list",ordered:!0,items:["Go to meet.google.com, select New meeting, then Start an instant meeting. (You'll be the only one in it.)","Turn your microphone off and on, and blur your background with Apply visual effects or More options.","Turn on captions and say a sentence to see them appear.","Select Present now › A tab and share any tab. Then select Stop presenting.","Change the layout to Spotlight, take a screenshot, and leave the call."]},{type:"callout",variant:"success",text:"Deliverable: Submit your screenshot and one sentence about which Meet control you'll use most at work. If you can't use a camera or Meet on your computer, complete the practice simulations and submit their results pages."}]}],y="/images/google-workspace/module-8",z=(a,b)=>b.map((b,c)=>({src:`${y}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),A=[{moduleNumber:1,moduleSlug:"module-1",title:"Getting Started with Google Workspace",emoji:"\uD83E\uDDED",description:"Learn what Google Workspace is, sign in safely, move between Drive, Docs, Sheets, and Slides, and work with the Microsoft Office files people send you.",lessons:f,level:"Beginner",estimatedMinutes:80,whatYoullLearn:["What each Google Workspace app is for, and which Microsoft 365 app does the same job","How a personal Google account differs from a work or school account","How to sign in with 2-Step Verification and sign out safely on a shared computer","How to use the Google apps menu, app home screens, templates, and Search the menus","How to edit, convert, and download Word, Excel, and PowerPoint files in Google Workspace"],scenario:"You just started as the office assistant at Parkview Property Management, a small company that manages Elm Street Apartments and Riverside Commons. Everyone at Parkview works in Google Workspace. Your manager, Denise Carter, set up your account and wants you ready on day one: signing in on the shared front desk computer, finding the team's files, starting new ones, and handling the Word and Excel files that vendors and tenants still send."},{moduleNumber:2,moduleSlug:"module-2",title:"Google Drive: Organize and Share",emoji:"\uD83D\uDCC1",description:"Upload, organize, find, share, and recover files in Google Drive so the whole office can find the current version of anything in seconds.",lessons:i,level:"Beginner",estimatedMinutes:95,whatYoullLearn:["The parts of Drive: Home, My Drive, Shared drives, Shared with me, Starred, Trash, and Storage","How to upload files and folders and check a file's details","How to build folders, move and rename files, and use stars, colors, shortcuts, and copies","How to search Drive with words, filter chips, and search operators","How to share with the right role and general access, set expiration dates, and remove access","How Trash and storage work, and how to get a deleted file back"],scenario:"Parkview's Drive grew without a plan: scans sit on the front desk desktop, files for both buildings are loose in My Drive, and nobody is sure who can see what. Denise asks you to fix it. You upload the scans, build a folder system the whole office can follow, find files on request while she is on the phone, share each file with the right people at the right level, and clean up without losing anything the team needs."},{moduleNumber:3,moduleSlug:"module-3",title:"Google Docs",emoji:"\uD83D\uDCDD",description:"Write, format, structure, review, and send professional documents in Google Docs: notices, handbooks, updates, and letters.",lessons:l,level:"Beginner",estimatedMinutes:120,whatYoullLearn:["How to start documents from blank pages and templates and format text, paragraphs, and lists","How to structure long documents with headings, the tabs and outlines panel, a table of contents, headers, footers, page numbers, and page setup","How to add tables, images, smart chips, and building blocks, and how to use voice typing","How to review with comments, assignments, Suggesting mode, and version history","How to proofread, print, download, email, and copy a finished document"],scenario:"Parkview's documents are the office's voice: the water shutoff notice on the lobby board, the tenant handbook every new resident receives, the weekly maintenance update, the new pet policy, and the welcome letter for each move-in. You write and finish them all in Google Docs, working with Denise, Marcus, Kim, and Priya in the same files instead of emailing drafts back and forth."},{moduleNumber:4,moduleSlug:"module-4",title:"Google Sheets",emoji:"\uD83D\uDCCA",description:"Enter and format data, calculate with formulas and functions, sort and filter, chart and summarize, and keep shared spreadsheets clean in Google Sheets.",lessons:o,level:"Beginner to Intermediate",estimatedMinutes:135,whatYoullLearn:["How to enter, edit, and format data, freeze rows, and work with sheet tabs","How to write formulas, use SUM, AVERAGE, MAX, IF, and COUNTIF, and copy formulas with relative and absolute references","How to sort, filter, save filter views, add conditional formatting rules, and convert data to a table","How to build charts and pivot tables from your data","How to add dropdowns and checkboxes, protect ranges, use notes and comments, and download as Excel or CSV"],scenario:"Parkview runs on lists: the rent roll Priya keeps, the repair costs Kim tracks, the maintenance request log for both buildings, the numbers Marcus brings to the owners each month, and the supply order four people add to. You build and maintain these spreadsheets in Google Sheets so the numbers are right, easy to read, and safe from accidental changes while several people work in them at once."},{moduleNumber:5,moduleSlug:"module-5",title:"Google Slides",emoji:"\uD83D\uDDBC️",description:"Build a clear presentation in Google Slides: themes and layouts, pictures and backgrounds, gentle motion and speaker notes, then present it, share it, and download PowerPoint and PDF copies.",lessons:r,level:"Beginner",estimatedMinutes:80,whatYoullLearn:["How to create and name a presentation, apply a theme, and add slides with the right layouts","How to insert and replace pictures, add shapes, change backgrounds, and organize slides","How to add transitions and animations that help the audience, and write speaker notes","How to skip slides, present with presenter view or in Google Meet, share at the right access level, and download .pptx and PDF copies"],scenario:"Denise Carter wants a welcome presentation for new tenants at Riverside Commons: it plays on the lobby screen, she presents it at orientation, and new tenants get a copy by email. You build it in Google Slides from a blank file to the finished, shared presentation."},{moduleNumber:6,moduleSlug:"module-6",title:"Gmail",emoji:"✉️",description:"Run a work inbox in Gmail: sort and clean up mail, write and reply with the right recipients and files, schedule and protect messages, organize with labels and filters, and stay safe from phishing.",lessons:u,level:"Beginner",estimatedMinutes:115,whatYoullLearn:["The parts of Gmail, inbox tabs, stars, importance markers, and when to archive or delete","How to use To, Cc, and Bcc, choose Reply, Reply all, or Forward, and send attachments or Drive links","How to undo and schedule messages, use confidential mode, and set up a signature and vacation responder","How labels, search operators, filters, and Snooze keep a busy inbox under control","How to spot phishing, report spam and phishing, and rescue real mail from Spam"],scenario:"Parkview's office mailbox is now yours. Coworkers, tenants, the building owner, vendors, and a few scammers all write to you. Denise Carter wants every message answered by the right person with the right files, vendor mail organized without anyone sorting it by hand, and nothing dangerous clicked."},{moduleNumber:7,moduleSlug:"module-7",title:"Google Calendar & Google Meet",emoji:"\uD83D\uDCC5",description:"Plan the office's week in Google Calendar, invite people at times they're free, share calendars and booking pages, and take part in Google Meet calls with confidence.",lessons:x,level:"Beginner",estimatedMinutes:90,whatYoullLearn:["How to create events and tasks, add notifications, and use separate calendars","How to invite guests, use Find a time, add Google Meet, answer invitations, and work across time zones","How to share a calendar at the right permission level and set up an appointment schedule","How to join Meet calls, check your microphone and camera, use captions, chat, reactions and raise hand, and present a tab safely"],scenario:"Parkview runs on schedules: inspections at Riverside Commons, showings at Elm Street Apartments, owner calls, and the weekly leasing huddle on Google Meet. Denise Carter asks you to keep the calendars accurate and shared with the right people, book meetings at times that work for everyone, and run your part of each call smoothly."},{moduleNumber:8,moduleSlug:"module-8",title:"Working Together",emoji:"\uD83E\uDD1D",description:"Work as a team in Google Workspace: quick conversations in Google Chat, comments and assigned action items in shared files, version history for team mistakes, and a small project that brings Gmail, Chat, Drive, Calendar, and Meet together.",lessons:[{slug:"google-chat-and-spaces",title:"Message Your Team in Google Chat",description:"Use Google Chat for quick team conversations: direct messages, spaces, @mentions, reactions, and sharing Drive files with the right access.",objectives:["Open Google Chat in Gmail and start a direct message or a group message","Create a space and add people to it","Mention someone with @, and decide whether to add them to the space","Share a Google Drive file in a message and choose the access people get","Decide when a message belongs in Chat and when it belongs in email"],duration:"25 min",slides:z("google-chat-and-spaces",["Google Chat: quick conversations for your team","Direct messages and group messages","Spaces: a home for a team or project","@mentions: get one person's attention","Share a Drive file in Chat","Chat or email?"]),sections:[{heading:"Quick questions, without the email thread",blocks:[{type:"scenario",role:"You're coordinating the Riverside Commons lobby repaint.",text:"The repaint starts next week. Kim needs to check the lobby lights, Andre needs to know prospects should use the side door, and everyone needs the repaint schedule. Ten short emails would bury the office. Parkview uses Google Chat for quick team conversations like these.",task:"Send a direct message, post updates in the team space, share the schedule, and set up a new space."},{type:"paragraph",text:"Google Chat is Google's messaging app. You can use it at chat.google.com or inside Gmail: select Chat on the far left of Gmail. Chat has direct messages (DMs) between two or more people, and spaces, where a team or project keeps its conversation, files, and members in one place."},{type:"key-terms",terms:[{term:"Direct message (DM)",definition:"A private conversation with one person, or a group DM with a few people."},{term:"Space",definition:"A named place for a team or project conversation. People can be added or leave, and new members see the conversation."},{term:"@mention",definition:"Typing @ and a name in a message so that person gets a notification."},{term:"Reaction",definition:"An emoji you add to a message to answer without writing a new one."},{term:"Shortcuts",definition:"Home, Mentions, and Starred at the top of Chat's left side. Mentions lists messages where someone mentioned you."}]},{type:"callout",variant:"info",text:"Microsoft Teams users: Google Chat's direct messages are like Teams chats, and spaces are like channels in a team."}]},{heading:"Direct messages",blocks:[{type:"list",ordered:!0,items:["In Gmail, select Chat on the far left (or open chat.google.com).","Select New chat at the top left.","Enter a name or email address. For a group message, add more names.","Select Start chat, type your message in the box at the bottom, and select Send (or press Enter)."]},{type:"tip",text:"The first time you message someone, they may need to accept your message request before you can chat. If your work account allows chatting with people outside your organization, their names show an External badge, so you always know when a conversation includes outsiders."}]},{heading:"Spaces for teams and projects",blocks:[{type:"list",ordered:!0,items:["Select New chat › Create a space.","Enter a space name. You can also choose an emoji for the space's picture.","Select Create.","In the space, select Add people, pick the people, and select Add."]},{type:"paragraph",text:"A space keeps a project together: the conversation, the files people share, and the list of members. When the lobby repaint is over, the space still holds the whole history. With a personal Google Account you can create spaces for collaborating with others; work accounts may have more kinds of spaces, depending on your organization."},{type:"drag-drop",mode:"sort",title:"Direct message or space?",prompt:"Sort each conversation into the best place.",buckets:[{id:"dm",label:"Direct message"},{id:"space",label:"Space"}],items:[{id:"a",text:"Asking Kim whether she can check the lobby lights today",bucket:"dm"},{id:"b",text:"Daily updates about the lobby repaint for everyone working on it",bucket:"space"},{id:"c",text:"Telling Priya, privately, that a tenant's check bounced",bucket:"dm"},{id:"d",text:"A home for everything about Elm Street move-ins this fall",bucket:"space"},{id:"e",text:"Sharing the repaint schedule so the whole team can find it later",bucket:"space"}],explanation:"A direct message is for a quick or private exchange with one or a few people. A space is for a team or project, where new members can catch up and files stay together."}]},{heading:"Mentions, reactions, and files",blocks:[{type:"table",caption:"Everyday Chat actions",columns:["To","Do this"],rows:[["Get one person's attention","Type @ and their name, and pick them from the list. They get a notification."],["Mention someone who isn't in the space","Chat asks: Add member and send (adds them and notifies them) or Send message only."],["Notify everyone in the space","Type @all. Use it only when everyone really needs to see the message."],["Answer with an emoji","Point to the message and add a reaction."],["Share a Drive file","Type @ and part of the file name, and pick the file under Files. If someone can't open it, Chat asks you to select the type of access."],["Share a file from your computer","Upload file, or drag the file into the message box (up to 200 MB)."]]},{type:"worked-example",title:"Sharing the repaint schedule",task:"Get the schedule to everyone in the Riverside Commons Team space.",steps:[{move:"Type “Here's the repaint schedule.” then @Lobby, and pick Lobby Repaint Schedule under Files.",why:"The message carries a link to the one current file, not a copy."},{move:"Press Enter. Chat says some members can't open the file and asks for the type of access.",why:"Sharing in Chat also shares the file in Drive."},{move:"Choose Viewer and select Send.",why:"The team needs to read the schedule, not change it. Give the least access that does the job."}],result:"Everyone in the space can open the schedule, and it stays up to date when Denise changes it.",takeaway:"Share the Drive file, not a downloaded copy, and pick the access level on purpose."},{type:"callout",variant:"warning",text:"Chat is still work communication. Don't post tenants' private information, such as bank details or Social Security numbers, in a space, and remember that people added later can read the space's history."}]},{heading:"Chat or email?",blocks:[{type:"drag-drop",mode:"sort",title:"Which tool fits?",prompt:"Sort each message into Chat or email.",buckets:[{id:"chat",label:"Google Chat"},{id:"email",label:"Gmail"}],items:[{id:"a",text:"“Is the side door unlocked?” to a coworker",bucket:"chat"},{id:"b",text:"A formal lease renewal offer to a tenant",bucket:"email"},{id:"c",text:"A quick “Done!” when you finish a task for the team",bucket:"chat"},{id:"d",text:"An invoice question to Russo Plumbing",bucket:"email"},{id:"e",text:"Today's lobby repaint progress for the project team",bucket:"chat"},{id:"f",text:"A notice that every tenant must keep as a record",bucket:"email"}],explanation:"Chat is for quick, informal talk inside the team. Email is for people outside the company, formal messages, and anything someone needs to keep as a record."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You @mention Andre in a space he isn't in yet, and you want him to see the conversation. Which option do you choose?",options:["Send message only","Add member and send","Delete the message","Start a new email"],correctIndex:1,explanation:"Add member and send adds Andre to the space and notifies him.",optionRationales:["That sends the message without adding Andre, so he won't be in the space.","Correct.","You don't need to delete anything; Chat asks what to do.","Email would split the conversation into two places."]},{type:"knowledge-check",question:"Where should a project's ongoing team conversation go?",options:["A group email that everyone replies all to","A space with the project's team","A direct message with each person separately","A comment in a spreadsheet"],correctIndex:1,explanation:"A space keeps the conversation, members, and shared files together, and new members can catch up.",optionRationales:["Reply-all threads get long and people drop off them.","Correct.","Separate messages mean everyone sees a different part of the story.","Comments are for a specific part of a file, not a whole project."]},{type:"knowledge-check",question:"You share a Drive file in Chat, and Chat says some members can't open it. What does that mean?",options:["The file is broken","You need to choose the type of access to give them, or they won't be able to open it","Chat can only share files from your computer","Members must request access by email first"],correctIndex:1,explanation:"Chat checks the file's sharing and asks you to select the type of access for people who don't have it.",optionRationales:["The file is fine; it just isn't shared with everyone yet.","Correct.","Chat can share Drive files and files from your computer.","You can give access right from Chat."]}]}],challenge:[{type:"paragraph",text:"Practice with a classmate or a second Google Account of your own. Personal Google Accounts can use Google Chat at chat.google.com or in Gmail."},{type:"list",ordered:!0,items:["Start a direct message with your partner and send a short hello.","Create a space named “Study Group” and add your partner.","In the space, @mention your partner with a question, and add a reaction to their answer.","Share a Google Doc from your Drive in the space, giving your partner Commenter access.","Write two sentences: one message you'd send in Chat and one you'd send by email, and why."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of your space showing the mention, the reaction, and the shared file, plus your two sentences, to your instructor or course folder. If you can't use Google Chat, complete the practice simulation and submit its results page."}]},{slug:"comments-and-tasks-in-shared-files",title:"Comment, Assign, and Recover Work in Shared Files",description:"Work in the same Sheets and Slides files as your team: answer and resolve comments, assign action items, and use version history to recover from mistakes.",objectives:["Explain what happens when several people edit a Google file at the same time","Comment on a cell or slide, reply, and resolve a comment when it's handled","Assign an action item to a person with an @mention","Restore an earlier version and name versions at milestones","Choose between a comment, a suggestion, and a direct edit"],duration:"20 min",slides:z("comments-and-tasks-in-shared-files",["One file, many editors","Comments in Sheets and Slides","Assign an action item","Version history: undo a team mistake","Comment, suggest, or edit?","Quick check"]),sections:[{heading:"One file, many editors",blocks:[{type:"scenario",role:"You keep Parkview's Elm Street move-in tracker, a Google Sheets file the whole office edits.",text:"Priya asked a question in a comment. This morning someone cleared the Walkthrough column by mistake. And one new tenant still has no walkthrough on the schedule.",task:"Answer and resolve the comment, recover the lost dates, assign the open item, and mark the checked version."},{type:"paragraph",text:"When a file is shared with editors, everyone works in the same copy at the same time. Changes save automatically, and you can see who else has the file open by their pictures or initials at the top right. There's no “latest version” to email around: the file in Drive is always the latest."},{type:"callout",variant:"info",text:"Module 2 covered sharing and access levels, and Module 3 covered comments, suggestions, and version history in Google Docs. This lesson uses the same tools in Sheets and Slides, the way a team uses them day to day."}]},{heading:"Comments and action items",blocks:[{type:"list",items:["Select a cell (Sheets), or an object or slide (Slides), then select Insert › Comment or press Ctrl+Alt+M. Type and select Comment.","A cell with a comment shows a small mark in its corner. Select the cell to read the comment and reply.","To assign an action item, type @ and the person's name in the comment, check Assign to, and select Assign. They get an email, and they select Done on the comment when the task is finished.","When a comment is handled, select Resolve (the check mark in the top corner of the comment) to close it. Closed comments are listed under Comments at the top of the window, and Re-open brings one back.","People you mention need access to the file. Share it with them, or make sure it's already shared."]},{type:"drag-drop",mode:"order",title:"Assign the walkthrough to Kim",prompt:"Put the steps in order.",items:[{id:"1",text:"Select cell E5, Marisol Vega's Walkthrough cell"},{id:"2",text:"Insert › Comment (or Ctrl+Alt+M)"},{id:"3",text:"Type @Kim and pick Kim Nguyen, then finish the comment"},{id:"4",text:"Check Assign to Kim Nguyen"},{id:"5",text:"Select Assign"}],explanation:"The comment stays attached to the exact cell, and Kim gets an email about the action item."},{type:"callout",variant:"info",text:"Microsoft 365 has the same idea: in Word, Excel, and PowerPoint you can @mention someone in a comment, and in many versions you can assign it to them as a task. The habit carries over between the two."}]},{heading:"Version history: undo a team mistake",blocks:[{type:"list",ordered:!0,items:["Open version history: File › Version history › See version history, or select Last edit (the clock) at the top right.","Select a version on the right to see what the file looked like then, and who changed what.","Select Restore this version at the top, then select Restore.","At a milestone, name the version: File › Version history › Name current version. A spreadsheet can have up to 15 named versions; a document up to 40."]},{type:"tip",text:"Restoring an older version undoes every change made since then, not just the mistake. Check the newer versions first; if a coworker added something important after that point, copy it before you restore, or fix the mistake by hand instead."},{type:"worked-example",title:"Recovering the walkthrough dates",task:"Get back the Walkthrough column that was cleared at 9:40 AM.",steps:[{move:"Open version history and select October 20, 4:10 PM.",why:"That version still has every walkthrough date."},{move:"Check the 9:40 AM version.",why:"It shows the only change since then was clearing the column, so restoring loses nothing else."},{move:"Select Restore this version, then Restore.",why:"The tracker goes back to how it was on October 20, so the dates come back."},{move:"Name the current version “Checked by office”.",why:"If something goes wrong later, you can find this good version by name."}],result:"The tracker is back to normal in a minute, without retyping anything.",takeaway:"Before you restore, look at what changed since that version."}]},{heading:"Comment, suggest, or edit?",blocks:[{type:"drag-drop",mode:"match",title:"Pick the right way to give feedback",prompt:"Drag the best choice onto each situation.",items:[{id:"a",text:"You're not sure a move-in date in Andre's sheet is right",match:"Comment and @mention Andre"},{id:"b",text:"You'd reword a paragraph in Denise's Google Doc",match:"Suggesting mode"},{id:"c",text:"Your own tracker has a typo",match:"Edit directly"},{id:"d",text:"Kim must book a walkthrough",match:"Assign a comment to Kim"}],explanation:"Comments ask and discuss, assigned comments hand off a task, Suggesting mode (in Google Docs) proposes changes for the owner to accept, and you edit your own work directly."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How do you hand Kim a task about one cell in a shared sheet?",options:["Email her a screenshot","Comment on the cell with @Kim Nguyen and check Assign to","Type her name in the cell","Make a copy of the sheet for her"],correctIndex:1,explanation:"An assigned comment stays on the cell and emails Kim, and she marks it Done when the task is finished.",optionRationales:["A screenshot gets out of date and isn't linked to the cell.","Correct.","Kim won't get a notification, and it changes the data.","A copy splits the work into two files."]},{type:"knowledge-check",question:"Someone deleted a column in a shared sheet an hour ago. What's the best way to get it back?",options:["Ask everyone to retype it","Restore the version from before the deletion in version history","Undo (Ctrl+Z) on your computer","Download an old copy from your email"],correctIndex:1,explanation:"Version history keeps earlier versions of the file. Check what changed since then, then restore.",optionRationales:["Version history makes retyping unnecessary.","Correct.","Undo only reverses your own recent changes, not a coworker's.","An emailed copy may be older and wouldn't be the shared file."]}]}],challenge:[{type:"paragraph",text:"Practice with a classmate or a second Google Account of your own."},{type:"list",ordered:!0,items:["Create a Google Sheets file with a short list (for example, five tasks and who does each one). Share it with your partner as an Editor.","Comment on one cell, @mention your partner, check Assign to, and select Assign. Ask your partner to reply and mark it done.","Name the current version “Version 1”. Then delete a row, and restore Version 1 from version history.","Write two sentences: when you'd restore a version, and when you'd fix a mistake by hand instead."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of the resolved, assigned comment and a screenshot of version history showing Version 1, plus your two sentences, to your instructor or course folder. No partner? Complete the practice simulation and submit its results page."}]},{slug:"run-a-team-project",title:"Bring It Together: Run a Team Project",description:"Combine Gmail, Chat, Drive, Calendar, and Meet to start and run a small team project, choosing the right tool for each job.",objectives:["Choose the right Google Workspace tool for each kind of message or task","Start a project: reply by email, set up a Chat space, share the plan, and schedule a kickoff call","Name the Microsoft 365 tool that matches each Google Workspace app","Decide whether an AI assistant such as Gemini is available and appropriate for a task"],duration:"20 min",slides:z("run-a-team-project",["The right tool for each job","Kick off a project in four moves","Keep it running: habits that help the team","Google Workspace and Microsoft 365, side by side","AI helpers: check before you use","Project kickoff checklist"]),sections:[{heading:"The right tool for each job",blocks:[{type:"scenario",role:"Denise asks you to coordinate the Riverside Commons lobby repaint.",text:"Kim and Marcus will work on it with you. Denise wants a Chat space for the three of you, the Lobby Repaint Plan shared so they can comment on it, and a short kickoff call on Thursday morning.",task:"Answer Denise, set up the space, share the plan, and schedule the kickoff, each in the right tool."},{type:"image",src:`${y}/run-a-team-project/infographic.png`,alt:"Quick reference: which Google Workspace tool to use for each kind of team work, how to kick off a project, and the matching Microsoft 365 tools.",caption:"Working together in Google Workspace at a glance."},{type:"table",caption:"Which tool for what",columns:["Tool","Best for","At Parkview"],rows:[["Gmail","Formal messages, people outside the company, anything that needs a record","Notices to tenants, vendor invoices, owner reports"],["Google Chat","Quick, informal talk inside a team","“The side door is unlocked,” daily repaint updates"],["Comments","Feedback about one part of a file","A question on one cell of the move-in tracker"],["Google Drive","One shared copy of every file","The Lobby Repaint Plan everyone edits"],["Calendar and Meet","Meetings and decisions that need discussion","The Thursday kickoff call"]]},{type:"drag-drop",mode:"match",title:"Match the need to the tool",prompt:"Drag the best tool onto each need.",items:[{id:"a",text:"Tell Russo Plumbing the repaint dates",match:"Gmail"},{id:"b",text:"Ask Kim if the paint arrived",match:"Google Chat"},{id:"c",text:"Point out a wrong date on slide 3 of the plan",match:"A comment"},{id:"d",text:"Decide the color with Denise and Marcus together",match:"A Google Meet call"},{id:"e",text:"Give Kim and Marcus the latest plan",match:"Share the Drive file"}],explanation:"Outside people and records go by email; quick team questions go in Chat; feedback on a file goes in a comment; decisions that need discussion go to a meeting; and files are shared, not attached."}]},{heading:"Kick off a project",blocks:[{type:"list",ordered:!0,items:["Reply to the request so the person knows you're on it. Reply, not Reply all, unless everyone needs your answer.","Create a space for the project and add the team (Chat › New chat › Create a space, then Add people).","Share the plan in the space as a Drive file, with the access people need (Commenter if they should only comment).","Schedule the kickoff in Google Calendar: invite the team, use Find a time if needed, add Google Meet video conferencing, and send the invitations."]},{type:"drag-drop",mode:"order",title:"Put the kickoff in order",prompt:"Drag the steps into a sensible order.",items:[{id:"1",text:"Reply to Denise: “I'm on it.”"},{id:"2",text:"Create the Lobby Repaint space and add Kim and Marcus"},{id:"3",text:"Share the Lobby Repaint Plan in the space with Commenter access"},{id:"4",text:"Create the kickoff event with Google Meet and send the invitations"},{id:"5",text:"After the call, post the decisions in the space"}],explanation:"Confirm first, give the team a place to talk, share the plan, then meet. Posting decisions afterward keeps everyone, including people who missed the call, on the same page."}]},{heading:"Keep it running",blocks:[{type:"list",items:["Keep one conversation in one place. If a topic starts in email and moves to the space, say so in the email.","Mention people only when you need them, and use @all rarely.","Link to Drive files instead of attaching copies, so everyone has the latest version.","After a meeting, write down decisions and who does what, and assign comments or tasks for the open items.","When the project ends, name the final versions of its files."]},{type:"table",caption:"Google Workspace and Microsoft 365, side by side",columns:["Google Workspace","Microsoft 365"],rows:[["Gmail and Google Calendar","Outlook mail and calendar"],["Google Chat (DMs and spaces)","Microsoft Teams (chats and channels)"],["Google Meet","Microsoft Teams meetings"],["Google Drive and shared drives","OneDrive and SharePoint"],["Google Docs, Sheets, and Slides","Word, Excel, and PowerPoint"]]}]},{heading:"AI helpers: check before you use",blocks:[{type:"paragraph",text:"Some Google accounts include Gemini, Google's AI assistant. In Gmail it can summarize a long conversation, suggest replies, and help write a draft. Which features you get depends on your account: on personal accounts without a paid plan, some Gmail features (such as summaries, Help me write, and suggested replies) are available only in the United States, while paid Google AI plans and eligible Google Workspace editions include more. Your employer may turn these features off."},{type:"callout",variant:"warning",text:"Nothing in this course requires Gemini. If your job allows it, follow your company's rules about what information you may use with it, and read and check everything it writes before you send it. You are responsible for the message, not the tool."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You need to tell a vendor the repaint dates and keep a record. Which tool fits best?",options:["Google Chat","Gmail","A comment in the plan","A Meet call"],correctIndex:1,explanation:"Email is best for people outside the company and for anything that needs a record.",optionRationales:["Chat is for quick talk inside the team.","Correct.","The vendor doesn't work in Parkview's files.","A call leaves no written record of the dates."]},{type:"knowledge-check",question:"Kim and Marcus should be able to comment on the plan but not change it. How do you share it in the space?",options:["Attach a PDF","Share the Drive file with Commenter access","Share the Drive file with Editor access","Paste the plan into a message"],correctIndex:1,explanation:"Commenter access lets them add comments without changing the plan.",optionRationales:["A PDF is a copy that can't take comments in the shared file.","Correct.","Editors can change the plan.","Pasted text becomes a copy that won't update."]},{type:"knowledge-check",question:"Which Microsoft 365 tool matches Google Chat spaces?",options:["Outlook","Microsoft Teams channels","OneNote","Excel"],correctIndex:1,explanation:"Teams channels, like Chat spaces, hold a team's ongoing conversation and files.",optionRationales:["Outlook matches Gmail and Google Calendar.","Correct.","OneNote is a notebook app.","Excel matches Google Sheets."]}]}],challenge:[{type:"paragraph",text:"Run a mini project with a classmate (or a second Google Account of your own), such as planning a study session."},{type:"list",ordered:!0,items:["Create a Google Doc with a short plan and a space named after the project. Add your partner to the space.","Share the plan in the space with Commenter access, and ask your partner to add one comment.","Create a Google Calendar event for a 15-minute call, invite your partner, add Google Meet video conferencing, and send the invitation.","After the call, post a two-line summary of the decisions in the space."]},{type:"callout",variant:"success",text:"Deliverable: Submit screenshots of the space (with the shared plan and your summary) and of the calendar event to your instructor or course folder. No partner? Complete the practice simulation and submit its results page."}]}],level:"Beginner",estimatedMinutes:65,whatYoullLearn:["How to use Google Chat direct messages and spaces, @mentions, reactions, and Drive files with the right access","How to comment, assign action items, and resolve comments in shared Sheets and Slides files","How to recover from a teammate's mistake with version history and name versions at milestones","How to choose the right tool for each job and start a team project, with the matching Microsoft 365 tools"],scenario:"Parkview is repainting the Riverside Commons lobby and moving new tenants into Elm Street Apartments. You coordinate the team: messages in Google Chat, a shared move-in tracker, and a project kickoff that uses every app in this course."}].sort((a,b)=>a.moduleNumber-b.moduleNumber)}};